        private const string ProtectedCidSettingName = "ProtectedCID";

        public static int SavedCID
        {
            get
            {
                string storedValue = ReadFixedStringSetting(ProtectedCidSettingName, string.Empty);

                if (TryReadProtectedSetting(storedValue, "VATSIM CID", out string decryptedValue) &&
                    int.TryParse(decryptedValue, out int protectedCid) &&
                    protectedCid > 0)
                {
                    return protectedCid;
                }

                // Backwards compatibility: older builds stored CID as a plain integer setting.
                // The next successful save migrates it to the DPAPI-protected string setting.
                return Math.Max(0, Properties.Settings.Default.CID);
            }
            set
            {
                int cleanedValue = Math.Max(0, value);

                if (cleanedValue == 0)
                {
                    SaveFixedStringSetting(ProtectedCidSettingName, string.Empty);
                    Properties.Settings.Default.CID = 0;
                    return;
                }

                if (TryProtectStringForCurrentUser(cleanedValue.ToString(System.Globalization.CultureInfo.InvariantCulture), out string protectedValue))
                {
                    SaveFixedStringSetting(ProtectedCidSettingName, DpapiProtectedSettingPrefix + protectedValue);
                    Properties.Settings.Default.CID = 0;
                    return;
                }

                // Do not prevent the user from connecting if Windows DPAPI is unexpectedly unavailable.
                // Keep the legacy behaviour, but make the failure visible in the debug log.
                Logger.Debug("Could not protect VATSIM CID with Windows DPAPI; storing legacy plain setting.");
                SaveFixedStringSetting(ProtectedCidSettingName, string.Empty);
                Properties.Settings.Default.CID = cleanedValue;
            }
        }

        public static string SavedHoppieCode
        {
            get
            {
                string storedValue = Properties.Settings.Default.HoppieCode ?? string.Empty;

                if (TryReadProtectedSetting(storedValue, "Hoppie code", out string decryptedValue))
                {
                    return decryptedValue;
                }

                // Backwards compatibility: older builds stored this value as plain text.
                // The next successful save migrates it to the DPAPI-protected format.
                return storedValue.StartsWith(DpapiProtectedSettingPrefix, StringComparison.Ordinal)
                    ? string.Empty
                    : storedValue;
            }
            set
            {
                string cleanedValue = (value ?? string.Empty).Trim();

                if (string.IsNullOrWhiteSpace(cleanedValue))
                {
                    Properties.Settings.Default.HoppieCode = string.Empty;
                    return;
                }

                if (TryProtectStringForCurrentUser(cleanedValue, out string protectedValue))
                {
                    Properties.Settings.Default.HoppieCode = DpapiProtectedSettingPrefix + protectedValue;
                    return;
                }

                // Do not prevent the user from connecting if Windows DPAPI is unexpectedly unavailable.
                // Keep the legacy behaviour, but make the failure visible in the debug log.
                Logger.Debug("Could not protect Hoppie code with Windows DPAPI; storing legacy plain setting.");
                Properties.Settings.Default.HoppieCode = cleanedValue;

            }
        }

        public static string SimbriefID
        {
            get
            {
                string storedValue = Properties.Settings.Default.SimbriefUsername ?? string.Empty;

                if (TryReadProtectedSetting(storedValue, "SimBrief username", out string decryptedValue))
                {
                    return NormalizeSimbriefID(decryptedValue);
                }

                // Backwards compatibility: older builds stored this value as plain text.
                // The next successful save migrates it to the DPAPI-protected format.
                return storedValue.StartsWith(DpapiProtectedSettingPrefix, StringComparison.Ordinal)
                    ? string.Empty
                    : NormalizeSimbriefID(storedValue);
            }
            set
            {
                string cleanedValue = NormalizeSimbriefID(value);

                if (string.IsNullOrWhiteSpace(cleanedValue))
                {
                    Properties.Settings.Default.SimbriefUsername = string.Empty;
                    return;
                }

                if (TryProtectStringForCurrentUser(cleanedValue, out string protectedValue))
                {
                    Properties.Settings.Default.SimbriefUsername = DpapiProtectedSettingPrefix + protectedValue;
                    return;
                }

                // Do not prevent SimBrief from working if Windows DPAPI is unexpectedly unavailable.
                // Keep the legacy behaviour, but make the failure visible in the debug log.
                Logger.Debug("Could not protect SimBrief username with Windows DPAPI; storing legacy plain setting.");
                Properties.Settings.Default.SimbriefUsername = cleanedValue;
            }
        }

        private const string DpapiProtectedSettingPrefix = "dpapi:v1:";
        private const int CryptProtectUiForbidden = 0x1;

        [StructLayout(LayoutKind.Sequential)]
        private struct DataBlob
        {
            public int cbData;
            public IntPtr pbData;
        }

        [DllImport("crypt32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        private static extern bool CryptProtectData(
            ref DataBlob pDataIn,
            string szDataDescr,
            IntPtr pOptionalEntropy,
            IntPtr pvReserved,
            IntPtr pPromptStruct,
            int dwFlags,
            ref DataBlob pDataOut);

        [DllImport("crypt32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        private static extern bool CryptUnprotectData(
            ref DataBlob pDataIn,
            IntPtr ppszDataDescr,
            IntPtr pOptionalEntropy,
            IntPtr pvReserved,
            IntPtr pPromptStruct,
            int dwFlags,
            ref DataBlob pDataOut);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern IntPtr LocalFree(IntPtr hMem);

        private static bool TryReadProtectedSetting(string storedValue, string settingDisplayName, out string decryptedValue)
        {
            decryptedValue = string.Empty;

            if (string.IsNullOrEmpty(storedValue) ||
                !storedValue.StartsWith(DpapiProtectedSettingPrefix, StringComparison.Ordinal))
            {
                return false;
            }

            if (TryUnprotectStringForCurrentUser(storedValue.Substring(DpapiProtectedSettingPrefix.Length), out decryptedValue))
            {
                return true;
            }

            Logger.Debug("Saved " + settingDisplayName + " could not be decrypted for the current Windows user.");
            decryptedValue = string.Empty;
            return true;
        }

        private static bool TryProtectStringForCurrentUser(string value, out string protectedValue)
        {
            protectedValue = string.Empty;

            if (string.IsNullOrEmpty(value))
            {
                return true;
            }

            byte[] plainBytes = Encoding.UTF8.GetBytes(value);
            DataBlob inputBlob = new() { cbData = plainBytes.Length, pbData = Marshal.AllocHGlobal(plainBytes.Length) };
            DataBlob outputBlob = new();

            try
            {
                Marshal.Copy(plainBytes, 0, inputBlob.pbData, plainBytes.Length);

                if (!CryptProtectData(ref inputBlob, "EasyCPDLC Hoppie Code", IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, CryptProtectUiForbidden, ref outputBlob) ||
                    outputBlob.pbData == IntPtr.Zero ||
                    outputBlob.cbData <= 0)
                {
                    return false;
                }

                byte[] encryptedBytes = new byte[outputBlob.cbData];
                Marshal.Copy(outputBlob.pbData, encryptedBytes, 0, encryptedBytes.Length);
                protectedValue = Convert.ToBase64String(encryptedBytes);
                return true;
            }
            catch
            {
                protectedValue = string.Empty;
                return false;
            }
            finally
            {
                if (inputBlob.pbData != IntPtr.Zero)
                {
                    Marshal.FreeHGlobal(inputBlob.pbData);
                }

                if (outputBlob.pbData != IntPtr.Zero)
                {
                    LocalFree(outputBlob.pbData);
                }
            }
        }

        private static bool TryUnprotectStringForCurrentUser(string protectedValue, out string value)
        {
            value = string.Empty;

            if (string.IsNullOrWhiteSpace(protectedValue))
            {
                return true;
            }

            byte[] encryptedBytes;
            try
            {
                encryptedBytes = Convert.FromBase64String(protectedValue);
            }
            catch
            {
                return false;
            }

            DataBlob inputBlob = new() { cbData = encryptedBytes.Length, pbData = Marshal.AllocHGlobal(encryptedBytes.Length) };
            DataBlob outputBlob = new();

            try
            {
                Marshal.Copy(encryptedBytes, 0, inputBlob.pbData, encryptedBytes.Length);

                if (!CryptUnprotectData(ref inputBlob, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, CryptProtectUiForbidden, ref outputBlob) ||
                    outputBlob.pbData == IntPtr.Zero ||
                    outputBlob.cbData <= 0)
                {
                    return false;
                }

                byte[] plainBytes = new byte[outputBlob.cbData];
                Marshal.Copy(outputBlob.pbData, plainBytes, 0, plainBytes.Length);
                value = Encoding.UTF8.GetString(plainBytes);
                return true;
            }
            catch
            {
                value = string.Empty;
                return false;
            }
            finally
            {
                if (inputBlob.pbData != IntPtr.Zero)
                {
                    Marshal.FreeHGlobal(inputBlob.pbData);
                }

                if (outputBlob.pbData != IntPtr.Zero)
                {
                    LocalFree(outputBlob.pbData);
                }
            }
        }

        private const string SimbriefClientIdentifier =
            "EasyCPDLC-Modernized";

        private static string BuildSimbriefLatestOfpUrl(
            string pilotId)
        {
            string normalizedPilotId =
                NormalizeSimbriefID(pilotId);

            if (string.IsNullOrWhiteSpace(normalizedPilotId))
            {
                throw new InvalidOperationException(
                    "SimBrief Pilot ID is empty or invalid.");
            }

            return
                "https://www.simbrief.com/api/xml.fetcher.php" +
                "?userid=" +
                Uri.EscapeDataString(normalizedPilotId) +
                "&client=" +
                Uri.EscapeDataString(SimbriefClientIdentifier) +
                "&json=v2";
        }

        private static string ExtractSimbriefApiError(
            string responseBody)
        {
            string body = (responseBody ?? string.Empty).Trim();

            if (string.IsNullOrWhiteSpace(body))
            {
                return "EMPTY RESPONSE";
            }

            try
            {
                JToken parsed = JToken.Parse(body);

                string status =
                    parsed["fetch"]?["status"]?.ToString()
                    ?? parsed["status"]?.ToString()
                    ?? parsed["error"]?.ToString();

                if (!string.IsNullOrWhiteSpace(status) &&
                    !string.Equals(
                        status,
                        "Success",
                        StringComparison.OrdinalIgnoreCase))
                {
                    return status.Trim();
                }
            }
            catch
            {
                // Error responses may be XML even when JSON was requested.
            }

            try
            {
                string withoutTags =
                    Regex.Replace(
                        body,
                        "<[^>]+>",
                        " ");

                withoutTags =
                    Regex.Replace(
                        withoutTags,
                        @"\s+",
                        " ").Trim();

                if (!string.IsNullOrWhiteSpace(withoutTags))
                {
                    return withoutTags.Length > 120
                        ? withoutTags.Substring(0, 120)
                        : withoutTags;
                }
            }
            catch
            {
            }

            return "UNKNOWN API ERROR";
        }

        private static Navlog ParseSimbriefNavlog(
            string responseBody)
        {
            JObject root = JObject.Parse(responseBody);

            string fetchStatus =
                root["fetch"]?["status"]?.ToString();

            if (!string.IsNullOrWhiteSpace(fetchStatus) &&
                !string.Equals(
                    fetchStatus,
                    "Success",
                    StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "SimBrief: " + fetchStatus.Trim());
            }

            JToken navlogToken = root["navlog"];

            if (navlogToken == null ||
                navlogToken.Type == JTokenType.Null)
            {
                throw new JsonException(
                    "SimBrief response did not contain a navlog.");
            }

            // JSON v2 returns navlog directly as an array of fixes.
            // Legacy json=1 returned an object containing navlog.fix.
            JObject compatibleNavlog;

            if (navlogToken is JArray navlogArray)
            {
                compatibleNavlog =
                    new JObject(
                        new JProperty(
                            "fix",
                            navlogArray.DeepClone()));
            }
            else if (navlogToken is JObject navlogObject)
            {
                compatibleNavlog =
                    (JObject)navlogObject.DeepClone();
            }
            else
            {
                throw new JsonException(
                    "SimBrief navlog format is not supported.");
            }

            Navlog parsed =
                compatibleNavlog.ToObject<Navlog>();

            if (parsed?.fix == null ||
                !parsed.fix.Any())
            {
                throw new JsonException(
                    "SimBrief navlog did not contain route fixes.");
            }

            return parsed;
        }

        private async Task<Navlog> DownloadLatestSimbriefNavlogAsync(
            string pilotId,
            string diagnosticContext)
        {
            string url =
                BuildSimbriefLatestOfpUrl(pilotId);

            using HttpClient client =
                CreateShortTimeoutHttpClient();

            RecordUiDiagnosticActivity(
                "SimBrief flight-plan download");

            Stopwatch simbriefStopwatch =
                Stopwatch.StartNew();

            using HttpResponseMessage response =
                await client.GetAsync(url);

            string responseBody =
                await response.Content.ReadAsStringAsync();

            LogAsyncOperationDuration(
                string.IsNullOrWhiteSpace(diagnosticContext)
                    ? "SimBrief flight-plan download"
                    : "SimBrief flight-plan download (" +
                      diagnosticContext +
                      ")",
                simbriefStopwatch);

            if (!response.IsSuccessStatusCode)
            {
                string apiError =
                    ExtractSimbriefApiError(responseBody);

                throw new HttpRequestException(
                    "SimBrief HTTP " +
                    ((int)response.StatusCode)
                        .ToString(
                            System.Globalization.CultureInfo.InvariantCulture) +
                    ": " +
                    apiError);
            }

            return ParseSimbriefNavlog(responseBody);
        }

        private void ApplySimbriefNavlog(
            Navlog navlog)
        {
            if (navlog?.fix == null ||
                !navlog.fix.Any())
            {
                throw new JsonException(
                    "SimBrief navlog did not contain route fixes.");
            }

            simbriefData = navlog;

            reportFixes =
                simbriefData.fix
                    .Where(
                        fix =>
                            fix.is_sid_star == "0" &&
                            !new string[] { "apt" }
                                .Contains(fix.type))
                    .Select(fix => fix.ident)
                    .ToArray();

            UpdateFlightPhaseBadge();
        }

        private static string FormatSimbriefUserFacingError(
            Exception ex)
        {
            string message =
                (ex?.Message ?? "Unknown error")
                    .Trim();

            if (string.IsNullOrWhiteSpace(message))
            {
                return "UNKNOWN ERROR";
            }

            message =
                Regex.Replace(
                    message,
                    @"\s+",
                    " ").Trim();

            if (message.StartsWith(
                    "SimBrief ",
                    StringComparison.OrdinalIgnoreCase))
            {
                message =
                    message.Substring("SimBrief ".Length);
            }

            return (
                message.Length > 90
                    ? message.Substring(0, 90)
                    : message)
                .ToUpperInvariant();
        }

        private static string NormalizeSimbriefID(string value)
        {
            string cleaned = (value ?? string.Empty).Trim();
            return Regex.IsMatch(cleaned, @"^\d{1,7}$") ? cleaned : string.Empty;
        }

        private const string MessageTextSizeSettingName = "MessageTextSize";
        private const string AutoDeleteRequestSecondsSettingName = "AutoDeleteRequestSeconds";
        private const string WindowScalePercentSettingName = "WindowScalePercent";
        private const string MessageOverviewLskModeSettingName = "MessageOverviewLskMode";
        private const string MessagePreviewTextTag = "EASYCPDLC_MESSAGE_PREVIEW_TEXT";
        private const string A220PhysicalLayoutTag = "EASYCPDLC_A220_PHYSICAL_LAYOUT";

        // EasyCPDLC uses WQHD as its fixed design reference. Windows DPI is
        // deliberately not part of this calculation: AutoScaleMode remains None
        // and every UI dimension is derived only from monitor resolution plus the
        // user's EasyCPDLC 100/110/120 percent setting.
        private const int ReferenceScreenWidth = 2560;
        private const int ReferenceScreenHeight = 1440;
        private const float MinimumAutomaticResolutionScale = 0.60f;
        private static float automaticResolutionScaleFactor = 1.0f;

        private Rectangle resolutionScaleScreenBounds = Rectangle.Empty;
        private bool refreshingResolutionScale;
        private float appliedWindowScaleFactor = 1.0f;

        public static int WindowScalePercent
        {
            get
            {
                return NormalizeWindowScalePercent(ReadFixedStringSetting(WindowScalePercentSettingName, "100"));
            }
            set
            {
                SaveFixedStringSetting(
                    WindowScalePercentSettingName,
                    NormalizeWindowScalePercent(value.ToString(System.Globalization.CultureInfo.InvariantCulture)).ToString(System.Globalization.CultureInfo.InvariantCulture));
            }
        }

        private static int NormalizeWindowScalePercent(string value)
        {
            if (!int.TryParse((value ?? string.Empty).Trim().TrimEnd('%'), System.Globalization.NumberStyles.Integer, System.Globalization.CultureInfo.InvariantCulture, out int percent))
            {
                percent = 100;
            }

            int[] supported = { 100, 110, 120 };
            return supported.OrderBy(item => Math.Abs(item - percent)).First();
        }

        private static float UserWindowScaleFactor()
        {
            return Math.Max(1.0f, Math.Min(1.20f, WindowScalePercent / 100.0f));
        }

        private static float WindowScaleFactor()
        {
            return automaticResolutionScaleFactor * UserWindowScaleFactor();
        }

        private static float CalculateAutomaticResolutionScale(Rectangle screenBounds)
        {
            if (screenBounds.Width <= 0 || screenBounds.Height <= 0)
            {
                return 1.0f;
            }

            float widthFactor = screenBounds.Width / (float)ReferenceScreenWidth;
            float heightFactor = screenBounds.Height / (float)ReferenceScreenHeight;
            float resolutionFactor = Math.Min(widthFactor, heightFactor);

            // Higher resolutions never enlarge EasyCPDLC automatically. Users can
            // enlarge it explicitly with the program's 110/120 percent setting.
            return Math.Max(
                MinimumAutomaticResolutionScale,
                Math.Min(1.0f, resolutionFactor));
        }

        private Screen ResolveResolutionScaleScreen()
        {
            try
            {
                if (IsHandleCreated)
                {
                    return Screen.FromHandle(Handle);
                }

                if (Location != Point.Empty)
                {
                    return Screen.FromPoint(Location);
                }
            }
            catch
            {
            }

            return Screen.PrimaryScreen ?? Screen.AllScreens.FirstOrDefault();
        }

        private bool UpdateAutomaticResolutionScaleFactor(bool refreshUi)
        {
            Screen screen = ResolveResolutionScaleScreen();
            Rectangle screenBounds = screen?.Bounds ?? new Rectangle(
                0,
                0,
                ReferenceScreenWidth,
                ReferenceScreenHeight);

            float newFactor = CalculateAutomaticResolutionScale(screenBounds);
            bool changed =
                resolutionScaleScreenBounds != screenBounds ||
                Math.Abs(automaticResolutionScaleFactor - newFactor) > 0.0001f;

            resolutionScaleScreenBounds = screenBounds;

            if (!changed)
            {
                return false;
            }

            automaticResolutionScaleFactor = newFactor;
            Logger.Debug(
                DiagnosticLogMessage(
                    "Resolution UI scale updated: screen=" +
                    screenBounds.Width.ToString(System.Globalization.CultureInfo.InvariantCulture) +
                    "x" +
                    screenBounds.Height.ToString(System.Globalization.CultureInfo.InvariantCulture) +
                    ", automatic=" +
                    automaticResolutionScaleFactor.ToString("0.000", System.Globalization.CultureInfo.InvariantCulture) +
                    ", user=" +
                    WindowScalePercent.ToString(System.Globalization.CultureInfo.InvariantCulture) +
                    "%, effective=" +
                    WindowScaleFactor().ToString("0.000", System.Globalization.CultureInfo.InvariantCulture)));

            if (refreshUi &&
                !refreshingResolutionScale &&
                IsHandleCreated &&
                !IsDisposed &&
                !Disposing)
            {
                try
                {
                    refreshingResolutionScale = true;
                    RefreshWindowScaleUi();
                }
                finally
                {
                    refreshingResolutionScale = false;
                }
            }

            return true;
        }

        private void MainForm_ResolutionScaleLocationChanged(object sender, EventArgs e)
        {
            if (refreshingResolutionScale || !IsHandleCreated || IsDisposed)
            {
                return;
            }

            UpdateAutomaticResolutionScaleFactor(true);
        }

        private void MainForm_ResolutionScaleShown(object sender, EventArgs e)
        {
            UpdateAutomaticResolutionScaleFactor(true);
        }

        private IEnumerable<Control> EnumerateControlTreeIncludingRoot(Control root)
        {
            if (root == null)
            {
                yield break;
            }

            yield return root;

            foreach (Control child in root.Controls)
            {
                foreach (Control descendant in EnumerateControlTreeIncludingRoot(child))
                {
                    yield return descendant;
                }
            }
        }

        private void RescaleExistingControlFonts(
            float previousScaleFactor,
            float currentScaleFactor)
        {
            if (previousScaleFactor <= 0.0f ||
                currentScaleFactor <= 0.0f ||
                Math.Abs(previousScaleFactor - currentScaleFactor) < 0.0001f)
            {
                return;
            }

            float ratio = currentScaleFactor / previousScaleFactor;
            if (ratio <= 0.0f || Math.Abs(ratio - 1.0f) < 0.0001f)
            {
                return;
            }

            // Capture inheritance before changing any parent fonts. A child that
            // inherits its parent's Font must not receive a second explicit scale.
            List<(Control Control, Font Font, bool InheritsParentFont)> snapshots =
                new();

            foreach (Control control in EnumerateControlTreeIncludingRoot(this))
            {
                if (control == null || control.IsDisposed || control.Font == null)
                {
                    continue;
                }

                bool inheritsParentFont =
                    control.Parent != null &&
                    ReferenceEquals(control.Font, control.Parent.Font);

                snapshots.Add((control, control.Font, inheritsParentFont));
            }

            SuspendLayout();

            try
            {
                foreach ((Control control, Font oldFont, bool inheritsParentFont) in snapshots)
                {
                    if (control == null ||
                        control.IsDisposed ||
                        oldFont == null ||
                        inheritsParentFont)
                    {
                        continue;
                    }

                    float newSize = Math.Max(1.0f, oldFont.Size * ratio);
                    if (Math.Abs(newSize - oldFont.Size) < 0.05f)
                    {
                        continue;
                    }

                    try
                    {
                        control.Font = new Font(
                            oldFont.FontFamily,
                            newSize,
                            oldFont.Style,
                            oldFont.Unit,
                            oldFont.GdiCharSet,
                            oldFont.GdiVerticalFont);
                    }
                    catch (Exception ex)
                    {
                        Logger.Debug(
                            "Control font rescale skipped for " +
                            control.GetType().Name +
                            ": " +
                            ex.Message);
                    }
                }
            }
            finally
            {
                ResumeLayout(false);
            }
        }

        private static int ScaleUi(int value)
        {
            return (int)Math.Round(value * WindowScaleFactor(), MidpointRounding.AwayFromZero);
        }

        private static float ScaleUi(float value)
        {
            return value * WindowScaleFactor();
        }

        private static Size ScaleUiSize(Size value)
        {
            return new Size(ScaleUi(value.Width), ScaleUi(value.Height));
        }

        private int S(int value)
        {
            return ScaleUi(value);
        }

        private float SF(float value)
        {
            return ScaleUi(value);
        }

        private Point SP(Point value)
        {
            return new Point(S(value.X), S(value.Y));
        }

        private Size SS(Size value)
        {
            return ScaleUiSize(value);
        }

        private Padding SPad(Padding value)
        {
            return new Padding(S(value.Left), S(value.Top), S(value.Right), S(value.Bottom));
        }

        private Rectangle SR(Rectangle value)
        {
            return new Rectangle(S(value.X), S(value.Y), S(value.Width), S(value.Height));
        }

        private int BaseLogicalWidth(Control parent)
        {
            int parentWidth = parent?.ClientSize.Width ?? 0;
            if (parentWidth <= 0)
            {
                return 0;
            }

            return Math.Max(1, (int)Math.Round(parentWidth / WindowScaleFactor(), MidpointRounding.AwayFromZero));
        }

        private int BaseLogicalHeight(Control parent)
        {
            int parentHeight = parent?.ClientSize.Height ?? 0;
            if (parentHeight <= 0)
            {
                return 0;
            }

            return Math.Max(1, (int)Math.Round(parentHeight / WindowScaleFactor(), MidpointRounding.AwayFromZero));
        }

        private int BaseLogicalClientWidth(Control parent)
        {
            int baseWidth = BaseLogicalWidth(parent);
            return baseWidth > 0 ? baseWidth : (parent?.ClientSize.Width ?? 0);
        }

        private int BaseLogicalClientHeight(Control parent)
        {
            int baseHeight = BaseLogicalHeight(parent);
            return baseHeight > 0 ? baseHeight : (parent?.ClientSize.Height ?? 0);
        }

        private bool IsA220PhysicalLayout(Control parent)
        {
            if (!DcduStyleManager.IsA220)
            {
                return false;
            }

            Control current = parent;
            while (current != null)
            {
                if (string.Equals(
                    current.Tag as string,
                    A220PhysicalLayoutTag,
                    StringComparison.Ordinal))
                {
                    return true;
                }

                current = current.Parent;
            }

            return false;
        }

        private int ScaleChildX(Control parent, int x)
        {
            // A220 pages are composed with already-scaled physical coordinates.
            // Scaling those values a second time caused every form to drift at
            // 110/120 percent. Airbus/Boeing continue using logical coordinates.
            if (IsA220PhysicalLayout(parent))
            {
                return Math.Max(0, x);
            }
            int parentWidth = parent?.ClientSize.Width ?? 0;
            int baseWidth = BaseLogicalWidth(parent);

            // Calls like page.Width - 160 are already based on the scaled parent
            // width. Treat those as right-margin anchored. Normal fixed x values
            // like 154/252 remain ordinary scaled coordinates.
            if (parentWidth > 0 && baseWidth > 0 && x > baseWidth)
            {
                return Math.Max(0, parentWidth - S(parentWidth - x));
            }

            return S(x);
        }

        private int ScaleChildX(Control parent, int x, int width)
        {
            if (IsA220PhysicalLayout(parent))
            {
                return Math.Max(0, x);
            }

            int parentWidth = parent?.ClientSize.Width ?? 0;
            int baseWidth = BaseLogicalWidth(parent);

            // Right-aligned calls usually look like x = page.Width - margin.
            // They are below the current scaled width, but x+width exceeds the
            // unscaled logical width. Keep the right margin stable.
            if (parentWidth > 0 && baseWidth > 0 && x > baseWidth / 2 && x + width > baseWidth)
            {
                return Math.Max(0, parentWidth - S(parentWidth - x));
            }

            return ScaleChildX(parent, x);
        }

        private int ScaleChildY(Control parent, int y)
        {
            if (IsA220PhysicalLayout(parent))
            {
                return Math.Max(0, y);
            }

            int parentHeight = parent?.ClientSize.Height ?? 0;
            int baseHeight = BaseLogicalHeight(parent);

            if (parentHeight > 0 && baseHeight > 0 && y > baseHeight)
            {
                return Math.Max(0, parentHeight - S(parentHeight - y));
            }

            return S(y);
        }

        private int ScaleChildY(Control parent, int y, int height)
        {
            if (IsA220PhysicalLayout(parent))
            {
                return Math.Max(0, y);
            }

            int parentHeight = parent?.ClientSize.Height ?? 0;
            int baseHeight = BaseLogicalHeight(parent);

            if (parentHeight > 0 && baseHeight > 0 && y > baseHeight / 2 && y + height > baseHeight)
            {
                return Math.Max(0, parentHeight - S(parentHeight - y));
            }

            return ScaleChildY(parent, y);
        }

        private int ScaleChildWidth(Control parent, int x, int width)
        {
            if (IsA220PhysicalLayout(parent))
            {
                int parentWidthPhysical = parent?.ClientSize.Width ?? 0;
                if (parentWidthPhysical > 0)
                {
                    return Math.Max(1, Math.Min(width, parentWidthPhysical - Math.Max(0, x)));
                }

                return Math.Max(1, width);
            }

            int parentWidth = parent?.ClientSize.Width ?? 0;
            int baseWidth = BaseLogicalWidth(parent);
            int scaledX = ScaleChildX(parent, x, width);

            // If the provided x/width combination extends beyond the unscaled
            // logical page width, it came from page.Width/page.Width - margin.
            // Keep the right margin stable and scale that margin, instead of
            // compressing the field to 1px.
            if (parentWidth > 0 && baseWidth > 0 && x + width > baseWidth)
            {
                int rightMargin = Math.Max(0, parentWidth - x - width);
                return Math.Max(1, parentWidth - scaledX - S(rightMargin));
            }

            return S(width);
        }

        private int ScaleChildHeight(Control parent, int y, int height)
        {
            if (IsA220PhysicalLayout(parent))
            {
                int parentHeightPhysical = parent?.ClientSize.Height ?? 0;
                if (parentHeightPhysical > 0)
                {
                    return Math.Max(1, Math.Min(height, parentHeightPhysical - Math.Max(0, y)));
                }

                return Math.Max(1, height);
            }

            int parentHeight = parent?.ClientSize.Height ?? 0;
            int baseHeight = BaseLogicalHeight(parent);
            int scaledY = ScaleChildY(parent, y, height);

            if (parentHeight > 0 && baseHeight > 0 && y + height > baseHeight)
            {
                int bottomMargin = Math.Max(0, parentHeight - y - height);
                return Math.Max(1, parentHeight - scaledY - S(bottomMargin));
            }

            return S(height);
        }

        public static int AutoDeleteRequestMessageSeconds
        {
            get
            {
                return NormalizeAutoDeleteRequestSeconds(ReadFixedStringSetting(AutoDeleteRequestSecondsSettingName, "30"));
            }
            set
            {
                SaveFixedStringSetting(
                    AutoDeleteRequestSecondsSettingName,
                    NormalizeAutoDeleteRequestSeconds(value.ToString(System.Globalization.CultureInfo.InvariantCulture)).ToString(System.Globalization.CultureInfo.InvariantCulture));
            }
        }

        private static int NormalizeAutoDeleteRequestSeconds(string value)
        {
            if (!int.TryParse((value ?? string.Empty).Trim(), System.Globalization.NumberStyles.Integer, System.Globalization.CultureInfo.InvariantCulture, out int seconds))
            {
                seconds = 30;
            }

            return Math.Max(5, Math.Min(99, seconds));
        }

        public static string MessageTextSize
        {
            get
            {
                return NormalizeMessageTextSize(ReadFixedStringSetting(MessageTextSizeSettingName, "Normal"));
            }
            set
            {
                SaveFixedStringSetting(MessageTextSizeSettingName, NormalizeMessageTextSize(value));
            }
        }

        public static bool MessageOverviewLskModeEnabled
        {
            get
            {
                string value = ReadFixedStringSetting(MessageOverviewLskModeSettingName, "false");
                return string.Equals(value, "true", StringComparison.OrdinalIgnoreCase) ||
                       string.Equals(value, "1", StringComparison.OrdinalIgnoreCase) ||
                       string.Equals(value, "yes", StringComparison.OrdinalIgnoreCase) ||
                       string.Equals(value, "on", StringComparison.OrdinalIgnoreCase);
            }
            set
            {
                SaveFixedStringSetting(
                    MessageOverviewLskModeSettingName,
                    value ? "true" : "false");
            }
        }

        private static string NormalizeMessageTextSize(string value)
        {
            string cleaned = (value ?? string.Empty).Trim().ToUpperInvariant();

            if (cleaned.Contains("EXTRA") || cleaned == "XL" || cleaned.Contains("130"))
            {
                return "Extra Large";
            }

            if (cleaned.Contains("LARGE") || cleaned.Contains("115") || cleaned.Contains("125"))
            {
                return "Large";
            }

            return "Normal";
        }

        private static float MessageTextSizeOffsetPixels()
        {
            string size = MessageTextSize;

            if (string.Equals(size, "Extra Large", StringComparison.OrdinalIgnoreCase))
            {
                return 3.0f;
            }

            if (string.Equals(size, "Large", StringComparison.OrdinalIgnoreCase))
            {
                return 1.6f;
            }

            return 0.0f;
        }

        private static string ReadFixedStringSetting(string settingName, string defaultValue)
        {
            try
            {
                string path = FixedEasyCpdlcSettingsPath();
                if (string.IsNullOrWhiteSpace(settingName) || !File.Exists(path))
                {
                    return defaultValue;
                }

                System.Xml.Linq.XDocument document = System.Xml.Linq.XDocument.Load(path);
                string value = document
                    .Descendants()
                    .FirstOrDefault(item =>
                        item.Name.LocalName == "setting" &&
                        string.Equals(item.Attribute("name")?.Value, settingName, StringComparison.OrdinalIgnoreCase))
                    ?.Elements()
                    .FirstOrDefault(item => item.Name.LocalName == "value")
                    ?.Value;

                return string.IsNullOrWhiteSpace(value) ? defaultValue : value;
            }
            catch
            {
                return defaultValue;
            }
        }

        private static void SaveFixedStringSetting(string settingName, string settingValue)
        {
            try
            {
                string path = FixedEasyCpdlcSettingsPath();
                string directory = Path.GetDirectoryName(path);
                if (!string.IsNullOrWhiteSpace(directory))
                {
                    Directory.CreateDirectory(directory);
                }

                System.Xml.Linq.XDocument document = File.Exists(path)
                    ? System.Xml.Linq.XDocument.Load(path)
                    : new System.Xml.Linq.XDocument(
                        new System.Xml.Linq.XElement("configuration",
                            new System.Xml.Linq.XElement("userSettings",
                                new System.Xml.Linq.XElement("EasyCPDLC.Properties.Settings"))));

                System.Xml.Linq.XElement root = document.Element("configuration");
                if (root == null)
                {
                    root = new System.Xml.Linq.XElement("configuration");
                    document.Add(root);
                }

                System.Xml.Linq.XElement userSettings = root.Elements().FirstOrDefault(item => item.Name.LocalName == "userSettings");
                if (userSettings == null)
                {
                    userSettings = new System.Xml.Linq.XElement("userSettings");
                    root.Add(userSettings);
                }

                System.Xml.Linq.XElement settingsNode = userSettings.Elements().FirstOrDefault(item => item.Name.LocalName == "EasyCPDLC.Properties.Settings");
                if (settingsNode == null)
                {
                    settingsNode = new System.Xml.Linq.XElement("EasyCPDLC.Properties.Settings");
                    userSettings.Add(settingsNode);
                }

                System.Xml.Linq.XElement setting = settingsNode.Elements()
                    .FirstOrDefault(item =>
                        item.Name.LocalName == "setting" &&
                        string.Equals(item.Attribute("name")?.Value, settingName, StringComparison.OrdinalIgnoreCase));

                if (setting == null)
                {
                    setting = new System.Xml.Linq.XElement("setting",
                        new System.Xml.Linq.XAttribute("name", settingName),
                        new System.Xml.Linq.XAttribute("serializeAs", "String"),
                        new System.Xml.Linq.XElement("value", settingValue ?? string.Empty));
                    settingsNode.Add(setting);
                }
                else
                {
                    setting.SetAttributeValue("serializeAs", "String");
                    System.Xml.Linq.XElement valueElement = setting.Elements().FirstOrDefault(item => item.Name.LocalName == "value");
                    if (valueElement == null)
                    {
                        valueElement = new System.Xml.Linq.XElement("value");
                        setting.Add(valueElement);
                    }

                    valueElement.Value = settingValue ?? string.Empty;
                }

                document.Save(path);
            }
            catch (Exception ex)
            {
                try
                {
                    Logger.Debug("Could not save fixed string setting " + settingName + ": " + ex.Message);
                }
                catch
                {
                    // Ignore logging failures.
                }
            }
        }

        private static string FixedEasyCpdlcSettingsPath()
        {
            string root = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
            return Path.Combine(root, "EasyCPDLCModernized", "user.config");
        }

        private const string SettingsUpgradeVersionSettingName = "SettingsUpgradeVersion";

        private static void UpgradeUserSettingsForCurrentVersionIfNeeded()
        {
            try
            {
                string currentVersion = System.Windows.Forms.Application.ProductVersion ?? string.Empty;
                string upgradedVersion = ReadFixedStringSetting(SettingsUpgradeVersionSettingName, string.Empty);

                if (string.IsNullOrWhiteSpace(currentVersion) ||
                    string.Equals(upgradedVersion, currentVersion, StringComparison.OrdinalIgnoreCase))
                {
                    return;
                }

                Properties.Settings.Default.Upgrade();
                Properties.Settings.Default.Save();
                SaveFixedStringSetting(SettingsUpgradeVersionSettingName, currentVersion);
                Logger.Debug("User settings upgraded for version " + currentVersion + ".");
            }
            catch (Exception ex)
            {
                try
                {
                    Logger.Debug("User settings upgrade check failed: " + ex.Message);
                }
                catch
                {
                    // Ignore logging failures during early startup.
                }
            }
        }

        private static string CurrentUserConfigFilePath()
        {
            try
            {
                string path = System.Configuration.ConfigurationManager
                    .OpenExeConfiguration(System.Configuration.ConfigurationUserLevel.PerUserRoamingAndLocal)
                    .FilePath;

                return string.IsNullOrWhiteSpace(path) ? string.Empty : path;
            }
            catch (Exception ex)
            {
                try
                {
                    Logger.Debug("Could not resolve current user.config path: " + ex.Message);
                }
                catch
                {
                }

                return string.Empty;
            }
        }

        private static System.Xml.Linq.XDocument CreateEasyCpdlcUserConfigDocument()
        {
            return new System.Xml.Linq.XDocument(
                new System.Xml.Linq.XElement("configuration",
                    new System.Xml.Linq.XElement("userSettings",
                        new System.Xml.Linq.XElement("EasyCPDLC.Properties.Settings"))));
        }

        private static void SetUserConfigStringSetting(System.Xml.Linq.XDocument document, string settingName, string settingValue)
        {
            if (document == null || string.IsNullOrWhiteSpace(settingName))
            {
                return;
            }

            System.Xml.Linq.XElement root = document.Element("configuration");
            if (root == null)
            {
                root = new System.Xml.Linq.XElement("configuration");
                document.Add(root);
            }

            System.Xml.Linq.XElement userSettings = root.Elements().FirstOrDefault(item => item.Name.LocalName == "userSettings");
            if (userSettings == null)
            {
                userSettings = new System.Xml.Linq.XElement("userSettings");
                root.Add(userSettings);
            }

            System.Xml.Linq.XElement settingsNode = userSettings.Elements().FirstOrDefault(item => item.Name.LocalName == "EasyCPDLC.Properties.Settings");
            if (settingsNode == null)
            {
                settingsNode = new System.Xml.Linq.XElement("EasyCPDLC.Properties.Settings");
                userSettings.Add(settingsNode);
            }

            System.Xml.Linq.XElement setting = settingsNode.Elements()
                .FirstOrDefault(item =>
                    item.Name.LocalName == "setting" &&
                    string.Equals(item.Attribute("name")?.Value, settingName, StringComparison.OrdinalIgnoreCase));

            if (setting == null)
            {
                setting = new System.Xml.Linq.XElement("setting",
                    new System.Xml.Linq.XAttribute("name", settingName),
                    new System.Xml.Linq.XAttribute("serializeAs", "String"),
                    new System.Xml.Linq.XElement("value", settingValue ?? string.Empty));
                settingsNode.Add(setting);
                return;
            }

            setting.SetAttributeValue("serializeAs", "String");
            System.Xml.Linq.XElement valueElement = setting.Elements().FirstOrDefault(item => item.Name.LocalName == "value");
            if (valueElement == null)
            {
                valueElement = new System.Xml.Linq.XElement("value");
                setting.Add(valueElement);
            }

            valueElement.Value = settingValue ?? string.Empty;
        }

        private static string PrepareUserConfigForVersionChange(Release targetRelease, string tempDir, string currentUserConfigPath)
        {
            try
            {
                Properties.Settings.Default.Save();

                if (string.IsNullOrWhiteSpace(currentUserConfigPath))
                {
                    currentUserConfigPath = CurrentUserConfigFilePath();
                }

                Version targetVersion = ParseReleaseVersion(targetRelease?.TagName);
                Version currentVersion = ParseReleaseVersion(System.Windows.Forms.Application.ProductVersion);
                bool isRollback = targetVersion != null && currentVersion != null && targetVersion < currentVersion;

                if (!isRollback)
                {
                    return currentUserConfigPath;
                }

                if (string.IsNullOrWhiteSpace(tempDir))
                {
                    tempDir = Path.GetTempPath();
                }

                Directory.CreateDirectory(tempDir);
                string compatibilityPath = Path.Combine(tempDir, "EasyCPDLC_Rollback_Compatible_user.config");

                System.Xml.Linq.XDocument document = !string.IsNullOrWhiteSpace(currentUserConfigPath) && File.Exists(currentUserConfigPath)
                    ? System.Xml.Linq.XDocument.Load(currentUserConfigPath)
                    : CreateEasyCpdlcUserConfigDocument();

                // Older builds do not understand the DPAPI-protected settings.
                // For an explicit rollback, decrypt values in the current process and write
                // legacy-compatible plain settings into the copied user.config so the previous
                // build can still populate its setup fields after restart.
                SetUserConfigStringSetting(
                    document,
                    "CID",
                    Math.Max(0, SavedCID).ToString(System.Globalization.CultureInfo.InvariantCulture));
                SetUserConfigStringSetting(document, "HoppieCode", SavedHoppieCode ?? string.Empty);
                SetUserConfigStringSetting(document, "SimbriefUsername", SimbriefID ?? string.Empty);

                document.Save(compatibilityPath);
                return compatibilityPath;
            }
            catch (Exception ex)
            {
                try
                {
                    Logger.Debug("Could not prepare rollback-compatible user.config: " + ex.Message);
                }
                catch
                {
                }

                return currentUserConfigPath ?? string.Empty;
            }
        }

        private static void ResetEasyCpdlcLogFileForStartup(string logFilePath)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(logFilePath))
                {
                    return;
                }

                string directory = Path.GetDirectoryName(logFilePath);
                if (!string.IsNullOrWhiteSpace(directory))
                {
                    Directory.CreateDirectory(directory);
                }

                // Start every EasyCPDLC session with a fresh log file.
                // This prevents LocalAppData logs from growing indefinitely.
                using FileStream stream = new FileStream(
                    logFilePath,
                    System.IO.FileMode.Create,
                    System.IO.FileAccess.Write,
                    System.IO.FileShare.ReadWrite);
                stream.SetLength(0);
            }
            catch
            {
                // Logging is not initialised yet. If the file is locked or unavailable,
                // continue startup and let NLog append to the existing file.
            }
        }

        private static string ResolveEasyCpdlcLogFilePath()
        {
            const string logFileName = "EasyCPDLCLog.txt";

            try
            {
                string root = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
                string logDirectory = Path.Combine(root, "EasyCPDLCModernized", "Logs");
                Directory.CreateDirectory(logDirectory);
                return Path.Combine(logDirectory, logFileName);
            }
            catch
            {
                try
                {
                    string fallbackDirectory = Path.Combine(Path.GetTempPath(), "EasyCPDLCModernized", "Logs");
                    Directory.CreateDirectory(fallbackDirectory);
                    return Path.Combine(fallbackDirectory, logFileName);
                }
                catch
                {
                    return Path.Combine(Path.GetTempPath(), logFileName);
                }
            }
        }

        private Font messageTextFont;
        private Font messageTextFontBold;

        private void RefreshMessageTextFonts()
        {
            float offset = MessageTextSizeOffsetPixels();
            float baseRegularPixels = 10.5f * 96.0f / 72.0f;
            float baseBoldPixels = 11.5f * 96.0f / 72.0f;
            messageTextFont = CreateDpiStablePixelFont(textFont.FontFamily, Math.Max(1.0f, baseRegularPixels + offset), FontStyle.Regular);
            messageTextFontBold = CreateDpiStablePixelFont(textFontBold.FontFamily, Math.Max(1.0f, baseBoldPixels + offset), FontStyle.Bold);
        }

        private Font GetMessageTextFont(bool bold)
        {
            if (messageTextFont == null || messageTextFontBold == null)
            {
                RefreshMessageTextFonts();
            }

            return bold ? messageTextFontBold : messageTextFont;
        }

        private static IEnumerable<Control> EnumerateChildControls(Control parent)
        {
            if (parent == null)
            {
                yield break;
            }

            foreach (Control child in parent.Controls)
            {
                yield return child;

                foreach (Control descendant in EnumerateChildControls(child))
                {
                    yield return descendant;
                }
            }
        }

        public void ApplyMessageTextSizeSetting()
        {
            RefreshMessageTextFonts();
            RefreshVisibleMessageColors();

            if (messageFormatPanel != null && !messageFormatPanel.IsDisposed)
            {
                foreach (System.Windows.Forms.Label label in EnumerateChildControls(messageFormatPanel).OfType<System.Windows.Forms.Label>())
                {
                    if (string.Equals(label.Tag as string, MessagePreviewTextTag, StringComparison.Ordinal))
                    {
                        label.Font = GetMessageTextFont(true);
                        label.Invalidate();
                    }
                }

                messageFormatPanel.PerformLayout();
                HidePreviewHorizontalScrollbar();
            }

            HideNativeOutputScrollbars();
        }

        public int messageOutCounter = 1;
        private bool _connected;

        // A single client must never be able to create overlapping VATSIM logon
        // checks by double-clicking CONN or by invoking another style's handler.
        private bool connectionAttemptInProgress;
        private DateTime nextConnectionAttemptUtc = DateTime.MinValue;
        private int connectionRetryCooldownGeneration;
        private static readonly TimeSpan connectionFailureRetryCooldown = TimeSpan.FromSeconds(30);

        [System.ComponentModel.Browsable(false)]
        [System.ComponentModel.DesignerSerializationVisibility(System.ComponentModel.DesignerSerializationVisibility.Hidden)]
        public bool Connected
        {
            get
            {
                return _connected;
            }
            set
            {
                _connected = value;

                if (retrieveButton != null)
                {
                    retrieveButton.Text = _connected ? "DISC" : "CONN";
                }

                if (statusValueLabel != null)
                {
                    statusValueLabel.Text = _connected ? "CONNECTED" : "STANDBY";
                    statusValueLabel.ForeColor = _connected ? DcduTheme.Green : DcduTheme.Amber;
                }

                UpdateConnectionGatedControls();

                UpdateCurrentAtcUnitDisplay();
                UpdateCallsignDisplay();
                UpdateFlightPhaseBadge();
            }
        }

        private void UpdateConnectionGatedControls()
        {
            bool connected = _connected || DebugUiPreviewMode;
            bool connectCooldownActive =
                !DebugUiPreviewMode &&
                !_connected &&
                DateTime.UtcNow < nextConnectionAttemptUtc;
            bool connectionControlEnabled =
                DebugUiPreviewMode ||
                (!connectionAttemptInProgress && (_connected || !connectCooldownActive));

            if (retrieveButton != null)
            {
                retrieveButton.Enabled = connectionControlEnabled;
                retrieveButton.Cursor = connectionControlEnabled ? Cursors.Hand : Cursors.Default;
            }

            bool interactiveEnabled = DebugUiPreviewMode || (connected && IsHoppieCallsignReadyForInteractiveMenus());

            Control[] interactiveControls =
            {
                atcButton,
                telexButton,
                clearanceStatusLabel,
                datalinkStatusLabel,
                atisStatusLabel,
                atisAutoStatusLabel,
                quickWxStatusLabel,
                cpdlcDiscoveryLabel
            };

            foreach (Control control in interactiveControls)
            {
                if (control == null)
                {
                    continue;
                }

                control.Enabled = interactiveEnabled;
                control.Cursor = interactiveEnabled ? Cursors.Hand : Cursors.Default;
            }

            // Recovery/check controls stay available while connected.
            if (mainReloadFlightPlanButton != null)
            {
                mainReloadFlightPlanButton.Enabled = connected;
                mainReloadFlightPlanButton.Cursor = connected ? Cursors.Hand : Cursors.Default;
            }

            if (callsignUpdateLabel != null)
            {
                callsignUpdateLabel.Enabled = connected;
                callsignUpdateLabel.Cursor = connected ? Cursors.Hand : Cursors.Default;
            }

            if (CpdlcHelperPopupDebugPreview && cpdlcDiscoveryLabel != null)
            {
                cpdlcDiscoveryLabel.Enabled = true;
                cpdlcDiscoveryLabel.Cursor = Cursors.Hand;
                cpdlcDiscoveryLabel.Visible = true;
            }

            SyncA220NavigationAvailability();

            if (!interactiveEnabled)
            {
                HideQuickWxPopup();
                HideClearanceTimelinePopup();
                HideAtisAvailabilityPopup();
                HideAtisAutoPopup();
                HideQuickActionButtons();
            }

            if (!connected)
            {
                lastCpdlcStationDetectedNotificationKey = string.Empty;
                lastCpdlcStationDetectedNotificationUtc = DateTime.MinValue;
            }
        }

        private int RemainingConnectionRetrySeconds()
        {
            TimeSpan remaining = nextConnectionAttemptUtc - DateTime.UtcNow;
            return Math.Max(0, (int)Math.Ceiling(remaining.TotalSeconds));
        }

        private void ClearConnectionRetryCooldown()
        {
            connectionRetryCooldownGeneration++;
            nextConnectionAttemptUtc = DateTime.MinValue;
            UpdateConnectionGatedControls();
        }

        private void StartConnectionRetryCooldown(string reason)
        {
            nextConnectionAttemptUtc = DateTime.UtcNow + connectionFailureRetryCooldown;
            int generation = ++connectionRetryCooldownGeneration;

            Logger.Debug(
                "VATSIM connection retry cooldown started for " +
                connectionFailureRetryCooldown.TotalSeconds.ToString(
                    "0",
                    System.Globalization.CultureInfo.InvariantCulture) +
                " seconds: " +
                (reason ?? "unspecified"));

            UpdateConnectionGatedControls();
            _ = RestoreConnectionButtonAfterCooldownAsync(generation);
        }

        private async Task RestoreConnectionButtonAfterCooldownAsync(int generation)
        {
            TimeSpan delay = nextConnectionAttemptUtc - DateTime.UtcNow;
            if (delay > TimeSpan.Zero)
            {
                await Task.Delay(delay);
            }

            SafeUi(() =>
            {
                if (generation != connectionRetryCooldownGeneration)
                {
                    return;
                }

                if (DateTime.UtcNow >= nextConnectionAttemptUtc)
                {
                    nextConnectionAttemptUtc = DateTime.MinValue;
                    UpdateConnectionGatedControls();
                }
            });
        }

        private static bool IsVatsimRetryCooldownMessageText(string messageText)
        {
            string upper = (messageText ?? string.Empty)
                .Replace("⌛", string.Empty)
                .Replace("⏳", string.Empty)
                .Replace("✓", string.Empty)
                .Trim()
                .ToUpperInvariant();

            return upper.StartsWith("VATSIM: PILOT NOT FOUND", StringComparison.Ordinal) ||
                   (upper.StartsWith("VATSIM: ERROR", StringComparison.Ordinal) &&
                    (upper.Contains("WAIT 30 SECONDS AND RETRY") ||
                     upper.Contains("RETRY AVAILABLE")));
        }

        private static string BuildVatsimRetryReadyMessage(string originalText)
        {
            string clean = (originalText ?? string.Empty)
                .Replace("⌛", string.Empty)
                .Replace("⏳", string.Empty)
                .Replace("✓", string.Empty)
                .Trim();

            clean = Regex.Replace(
                clean,
                @"\s*WAIT\s+\d+\s+SECONDS?\s+AND\s+RETRY\s*\.?\s*$",
                string.Empty,
                RegexOptions.IgnoreCase).Trim();

            clean = clean.TrimEnd('.');
            return string.IsNullOrWhiteSpace(clean)
                ? "VATSIM: RETRY AVAILABLE."
                : clean + ". RETRY AVAILABLE.";
        }

        private TimerLabel FindOverviewActionLabel(CPDLCMessage message)
        {
            if (message == null ||
                message.IsDisposed ||
                outputTable == null ||
                outputTable.IsDisposed)
            {
                return null;
            }

            // LSK mode intentionally unparents action cells; this lookup
            // must keep finding the same live instance for state updates.
            if (overviewMessageRowParts.TryGetValue(message, out var owned) &&
                owned.Action != null && !owned.Action.IsDisposed)
            {
                return owned.Action;
            }

            try
            {
                TableLayoutPanelCellPosition position =
                    outputTable.GetPositionFromControl(message);

                if (position.Row >= 0 &&
                    outputTable.GetControlFromPosition(2, position.Row) is TimerLabel menuLabel)
                {
                    return menuLabel;
                }
            }
            catch
            {
                // Cosmetic lookup only.
            }

            return null;
        }

        private void HideVatsimRetryMessageActions(CPDLCMessage message)
        {
            TimerLabel menuLabel = FindOverviewActionLabel(message);
            if (menuLabel == null || menuLabel.IsDisposed)
            {
                return;
            }

            menuLabel.Paint -= OpenMessageIndicator_Paint;
            menuLabel.Paint -= AutoDeleteRequestIndicator_Paint;
            menuLabel.Tag = null;
            menuLabel.Text = string.Empty;
            menuLabel.CanFlash = false;
            menuLabel.Enabled = false;
            menuLabel.Cursor = Cursors.Default;
            menuLabel.Visible = false;
            menuLabel.Invalidate();
        }

        private void StartVatsimRetryReadyAutoDelete(CPDLCMessage message)
        {
            if (message == null || message.IsDisposed)
            {
                return;
            }

            // Keep this special status row free of action/countdown icons. The
            // normal configured auto-delete duration is used, but its countdown is
            // intentionally not painted in the overview.
            HideVatsimRetryMessageActions(message);
            StopAutoDeleteRequestMessage(message, false);

            DateTime dueUtc = DateTime.UtcNow + RequestMessageAutoDeleteDelay;
            System.Windows.Forms.Timer deleteTimer = new()
            {
                Interval = 250
            };

            deleteTimer.Tick += (_, __) =>
            {
                if (message.IsDisposed ||
                    outputTable == null ||
                    outputTable.IsDisposed)
                {
                    StopAutoDeleteRequestMessage(message, false);
                    return;
                }

                if (IsMessageProtectedFromAutoDelete(message))
                {
                    StopAutoDeleteRequestMessage(message, true);
                    return;
                }

                if (DateTime.UtcNow < dueUtc)
                {
                    return;
                }

                StopAutoDeleteRequestMessage(message, false);
                AutoDeleteMessageRow(message);
            };

            autoDeleteRequestTimers[message] = deleteTimer;
            deleteTimer.Start();
        }

        private void StartVatsimRetryHourglassAnimation(
            CPDLCMessage message,
            string originalText)
        {
            if (message == null || message.IsDisposed)
            {
                return;
            }

            StopVatsimRetryHourglassAnimation(message);
            StopAutoDeleteRequestMessage(message, false);
            HideVatsimRetryMessageActions(message);

            string cleanOriginalText = (originalText ?? string.Empty).Trim();
            string listText = BuildSystemListSummary(cleanOriginalText);
            DateTime dueUtc = nextConnectionAttemptUtc > DateTime.UtcNow
                ? nextConnectionAttemptUtc
                : DateTime.UtcNow + connectionFailureRetryCooldown;

            int frameIndex = 0;
            string[] frames = { "⌛", "⏳" };

            void ApplyWaitingFrame()
            {
                if (message.IsDisposed)
                {
                    return;
                }

                message.Text = frames[frameIndex] + " " + listText;
                message.ForeColor = DcduTheme.Amber;
                message.Invalidate();
                frameIndex = (frameIndex + 1) % frames.Length;
            }

            System.Windows.Forms.Timer animationTimer = new()
            {
                Interval = 420
            };

            animationTimer.Tick += (_, __) =>
            {
                if (message.IsDisposed ||
                    outputTable == null ||
                    outputTable.IsDisposed)
                {
                    StopVatsimRetryHourglassAnimation(message);
                    return;
                }

                if (DateTime.UtcNow >= dueUtc)
                {
                    StopVatsimRetryHourglassAnimation(message);

                    string readyText = BuildVatsimRetryReadyMessage(cleanOriginalText);
                    message.message = readyText;
                    message.Text = "✓ " + BuildSystemListSummary(readyText);
                    message.ForeColor = DcduTheme.Green;
                    message.Invalidate();
                    outputTable.PerformLayout();

                    // The waiting notice itself never expires. Auto-delete begins
                    // only now, after RETRY AVAILABLE has been displayed.
                    StartVatsimRetryReadyAutoDelete(message);
                    return;
                }

                ApplyWaitingFrame();
            };

            vatsimRetryMessageAnimationTimers[message] = animationTimer;
            ApplyWaitingFrame();
            animationTimer.Start();
        }

        private void StopVatsimRetryHourglassAnimation(CPDLCMessage message)
        {
            if (message == null ||
                !vatsimRetryMessageAnimationTimers.TryGetValue(
                    message,
                    out System.Windows.Forms.Timer animationTimer))
            {
                return;
            }

            animationTimer.Stop();
            animationTimer.Dispose();
            vatsimRetryMessageAnimationTimers.Remove(message);
        }

        private void StopAllVatsimRetryHourglassAnimations()
        {
            foreach (System.Windows.Forms.Timer animationTimer in
                     vatsimRetryMessageAnimationTimers.Values.ToList())
            {
                animationTimer.Stop();
                animationTimer.Dispose();
            }

            vatsimRetryMessageAnimationTimers.Clear();
        }

