                _currentATCUnit = newUnit;

                if (!string.IsNullOrWhiteSpace(newUnit))
                {
                    cpdlcSessionEstablished = true;
                    RemoveObsoleteCpdlcWatchMessages();
                }

                UpdateCurrentAtcUnitDisplay();
                UpdateOnlineStatusLabel();

            }
        }

