        private static string DiagnosticLogTimestamp()
        {
            return DateTimeOffset.Now.ToString(
                "yyyy-MM-dd HH:mm:ss.fff zzz",
                System.Globalization.CultureInfo.InvariantCulture);
        }

        private static string DiagnosticLogMessage(string message)
        {
            return "[" + DiagnosticLogTimestamp() + "] " + (message ?? string.Empty);
        }

        private void RecordUiDiagnosticActivity(string activity)
        {
            lock (uiThreadDiagnosticSync)
            {
                uiThreadLastDiagnosticActivity =
                    string.IsNullOrWhiteSpace(activity) ? "unknown" : activity;
                uiThreadLastDiagnosticActivityUtc = DateTime.UtcNow;
            }
        }

        private int BeginUiDiagnosticOperation(string operation)
        {
            lock (uiThreadDiagnosticSync)
            {
                uiThreadDiagnosticOperationToken++;
                uiThreadActiveDiagnosticOperation =
                    string.IsNullOrWhiteSpace(operation) ? "unknown" : operation;
                uiThreadActiveDiagnosticOperationUtc = DateTime.UtcNow;
                uiThreadLastDiagnosticActivity = uiThreadActiveDiagnosticOperation;
                uiThreadLastDiagnosticActivityUtc = uiThreadActiveDiagnosticOperationUtc;
                return uiThreadDiagnosticOperationToken;
            }
        }

        private void EndUiDiagnosticOperation(int token)
        {
            string operation = null;
            TimeSpan elapsed = TimeSpan.Zero;

            lock (uiThreadDiagnosticSync)
            {
                if (token != uiThreadDiagnosticOperationToken)
                {
                    return;
                }

                operation = uiThreadActiveDiagnosticOperation;
                if (uiThreadActiveDiagnosticOperationUtc != DateTime.MinValue)
                {
                    elapsed = DateTime.UtcNow - uiThreadActiveDiagnosticOperationUtc;
                }

                uiThreadActiveDiagnosticOperation = "idle";
                uiThreadActiveDiagnosticOperationUtc = DateTime.MinValue;
            }

            if (!string.IsNullOrWhiteSpace(operation) &&
                !string.Equals(operation, "idle", StringComparison.OrdinalIgnoreCase) &&
                elapsed >= diagnosticSlowOperationThreshold)
            {
                Logger.Warn(
                    DiagnosticLogMessage(
                        "SLOW UI OPERATION: " +
                        operation +
                        " took " +
                        elapsed.TotalSeconds.ToString(
                            "0.0",
                            System.Globalization.CultureInfo.InvariantCulture) +
                        "s."));
            }
        }

        private void LogAsyncOperationDuration(string operation, Stopwatch stopwatch)
        {
            if (stopwatch == null)
            {
                return;
            }

            stopwatch.Stop();
            string message =
                "ASYNC OPERATION: " +
                operation +
                " took " +
                stopwatch.Elapsed.TotalSeconds.ToString(
                    "0.0",
                    System.Globalization.CultureInfo.InvariantCulture) +
                "s.";

            if (stopwatch.Elapsed >= diagnosticSlowOperationThreshold)
            {
                Logger.Warn(
                    DiagnosticLogMessage(
                        message + " UI should remain responsive while awaiting it."));
            }
            else
            {
                Logger.Debug(DiagnosticLogMessage(message));
            }
        }

        private string BuildUiThreadDiagnosticSnapshot()
        {
            string lastActivity;
            string activeOperation;
            DateTime lastActivityUtc;
            DateTime activeOperationUtc;

            lock (uiThreadDiagnosticSync)
            {
                lastActivity = uiThreadLastDiagnosticActivity;
                lastActivityUtc = uiThreadLastDiagnosticActivityUtc;
                activeOperation = uiThreadActiveDiagnosticOperation;
                activeOperationUtc = uiThreadActiveDiagnosticOperationUtc;
            }

            DateTime nowUtc = DateTime.UtcNow;
            double lastActivityAge = Math.Max(
                0.0,
                (nowUtc - lastActivityUtc).TotalSeconds);
            double activeOperationAge =
                activeOperationUtc == DateTime.MinValue
                    ? 0.0
                    : Math.Max(0.0, (nowUtc - activeOperationUtc).TotalSeconds);

            string style = DcduStyleManager.IsA220
                ? "A220"
                : (DcduStyleManager.IsBoeing ? "BOEING" : "AIRBUS");

            return
                "active-ui-operation=" +
                activeOperation +
                " (" +
                activeOperationAge.ToString(
                    "0.0",
                    System.Globalization.CultureInfo.InvariantCulture) +
                "s), last-activity=" +
                lastActivity +
                " (" +
                lastActivityAge.ToString(
                    "0.0",
                    System.Globalization.CultureInfo.InvariantCulture) +
                "s ago), connected=" +
                Connected.ToString() +
                ", style=" +
                style +
                ", fsuipc-enabled=" +
                UseFSUIPC.ToString() +
                ", fsuipc-open=" +
                fsConnectionOpen.ToString() +
                ", connection-attempt=" +
                connectionAttemptInProgress.ToString() +
                ", vatsim-refresh=" +
                vatsimOnlineRefreshInProgress.ToString() +
                ", setup-page=" +
                embeddedSetupPage.ToString() +
                ", airbus-page=" +
                airbusAocPage.ToString() +
                ", boeing-page=" +
                boeingTelexPage.ToString();
        }

        private async Task RefreshFsuipcDataWithDiagnosticsAsync(string context)
        {
            Stopwatch totalStopwatch = Stopwatch.StartNew();
            Task refreshTask;
            int uiOperationToken = BeginUiDiagnosticOperation(
                "FSUIPC RefreshData invocation [" + context + "]");

            try
            {
                // If the third-party library blocks before returning its Task, the
                // background watchdog can now identify this exact operation.
                refreshTask = fsuipc.RefreshData();
            }
            finally
            {
                EndUiDiagnosticOperation(uiOperationToken);
            }

            await refreshTask;
            LogAsyncOperationDuration(
                "FSUIPC RefreshData [" + context + "]",
                totalStopwatch);
        }

        private async Task<bool> OpenFsuipcConnectionWithDiagnosticsAsync(
            string context,
            CancellationToken cancellationToken = default)
        {
            Stopwatch stopwatch = Stopwatch.StartNew();
            RecordUiDiagnosticActivity("FSUIPC OpenConnection [" + context + "]");

            bool result = await Task.Run(
                () => FSUIPCData.OpenConnection(),
                cancellationToken);

            LogAsyncOperationDuration(
                "FSUIPC OpenConnection [" + context + "]",
                stopwatch);
            return result;
        }

        private async Task<bool> CloseFsuipcConnectionWithDiagnosticsAsync(
            string context,
            CancellationToken cancellationToken = default)
        {
            Stopwatch stopwatch = Stopwatch.StartNew();
            RecordUiDiagnosticActivity("FSUIPC CloseConnection [" + context + "]");

            bool result = await Task.Run(
                () => FSUIPCData.CloseConnection(),
                cancellationToken);

            LogAsyncOperationDuration(
                "FSUIPC CloseConnection [" + context + "]",
                stopwatch);
            return result;
        }

        private void ConfigureUiThreadWatchdog()
        {
            uiThreadWatchdogTimer.Interval = 1000;
            uiThreadWatchdogLastTickUtc = DateTime.UtcNow;
            Interlocked.Exchange(
                ref uiThreadHeartbeatUtcTicks,
                uiThreadWatchdogLastTickUtc.Ticks);

            uiThreadWatchdogTimer.Tick += (_, __) =>
            {
                DateTime nowUtc = DateTime.UtcNow;
                TimeSpan elapsed = nowUtc - uiThreadWatchdogLastTickUtc;
                uiThreadWatchdogLastTickUtc = nowUtc;

                Interlocked.Exchange(ref uiThreadHeartbeatUtcTicks, nowUtc.Ticks);
                Interlocked.Exchange(ref uiThreadStallReported, 0);

                if (elapsed >= uiThreadStallLogThreshold)
                {
                    Logger.Warn(
                        DiagnosticLogMessage(
                            "UI THREAD STALL RECOVERED: " +
                            elapsed.TotalSeconds.ToString(
                                "0.0",
                                System.Globalization.CultureInfo.InvariantCulture) +
                            "s between UI watchdog ticks. " +
                            BuildUiThreadDiagnosticSnapshot()));
                }
            };

            // This timer is intentionally NOT a WinForms timer. It keeps running
            // when the WinForms message pump is blocked and can therefore record
            // the diagnostic context while the freeze is actually happening.
            uiThreadBackgroundWatchdogTimer = new System.Threading.Timer(
                _ =>
                {
                    long heartbeatTicks = Interlocked.Read(
                        ref uiThreadHeartbeatUtcTicks);
                    if (heartbeatTicks <= 0)
                    {
                        return;
                    }

                    TimeSpan elapsed =
                        DateTime.UtcNow - new DateTime(
                            heartbeatTicks,
                            DateTimeKind.Utc);

                    if (elapsed < uiThreadStallLogThreshold)
                    {
                        return;
                    }

                    if (Interlocked.CompareExchange(
                            ref uiThreadStallReported,
                            1,
                            0) != 0)
                    {
                        return;
                    }

                    Logger.Warn(
                        DiagnosticLogMessage(
                            "UI THREAD STALL IN PROGRESS: no UI heartbeat for " +
                            elapsed.TotalSeconds.ToString(
                                "0.0",
                                System.Globalization.CultureInfo.InvariantCulture) +
                            "s. " +
                            BuildUiThreadDiagnosticSnapshot()));
                },
                null,
                1000,
                1000);

            uiThreadWatchdogTimer.Start();
        }

        public MainForm()
        {
            string easyCpdlcLogFilePath = ResolveEasyCpdlcLogFilePath();
            ResetEasyCpdlcLogFileForStartup(easyCpdlcLogFilePath);

            var config = new NLog.Config.LoggingConfiguration();
            var logFile = new NLog.Targets.FileTarget("logfile")
            {
                FileName = easyCpdlcLogFilePath,
                KeepFileOpen = false
            };
            config.AddRule(LogLevel.Debug, LogLevel.Fatal, logFile);
            LogManager.Configuration = config;
            Logger.Info("Logging initialised, beginning setup");
            Logger.Debug("Log file path: " + easyCpdlcLogFilePath);
            CleanupStaleUpdateTemporaryDirectories();

            if (TryForwardProtocolLaunchToExistingInstance())
            {
                Logger.Info("Protocol launch forwarded to existing EasyCPDLC instance");
                Environment.Exit(0);
                return;
            }

            AutoScaleMode = AutoScaleMode.None;

            // Establish the resolution-only base scale before any fonts or controls
            // are created. Windows DPI is intentionally not consulted.
            UpdateAutomaticResolutionScaleFactor(false);
            appliedWindowScaleFactor = WindowScaleFactor();

            textFont = CreateDpiStablePointFont("Consolas", 10.5f, FontStyle.Regular);
            textFontBold = CreateDpiStablePointFont("Consolas", 11.5f, FontStyle.Bold);
            RefreshMessageTextFonts();
            controlFont = CreateDpiStablePointFont("Segoe UI", 10.0f, FontStyle.Regular);
            controlFontBold = CreateDpiStablePointFont("Segoe UI", 10.0f, FontStyle.Bold);
            dataEntryFont = CreateDpiStablePointFont("Consolas", 13.0f, FontStyle.Bold);
            Font = controlFont;

            AppDomain.CurrentDomain.AssemblyResolve += CurrentDomain_AssemblyResolve;

            ConfigureSoundPlayers();
            ConfigureUnreadMessageReminder();
            ConfigureRouteBlinkTimer();
            ConfigureClearanceAutoConfirmTimer();
            ConfigureCpdlcHandoverBlinkTimer();
            ConfigureNextAtcUnitBlinkTimer();
            ConfigureVatsimOnlineRefresh();
            ConfigureAtisAutoRefresh();
            ConfigureUiThreadWatchdog();
            if (!string.IsNullOrWhiteSpace(startupPlayer.SoundLocation) || startupPlayer.Stream != null)
            {
                startupPlayer.Play();
            }
            InitializeComponent();
            UpgradeUserSettingsForCurrentVersionIfNeeded();
            this.AutoScaleMode = AutoScaleMode.None;
            this.Font = controlFont;
            this.Icon = LoadTrayIcon();

            // A persisted A220 style is applied during construction, before MainForm_Load.
            // Its layout needs the dynamically created status and filter controls already
            // to exist, otherwise startup can fail with a NullReferenceException.
            ConfigureSmartWidgets();
            ApplyDisplayStyle();
            this.ShowInTaskbar = false;
            ConfigureTrayIcon();
            ConfigureMainFrameButtonHotspots();
            this.TopMost = true;
            this.FormBorderStyle = FormBorderStyle.None;
            this.DoubleBuffered = true;
            this.SetStyle(ControlStyles.ResizeRedraw, true);
            ApplyMainWindowBounds(DcduStyleManager.IsBoeing);
            cpdlcSessionEstablished = false;
            CurrentATCUnit = null;
            ClearNextAtcUnitDisplay();
            ConfigureMsfsClickGuard();
            InitialiseDebugUiPreviewMode();

            // Recalculate only when the form is first displayed or moved to a
            // monitor with different pixel dimensions. Location changes on the same
            // monitor do not trigger a rebuild.
            Shown += MainForm_ResolutionScaleShown;
            LocationChanged += MainForm_ResolutionScaleLocationChanged;

            // Prime VATSpy FIR/ARTCC boundaries at startup.
            // This is an in-memory fetch only. Nothing is written to the user's disk.
            _ = EnsureFirBoundariesLoadedAsync(false);

        }


        private void InitialiseDebugUiPreviewMode()
        {
            if (!DebugUiPreviewMode)
            {
                return;
            }

            try
            {
                bool firstInitialisation = !debugUiPreviewInitialised;
                debugUiPreviewInitialised = true;
                if (cid <= 0)
                {
                    cid = 1000001;
                }

                logonCode = string.IsNullOrWhiteSpace(logonCode) ? "DEBUG" : logonCode;
                callsign = string.IsNullOrWhiteSpace(callsign) ? "EZY123" : callsign.Trim().ToUpperInvariant();
                activeVatsimCallsign = callsign;
                pendingHoppieCallsign = string.Empty;
                vatsimCallsignMismatchWarningActive = false;
                pendingLogon = null;

                if (userVATSIMData == null)
                {
                    userVATSIMData = new Pilot();
                }

                userVATSIMData.cid = cid;
                userVATSIMData.callsign = callsign;
                userVATSIMData.latitude = 50.63408F;
                userVATSIMData.longitude = 7.99831F;
                userVATSIMData.altitude = 35000;
                userVATSIMData.groundspeed = 420;
                userVATSIMData.heading = 90;

                if (userVATSIMData.flight_plan == null)
                {
                    userVATSIMData.flight_plan = new Flight_Plan();
                }

                userVATSIMData.flight_plan.aircraft_short = string.IsNullOrWhiteSpace(userVATSIMData.flight_plan.aircraft_short) ? "A320" : userVATSIMData.flight_plan.aircraft_short;
                userVATSIMData.flight_plan.aircraft = string.IsNullOrWhiteSpace(userVATSIMData.flight_plan.aircraft) ? "A320" : userVATSIMData.flight_plan.aircraft;
                userVATSIMData.flight_plan.departure = string.IsNullOrWhiteSpace(userVATSIMData.flight_plan.departure) ? "EDDF" : userVATSIMData.flight_plan.departure;
                userVATSIMData.flight_plan.arrival = string.IsNullOrWhiteSpace(userVATSIMData.flight_plan.arrival) ? "EDDP" : userVATSIMData.flight_plan.arrival;
                userVATSIMData.flight_plan.altitude = string.IsNullOrWhiteSpace(userVATSIMData.flight_plan.altitude) ? "35000" : userVATSIMData.flight_plan.altitude;
                userVATSIMData.flight_plan.route = string.IsNullOrWhiteSpace(userVATSIMData.flight_plan.route) ? "DCT GED DCT" : userVATSIMData.flight_plan.route;

                if (reportFixes == null || reportFixes.Length == 0)
                {
                    reportFixes = new[] { "GED", "BOLBO", "OSKAN", "ERL", "MAG" };
                }

                nextFix = string.IsNullOrWhiteSpace(nextFix) ? reportFixes.FirstOrDefault() : nextFix;
                loadedFlightPlanSignature = BuildFlightPlanSignature(userVATSIMData);
                preserveLoadedFlightPlanOnLiveUpdate = true;

                if (string.IsNullOrWhiteSpace(CurrentATCUnit))
                {
                    CurrentATCUnit = "EDGG";
                }

                // DEBUG UI Preview must look connected to the existing UI gating code.
                // Do not start the real retrieve/logon flow here; outbound Hoppie traffic is still
                // suppressed in SendCPDLCMessage and the online refresh is short-circuited below.
                _connected = true;

                hoppieOnlineStationsLoaded = true;
                hoppieOnlineStations.Add("EDGG");
                hoppieOnlineStations.Add("EDDF");
                hoppieOnlineStations.Add("EDDP");

                pdcDiscoveryLogonCode = "EDDF";
                pdcDiscoveryController = "EDDF_DEL";
                pdcDiscoverySource = "DEBUG UI PREVIEW";
                pdcDiscoveryAllowReqClr = true;
                pdcDiscoveryIsFallbackCandidate = false;
                pdcDiscoveryHoverText = "DEBUG UI preview\nPDC/DCL action unlocked locally. Nothing is sent to Hoppie.";
                datalinkStatusText = "PDC AVAIL";

                cpdlcDiscoveryText = "possible";
                cpdlcDiscoveryLogonCode = "EDGG";
                cpdlcDiscoveryController = "EDGG_CTR";
                cpdlcDiscoveryHoverText = "DEBUG UI preview\nCPDLC LOGON action unlocked locally. Nothing is sent to Hoppie.";

                SetClearanceStatus("CLR RX");
                atisStatusText = BuildDotBadgeText("ATIS");
                atisAvailabilityState = "AVAILABLE";

                retrieveButton.Enabled = true;
                retrieveButton.Text = "DISC";
                telexButton.Enabled = true;
                atcButton.Enabled = true;
                settingsButton.Enabled = true;
                helpButton.Enabled = true;
                exitButton.Enabled = true;
                if (mainReloadFlightPlanButton != null) mainReloadFlightPlanButton.Enabled = true;
                if (mainMinimizeButton != null) mainMinimizeButton.Enabled = true;

                UpdateConnectionGatedControls();
                UpdateCurrentAtcUnitDisplay();
                UpdateCallsignDisplay();
                UpdateFlightPhaseBadge();
                UpdateClearanceStatusLabel();
                UpdateSmartStatusLabelColors();

                if (statusValueLabel != null)
                {
                    statusValueLabel.Text = "UI PREVIEW";
                    statusValueLabel.ForeColor = DcduTheme.Green;
                }

                if (firstInitialisation && !debugUiPreviewStartupMessageWritten)
                {
                    debugUiPreviewStartupMessageWritten = true;
                    WriteMessage("DEBUG UI PREVIEW MODE: BUTTONS ARE UNLOCKED LOCALLY. OUTBOUND HOPPIE MESSAGES ARE SUPPRESSED.", "SYSTEM", "SYSTEM");
                }

                if (firstInitialisation && !debugUiPreviewSampleMessagesWritten)
                {
                    debugUiPreviewSampleMessagesWritten = true;

                    _ = CPDLCParser(
                        "/data2/10//WU/CLD 1450 260706 EDDF PDC 001 DLH6YM CLRD TO @EDDN@ OFF @18@ VIA @CINDY8S@ SQUAWK @2675@ NEXT FREQ @121.855@ ATIS @E@ REPORT READY ON @121.855@",
                        "EGKK");

                    _ = CPDLCParser(
                        "/data2/11//WU/CLIMB TO @FL340@",
                        "EDGG");

                    WriteMessage("DEPART REQUEST STATUS\nFSM 1302 250727 EDMM\nDLH06F RCD REQUEST\nBEING PROCESSED\nSTANDBY", "TELEX", "EDMM", false, null);

                    // Intentionally oversized debug clearance. This is long enough
                    // to require several pages even in the roomier A220 message
                    // view, so PREV PAGE / NEXT PAGE and PAGE X/Y can be inspected
                    // in every DCDU style without waiting for a real long clearance.
                    string debugLongClearance =
                        "DEBUG LONG CLEARANCE - PAGING TEST\n" +
                        "CLEARED TO @EDDM@ VIA @ANEKI ONE NOVEMBER@ DEPARTURE, " +
                        "THEN @DCT DONAD DCT AKANU DCT TULSI DCT MASEK DCT NAPSA DCT ROKIL DCT BETOS DCT LANDU@. " +
                        "CLIMB INITIALLY TO @FL090@. EXPECT @FL230@ TEN MINUTES AFTER DEPARTURE. " +
                        "MAINTAIN @250 KNOTS@ OR LESS BELOW @FL100@. " +
                        "CONTACT DEPARTURE ON @120.155@ AFTER AIRBORNE. " +
                        "SQUAWK @4271@. " +
                        "AFTER PASSING @5000 FEET@ PROCEED DIRECT @DONAD@ UNLESS OTHERWISE INSTRUCTED. " +
                        "CROSS @AKANU@ AT OR ABOVE @FL120@ AND CROSS @TULSI@ AT OR BELOW @FL180@. " +
                        "EXPECT FURTHER CLIMB FROM MUNICH CONTROL. " +
                        "IN CASE OF RADIO FAILURE CONTINUE VIA THE CLEARED ROUTE, MAINTAIN THE LAST ASSIGNED LEVEL FOR SEVEN MINUTES, " +
                        "THEN CLIMB TO THE FLIGHT PLAN LEVEL. " +
                        "WHEN ABLE REPORT PASSING @FL150@ AND ESTIMATE @MASEK@. " +
                        "DUE TRAFFIC, SPEED @MACH 0.74@ MAY BE REQUIRED AFTER LEVEL OFF. " +
                        "DO NOT EXCEED @MACH 0.78@ UNTIL ADVISED. " +
                        "EXPECT POSSIBLE REROUTE AFTER @BETOS@ VIA @NATOR DCT GUPIN DCT INPUD@. " +
                        "DESTINATION WEATHER MAY REQUIRE HOLDING; EXPECT HOLD AT @LANDU@, RIGHT TURNS, INBOUND TRACK @184 DEGREES@, " +
                        "ONE MINUTE LEGS, EXPECT FURTHER CLEARANCE @35 MINUTES AFTER THE HOUR@. " +
                        "IF UNABLE TO COMPLY WITH ANY PART OF THIS CLEARANCE, ADVISE ATC BEFORE DEPARTURE. " +
                        "READ BACK RUNWAY, SID, INITIAL LEVEL, SQUAWK AND ANY SPEED OR LEVEL RESTRICTIONS. " +
                        "THIS FINAL SENTENCE EXISTS ONLY TO MAKE THE DEBUG MESSAGE LONG ENOUGH TO VERIFY THAT NO TEXT IS CUT OFF " +
                        "AND THAT THE LAST PAGE IS REACHABLE USING THE NEW PAGING CONTROLS.";

                    WriteMessage(
                        debugLongClearance,
                        "CPDLC",
                        "EDMM",
                        false,
                        null);
                }
            }
            catch (Exception ex)
            {
                Logger.Debug("Debug UI preview initialisation failed: " + ex.Message);
            }
        }

        public static Font CreateDpiStablePointFont(string familyName, float pointSizeAt96Dpi, FontStyle style)
        {
            // The DCDU UI is pixel-positioned over a fixed bitmap.
            // WinForms/Windows DPI text scaling would otherwise enlarge fonts at 125/150%
            // while the cockpit frame and control rectangles stay fixed.
            return new Font(familyName, Math.Max(1.0f, pointSizeAt96Dpi * 96.0f / 72.0f * WindowScaleFactor()), style, GraphicsUnit.Pixel);
        }

        public static Font CreateDpiStablePixelFont(FontFamily family, float pixelSize, FontStyle style)
        {
            return new Font(family, Math.Max(1.0f, pixelSize * WindowScaleFactor()), style, GraphicsUnit.Pixel);
        }



        private Color MainAccentColor()
        {
            return DcduStyleManager.IsBoeing
                ? Color.FromArgb(86, 255, 103)
                : DcduTheme.Cyan;
        }

        private Color MainPrimaryTextColor()
        {
            return DcduStyleManager.IsBoeing
                ? Color.FromArgb(224, 232, 238)
                : DcduTheme.CyanWhite;
        }

        private Color PopupBorderAccent(Color accent)
        {
            if (!DcduStyleManager.IsBoeing)
            {
                return accent;
            }

            if (accent.R >= 220 && accent.G >= 160 && accent.B <= 140)
            {
                return Color.FromArgb(196, 180, 128);
            }

            if (accent.R >= 180 && accent.G <= 135)
            {
                return Color.FromArgb(192, 146, 142);
            }

            if (accent.G >= accent.R + 18)
            {
                return Color.FromArgb(176, 188, 194);
            }

            return Color.FromArgb(180, 188, 194);
        }

        private Font PopupPixelFont(float pixelSize, FontStyle style = FontStyle.Bold)
        {
            FontFamily family = textFontBold?.FontFamily ?? Font.FontFamily;
            return CreateDpiStablePixelFont(family, pixelSize, style);
        }

