        private Color PopupContentTextColor(Color accent)
        {
            if (!DcduStyleManager.IsBoeing)
            {
                return accent;
            }

            if (accent.R >= 220 && accent.G >= 160 && accent.B <= 140)
            {
                return Color.FromArgb(220, 200, 144);
            }

            if (accent.R >= 180 && accent.G <= 135)
            {
                return Color.FromArgb(224, 164, 154);
            }

            return MainPrimaryTextColor();
        }

        private void PaintStyleAwarePopupPanel(Panel panel, PaintEventArgs e, Color accent, bool pinned)
        {
            if (panel == null)
            {
                return;
            }

            Rectangle bounds = new Rectangle(0, 0, Math.Max(1, panel.Width - 1), Math.Max(1, panel.Height - 1));

            e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;
            e.Graphics.PixelOffsetMode = PixelOffsetMode.HighQuality;

            if (DcduStyleManager.IsA220)
            {
                // A220 overview action menus use the same flat, recessed visual
                // language as the cockpit push/select controls.
                e.Graphics.SmoothingMode = SmoothingMode.None;
                e.Graphics.PixelOffsetMode = PixelOffsetMode.None;

                using SolidBrush shadowBrush = new(Color.FromArgb(5, 7, 10));
                using SolidBrush faceBrush = new(Color.FromArgb(16, 20, 25));
                using Pen outerBorder = new(Color.FromArgb(20, 27, 34), 1.0f);
                using Pen innerBorder = new(Color.FromArgb(119, 132, 143), 1.0f);
                using Pen topEdge = new(Color.FromArgb(48, 60, 70), 1.0f);

                e.Graphics.FillRectangle(shadowBrush, bounds);
                Rectangle face = Rectangle.Inflate(bounds, -1, -1);
                e.Graphics.FillRectangle(faceBrush, face);
                e.Graphics.DrawRectangle(outerBorder, bounds);
                if (face.Width > 2 && face.Height > 2)
                {
                    e.Graphics.DrawRectangle(innerBorder, face);
                    e.Graphics.DrawLine(topEdge, face.Left + S(3), face.Top + S(1), face.Right - S(3), face.Top + S(1));
                }
                return;
            }

            using GraphicsPath path = RoundedButtonRect(bounds, S(DcduStyleManager.IsBoeing ? 4 : 6));

            if (DcduStyleManager.IsBoeing)
            {
                // Boeing: neutral dark glass with only a subtle, desaturated status hint.
                Color popupAccent = PopupBorderAccent(accent);
                using LinearGradientBrush fill = new LinearGradientBrush(
                    bounds,
                    Color.FromArgb(240, 14, 22, 27),
                    Color.FromArgb(240, 7, 12, 16),
                    LinearGradientMode.Vertical);
                using SolidBrush accentWash = new SolidBrush(Color.FromArgb(pinned ? 14 : 8, popupAccent));
                using Pen border = new Pen(Color.FromArgb(pinned ? 196 : 142, popupAccent), pinned ? ScaleUi(1.25f) : ScaleUi(1.0f));
                using Pen boeingTopLine = new Pen(Color.FromArgb(34, Color.White), 1.0f);

                e.Graphics.FillPath(fill, path);
                e.Graphics.FillPath(accentWash, path);
                e.Graphics.DrawPath(border, path);
                e.Graphics.DrawLine(boeingTopLine, bounds.Left + S(6), bounds.Top + S(1), bounds.Right - S(6), bounds.Top + S(1));
                return;
            }

            // Airbus: neutral Airbus/DCDU panel fill. Only the border carries the status color.
            using LinearGradientBrush fillAirbus = new LinearGradientBrush(
                bounds,
                Color.FromArgb(236, 8, 17, 28),
                Color.FromArgb(236, 3, 8, 16),
                LinearGradientMode.Vertical);
            using Pen borderAirbus = new Pen(Color.FromArgb(pinned ? 210 : 150, accent), pinned ? ScaleUi(1.35f) : ScaleUi(1.0f));
            using Pen topLine = new Pen(Color.FromArgb(38, Color.White), 1.0f);

            e.Graphics.FillPath(fillAirbus, path);
            e.Graphics.DrawPath(borderAirbus, path);
            e.Graphics.DrawLine(topLine, bounds.Left + S(6), bounds.Top + S(1), bounds.Right - S(6), bounds.Top + S(1));
        }

        private void ApplyMainThemeColors()
        {
            controlFrontColor = MainPrimaryTextColor();

            if (titleLabel != null)
            {
                titleLabel.Text = string.Empty;
                titleLabel.Visible = false;
            }

            if (clockLabel != null)
            {
                clockLabel.Text = string.Empty;
                clockLabel.Visible = false;
            }

            if (messageHeaderLabel != null)
            {
                messageHeaderLabel.ForeColor = DcduStyleManager.IsBoeing ? MainPrimaryTextColor() : MainAccentColor();
            }

            if (clockLabel != null)
            {
                clockLabel.ForeColor = MainPrimaryTextColor();
            }

            if (statusCaptionLabel != null)
            {
                statusCaptionLabel.ForeColor = MainPrimaryTextColor();
            }

            UpdateCurrentAtcUnitDisplay();
            UpdateCallsignDisplay();
            UpdateFlightPhaseBadge();

            if (popupMenu != null)
            {
                popupMenu.BackColor = controlBackColor;
                popupMenu.ForeColor = controlFrontColor;
                foreach (ToolStripItem item in popupMenu.Items)
                {
                    item.ForeColor = controlFrontColor;
                    item.BackColor = controlBackColor;
                }
            }

            UpdateSmartStatusLabelColors();
            RefreshVisibleMessageColors();
        }

