        private bool CanUseA220StatusActions()
        {
            return !DcduStyleManager.IsA220 || Connected;
        }

        private void UpdateA220StatusActionAvailability()
        {
            bool enabled = CanUseA220StatusActions();

            foreach (System.Windows.Forms.Label label in new[]
            {
                clearanceStatusLabel,
                datalinkStatusLabel,
                atisStatusLabel,
                atisAutoStatusLabel,
                quickWxStatusLabel
            })
            {
                if (label == null || label.IsDisposed)
                {
                    continue;
                }

                label.Enabled = enabled;
                label.Cursor = enabled ? Cursors.Hand : Cursors.Default;
                label.TabStop = enabled;
                label.Invalidate();
            }

            if (!enabled)
            {
                HideClearanceTimelinePopup();
                HidePdcQuickActionButton();
                HideAtisAvailabilityPopup();
                HideAtisAutoPopup();
                HideQuickWxPopup();
            }
        }

        private Color ClearanceStatusColor()
        {
            if (IsAirborneForStatusBadges())
            {
                return NeutralStatusBadgeColor();
            }

            string upper = (clearanceStatusText ?? string.Empty).ToUpperInvariant();

            // CLR logic:
            // white = standby / nothing yet / received-neutral
            // amber = request sent, waiting for reply or pilot acknowledged but ATC did not confirm
            // green = ATC/network confirmed clearance
            // red = rejected
            if (upper.Contains("ACK") && upper.Contains("AUTO"))
            {
                return DcduTheme.Amber;
            }

            if (upper.Contains("ACCEPTED") || upper.Contains("ACC"))
            {
                return DcduTheme.Green;
            }

            if (upper.Contains("RECEIVED") || upper.Contains(" RX"))
            {
                // Clearance received / PDC response is not final confirmation yet.
                // Keep CLR amber until ATC/network confirmation changes it to CLR ACC.
                return DcduTheme.Amber;
            }

            if (upper.Contains("REJECTED") || upper.Contains("REJ"))
            {
                return Color.FromArgb(255, 86, 74);
            }

            if (upper.Contains("REQUESTED") || upper.Contains("REQ"))
            {
                return DcduTheme.Amber;
            }

            return NeutralStatusBadgeColor();
        }

        private Color DatalinkStatusColor()
        {
            if (IsAirborneForStatusBadges())
            {
                return NeutralStatusBadgeColor();
            }

            string upper = (datalinkStatusText ?? string.Empty).ToUpperInvariant();

            // PDC availability is based on the Hoppie callsign list:
            // white = unknown/not checked yet, red = no CPDLC/PDC station found, green = station available.
            if (upper.Contains("AVAIL"))
            {
                return DcduTheme.Green;
            }

            if (upper.Contains("MAYBE") || upper.Contains("POSSIBLE"))
            {
                return DcduTheme.Amber;
            }

            if (upper.Contains("NONE"))
            {
                return Color.FromArgb(255, 86, 74);
            }

            if (upper.Contains("?") || upper.Contains("--"))
            {
                return NeutralStatusBadgeColor();
            }

            return NeutralStatusBadgeColor();
        }

        private Color AtisStatusColor()
        {
            string upper = (atisAvailabilityState ?? string.Empty).ToUpperInvariant();

            if (upper == "ONLINE")
            {
                return DcduTheme.Green;
            }

            if (upper == "OFFLINE")
            {
                return Color.FromArgb(255, 86, 74);
            }

            return NeutralStatusBadgeColor();
        }

        private Color AtisAutoStatusColor()
        {
            return IsAtisAutoRefreshEnabled()
                ? DcduTheme.Green
                : Color.FromArgb(255, 86, 74);
        }

        private Color NeutralStatusBadgeColor()
        {
            return Color.FromArgb(182, 188, 194);
        }

        private void ApplyMainBadgeStyle(System.Windows.Forms.Label label, Color color, bool bold)
        {
            if (label == null)
            {
                return;
            }

            label.ForeColor = color;
            label.BackColor = Color.Transparent;
            label.BorderStyle = BorderStyle.None;
            label.Font = CreateDpiStablePixelFont(
                bold ? textFontBold.FontFamily : textFont.FontFamily,
                Math.Max(7.0f, (bold ? textFontBold.Size : textFont.Size) - 2.7f),
                bold ? FontStyle.Bold : FontStyle.Regular);
            label.Invalidate();
        }

        private void MainStatusBadge_Paint(object sender, PaintEventArgs e)
        {
            if (sender is not System.Windows.Forms.Label label)
            {
                return;
            }

            if (string.Equals(label.AccessibleDescription, "DCDU_STYLED_MESSAGE_ACTION", StringComparison.Ordinal))
            {
                // Styled message-preview actions are real DCDU line-select text.
                // Do not paint the generic rounded button box here.
                return;
            }

            Rectangle bounds = new Rectangle(0, 0, Math.Max(1, label.Width - 1), Math.Max(1, label.Height - 1));
            bool enabled = label.Enabled;
            Color accent = enabled ? label.ForeColor : Color.FromArgb(105, 110, 116);
            bool focused = enabled && label.Focused;
            bool hovered = enabled && label.ClientRectangle.Contains(label.PointToClient(Cursor.Position));

            e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;
            e.Graphics.PixelOffsetMode = PixelOffsetMode.HighQuality;

            using GraphicsPath path = RoundedButtonRect(bounds, 3);
            using LinearGradientBrush fill = new LinearGradientBrush(
                bounds,
                Color.FromArgb(enabled ? 34 : 18, accent),
                Color.FromArgb(enabled ? 12 : 7, accent),
                LinearGradientMode.Vertical);
            using Pen border = new Pen(
                Color.FromArgb(enabled ? ((focused || hovered) ? 180 : 112) : 70, accent),
                (focused || hovered) ? ScaleUi(1.35f) : ScaleUi(1.0f));
            using Pen topLine = new Pen(Color.FromArgb(enabled ? 45 : 20, Color.White), 1.0f);

            e.Graphics.FillPath(fill, path);
            e.Graphics.DrawPath(border, path);
            e.Graphics.DrawLine(topLine, bounds.Left + 4, bounds.Top + 1, bounds.Right - 4, bounds.Top + 1);

            TextRenderer.DrawText(
                e.Graphics,
                label.Text,
                label.Font,
                Rectangle.Inflate(bounds, -4, -1),
                enabled ? (hovered ? Color.White : accent) : Color.FromArgb(112, 116, 121),
                TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPadding | TextFormatFlags.EndEllipsis);
        }

        private void RefreshVisibleMessageColors()
        {
            if (outputTable == null || outputTable.IsDisposed)
            {
                return;
            }

            foreach (Control control in outputTable.Controls)
            {
                if (control is CPDLCMessage message)
                {
                    bool isUnread = unreadMessages.Contains(message);
                    bool emphasizeAtisLetter = ShouldEmphasizeAtisLetter(message);

                    if (message is AtisOverviewMessage atisMessage)
                    {
                        atisMessage.BoldAtisLetter = emphasizeAtisLetter;
                        atisMessage.AtisLetterBoldFont = CreateDpiStablePixelFont(GetMessageTextFont(true).FontFamily, GetMessageTextFont(true).Size + 0.25f, FontStyle.Bold);
                    }

                    if (IsCallsignMismatchAlarmText(message.message))
                    {
                        message.Font = GetMessageTextFont(true);
                        message.ForeColor = CallsignMismatchAlarmColor();
                    }
                    else if (isUnread)
                    {
                        message.Font = GetMessageTextFont(true);

                        if (MessageNeedsOverviewReplyIndicator(message.type, message.outbound, message.header) && !message.acknowledged)
                        {
                            SetReplyStatusTimeLabel(message, "◷", DcduTheme.Amber);
                            message.ForeColor = MainPrimaryTextColor();
                        }
                        else
                        {
                            message.ForeColor = DcduTheme.Amber;
                        }
                    }
                    else if (message.acknowledged)
                    {
                        message.Font = GetMessageTextFont(false);
                        if (MessageNeedsOverviewReplyIndicator(message.type, message.outbound, message.header))
                        {
                            SetReplyStatusTimeLabel(message, "✓", DcduTheme.Green);
                        }

                        message.ForeColor = SystemColors.ControlDark;
                    }
                    else
                    {
                        message.Font = GetMessageTextFont(false);
                        message.ForeColor = MainPrimaryTextColor();
                    }

                    message.Invalidate();
                }
                else if (control is TimerLabel timerLabel)
                {
                    TableLayoutPanelCellPosition pos = outputTable.GetPositionFromControl(timerLabel);
                    bool isCallsignAlarmMarker = timerLabel.Text == UnreadMessageMarkerText &&
                        pos.Row >= 0 &&
                        outputTable.GetControlFromPosition(1, pos.Row) is CPDLCMessage linkedMessage &&
                        IsCallsignMismatchAlarmText(linkedMessage.message);

                    if (isCallsignAlarmMarker)
                    {
                        timerLabel.ForeColor = CallsignMismatchAlarmColor();
                    }
                    else if (timerLabel.Text == UnreadMessageMarkerText)
                    {
                        timerLabel.ForeColor = DcduTheme.Amber;
                    }
                    else
                    {
                        timerLabel.ForeColor = MainPrimaryTextColor();
                    }
                }
                else if (control is ReplyStatusTimeLabel replyTimeLabel)
                {
                    replyTimeLabel.ForeColor = MainPrimaryTextColor();
                    replyTimeLabel.Invalidate();
                }
                else if (control is AccessibleLabel label)
                {
                    label.ForeColor = MainPrimaryTextColor();
                }
            }
        }

        public void ApplyDisplayStyle()
        {
            bool isBoeing = DcduStyleManager.IsBoeing;
            bool isA220 = DcduStyleManager.IsA220;
            ApplyMainWindowBounds(isBoeing);
            if (dcduFrame != null)
            {
                // A220 is intentionally code-drawn: only a blue-grey bezel and
                // the touchscreen UI, never the Airbus/Boeing DCDU artwork.
                dcduFrame.DrawA220Bezel = isA220;
                dcduFrame.AssetFileName = isA220
                    ? string.Empty
                    : DcduStyleManager.AssetFile("DCDU_Main_V15.png");
                dcduFrame.HighlightRectangle = Rectangle.Empty;
                dcduFrame.HighlightPressed = false;
                dcduFrame.Invalidate();
            }

            ConfigureA220InteriorBackdrop();
            ConfigureA220Navigation();
            ApplyMainScreenLayout(isBoeing);

            // A style switch can change between hardware LSK paging and the
            // normal flexible list. Reapply filtering immediately so rows hidden
            // by Airbus/Boeing paging are restored when entering A220/standard
            // mode, and so the correct page capacity is applied on Boeing.
            ApplyMessageFilter();
            HideNativeOutputScrollbars();

            ApplyMainButtonLayout(isBoeing);
            ConfigureInboundMessageSound();
            ApplyMainThemeColors();
            ConfigureTransparentScrollDoubleBuffer();
            ConfigureMsfsClickGuard();
            if (DcduStyleManager.IsA220)
            {
                a220InteriorBackdrop?.SendToBack();
                screenPanel?.BringToFront();
                a220NavigationPanel?.BringToFront();
            }
            Invalidate(true);
        }

        private void ConfigureMsfsClickGuard()
        {
            if (!MsfsClickGuardEnabled)
            {
                return;
            }

            try
            {
                MouseDown -= EasyCpdlcCaptureFocus_MouseDown;
                MouseDown += EasyCpdlcCaptureFocus_MouseDown;
                ControlAdded -= EasyCpdlcRoot_ControlAdded;
                ControlAdded += EasyCpdlcRoot_ControlAdded;

                HookClickGuardRecursive(this);
            }
            catch
            {
            }
        }

        private void EasyCpdlcRoot_ControlAdded(object sender, ControlEventArgs e)
        {
            HookClickGuardRecursive(e.Control);
        }

        private void HookClickGuardRecursive(Control control)
        {
            if (control == null)
            {
                return;
            }

            control.MouseDown -= EasyCpdlcCaptureFocus_MouseDown;
            control.MouseDown += EasyCpdlcCaptureFocus_MouseDown;

            control.ControlAdded -= EasyCpdlcChild_ControlAdded;
            control.ControlAdded += EasyCpdlcChild_ControlAdded;

            foreach (Control child in control.Controls)
            {
                HookClickGuardRecursive(child);
            }
        }

        private void EasyCpdlcChild_ControlAdded(object sender, ControlEventArgs e)
        {
            HookClickGuardRecursive(e.Control);
        }

        private void EasyCpdlcCaptureFocus_MouseDown(object sender, MouseEventArgs e)
        {
            CaptureEasyCpdlcFocus();
        }

        private void CaptureEasyCpdlcFocus()
        {
            try
            {
                if (IsDisposed)
                {
                    return;
                }

                if (WindowState == FormWindowState.Minimized)
                {
                    ShowWindow(Handle, SW_RESTORE);
                }

                if (!ContainsFocus)
                {
                    Activate();
                }

                TopMost = true;
                BringToFront();
                SetForegroundWindow(Handle);
            }
            catch
            {
            }
        }

