                ? CreateDpiStablePointFont("Consolas", 11.2f, FontStyle.Bold)
                : isBoeing
                    ? CreateDpiStablePointFont("Segoe UI Semibold", 9.3f, FontStyle.Regular)
                    : CreateDpiStablePointFont("Consolas", 9.8f, FontStyle.Bold);
