        private static string BuildDotBadgeText(string title)
        {
            return string.IsNullOrWhiteSpace(title)
                ? "●"
                : title.Trim().ToUpperInvariant() + " ●";
        }

        private static string BuildAircraftBadgeText(string title)
        {
            return string.IsNullOrWhiteSpace(title)
                ? "✈"
                : title.Trim().ToUpperInvariant() + " ✈";
        }

        private bool IsAirborneForStatusBadges()
        {
            return ShouldUseArrivalAtisForHover();
        }

        private string BuildClearanceBadgeText()
        {
            if (IsAirborneForStatusBadges())
            {
                return BuildAircraftBadgeText("CLR");
            }

            string upper = (clearanceStatusText ?? string.Empty).ToUpperInvariant();

            if ((upper.Contains("ACK") && upper.Contains("AUTO")) ||
                upper.Contains("ACCEPTED") ||
                upper.Contains("ACC"))
            {
                return "CLR ✓";
            }

            return BuildDotBadgeText("CLR");
        }

        private string BuildPdcBadgeText()
        {
            return IsAirborneForStatusBadges()
                ? BuildAircraftBadgeText("PDC")
                : BuildDotBadgeText("PDC");
        }

        private string BuildAtisAutoBadgeText()
        {
            return "↻";
        }

        private void UpdateAtisAutoStatusLabel()
        {
            if (atisAutoStatusLabel != null)
            {
                atisAutoStatusLabel.Text = BuildAtisAutoBadgeText();
                atisAutoStatusLabel.ForeColor = AtisAutoStatusColor();
                atisAutoStatusLabel.Invalidate();
            }

            if (atisAutoPopupPanel != null && atisAutoPopupPanel.Visible)
            {
                UpdateAtisAutoPopupText();
            }
        }

        private void UpdateClearanceStatusLabel()
        {
            if (clearanceStatusLabel != null)
            {
                clearanceStatusLabel.Text = BuildClearanceBadgeText();
                clearanceStatusLabel.ForeColor = ClearanceStatusColor();
                clearanceStatusLabel.Invalidate();
            }

            if (datalinkStatusLabel != null)
            {
                datalinkStatusLabel.Text = BuildPdcBadgeText();
                datalinkStatusLabel.ForeColor = DatalinkStatusColor();
                smartStatusToolTip.SetToolTip(datalinkStatusLabel, pdcDiscoveryHoverText);
                datalinkStatusLabel.Invalidate();
            }

            UpdateCpdlcDiscoveryLabel();

            if (atisStatusLabel != null)
            {
                atisStatusLabel.Text = atisStatusText;
                atisStatusLabel.ForeColor = AtisStatusColor();
                atisStatusLabel.Invalidate();
            }

            if (pdcActionDebugLabel != null)
            {
                pdcActionDebugLabel.ForeColor = DcduTheme.Amber;
                if (pdcActionDebugLabel.Visible && !CanQuickRequestClearance())
                {
                    pdcActionDebugLabel.Visible = false;
                }
                pdcActionDebugLabel.Invalidate();
            }

            if (cpdlcActionDebugLabel != null)
            {
                cpdlcActionDebugLabel.ForeColor = DcduTheme.Amber;
                if (cpdlcActionDebugLabel.Visible && !CanQuickCpdlcLogon())
                {
                    cpdlcActionDebugLabel.Visible = false;
                }
                cpdlcActionDebugLabel.Invalidate();
            }

            UpdateAtisAutoStatusLabel();

            UpdateSmartStatusLabelColors();

            if (clearanceTimelinePopupPanel != null && clearanceTimelinePopupPanel.Visible)
            {
                UpdateClearanceHoverPopupText();
            }
        }

        private void SetClearanceStatus(string status)
        {
            if (string.IsNullOrWhiteSpace(status))
            {
                return;
            }

            clearanceStatusText = status.Trim().ToUpperInvariant();

            if (clearanceStatusText.Contains("REQ") ||
                clearanceStatusText.Contains("ACC") ||
                clearanceStatusText.Contains("REJ") ||
                clearanceStatusText.Contains("STBY"))
            {
                StopClearanceAutoConfirmTimer();
            }

            // Any real response/failure finishes the temporary station-offline
            // watch. CLR REQ is the only state in which that watch may continue.
            if (!clearanceStatusText.Contains("REQ"))
            {
                CancelPdcStationOfflineWatch();
            }

            SafeUi(() =>
            {
                UpdateClearanceStatusLabel();
                UpdateSmartStatusLabelColors();
            });
        }

        private void TrackClearanceStatus(string contents, string type, bool outbound)
        {
            if (string.IsNullOrWhiteSpace(contents))
            {
                return;
            }

            string normalizedType = (type ?? string.Empty).Trim().ToUpperInvariant();

            if (normalizedType != "CPDLC" && normalizedType != "TELEX")
            {
                return;
            }

            string upper = contents.ToUpperInvariant();

            if (!IsClearanceStatusText(upper))
            {
                return;
            }

            if (outbound)
            {
                lastClearanceHoverText = string.Empty;
                SetClearanceStatus("CLR REQ");
                return;
            }

            if (IsClearanceConfirmationText(upper))
            {
                // The green check means the network/controller confirmed the clearance,
                // not merely that the pilot clicked WILCO.
                SetClearanceStatus("CLR ACC");
                return;
            }

            if (upper.Contains("REJECT") || upper.Contains("UNABLE") || upper.Contains("DENIED"))
            {
                SetClearanceStatus("CLR REJ");
                return;
            }

            if (IsClearanceDeliveryText(upper))
            {
                lastClearanceHoverText = NormalizeClearanceHoverText(contents);
                SetClearanceStatus("CLR RX");
                return;
            }

            SetClearanceStatus("CLR RX");
        }

        private static bool IsClearanceStatusText(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            string upper = text.ToUpperInvariant();

            return upper.Contains("CLEARANCE") ||
                   upper.Contains("CLR TO") ||
                   upper.Contains("CLRD TO") ||
                   upper.Contains("CLEARED TO") ||
                   upper.Contains("PREDEP") ||
                   upper.Contains("PDC");
        }

        private void TrackClearanceReply(CPDLCMessage message, string reply)
        {
            if (message == null || !IsClearanceStatusText(message.message))
            {
                return;
            }

            string upperReply = (reply ?? string.Empty).ToUpperInvariant();

            if (upperReply == "STANDBY")
            {
                SetClearanceStatus("CLR STBY");
            }
            else if (upperReply == "UNABLE" || upperReply == "NEGATIVE" || upperReply == "REJECT")
            {
                SetClearanceStatus("CLR REJ");
            }
            else if (upperReply == "WILCO" || upperReply == "AFFIRMATIVE" || upperReply == "ROGER" || upperReply == "ACCEPT")
            {
                // Pilot acknowledgement sent. Some Hoppie/PDC/DCL stations never send
                // a final CLRC/CLEARANCE CONFIRMED. Keep RX first, then auto-confirm
                // after a quiet timeout so the green check does not stay missing forever.
                SetClearanceStatus("CLR RX");
                StartClearanceAutoConfirmTimer(upperReply);
            }
        }

        private void MessageFilterLabel_Click(object sender, EventArgs e)
        {
            if (messageFilterLabel == null)
            {
                return;
            }

            ConfigureFilterDropdownMenu();
            filterMenu.Show(messageFilterLabel, new Point(0, messageFilterLabel.Height + 2));
        }

        private void ConfigureFilterDropdownMenu()
        {
            filterMenu.Items.Clear();
            filterMenu.BackColor = Color.FromArgb(4, 9, 13);
            filterMenu.ForeColor = MainPrimaryTextColor();
            filterMenu.Font = DcduStyleManager.IsBoeing
                ? CreateDpiStablePointFont("Segoe UI Semibold", 8.6f, FontStyle.Regular)
                : textFontBold;
            filterMenu.ShowImageMargin = false;
            filterMenu.ShowCheckMargin = false;
            filterMenu.RenderMode = ToolStripRenderMode.Professional;
            filterMenu.Renderer = new DcduMenuRenderer();
            filterMenu.Padding = new Padding(DcduStyleManager.IsBoeing ? 1 : 2);

            foreach (string filter in messageFilterOrder)
            {
                int count = CountVisibleMessagesForFilter(filter);
                Logger.Debug("Message filter count " + filter + "=" + count);
                ToolStripMenuItem item = CreateFilterMenuItem(filter, count);
                filterMenu.Items.Add(item);
            }
        }

        private ToolStripMenuItem CreateFilterMenuItem(string filter, int count)
        {
            bool selected = string.Equals(filter, activeMessageFilter, StringComparison.OrdinalIgnoreCase);

            ToolStripMenuItem item = new ToolStripMenuItem(filter + "   " + count)
            {
                AutoSize = false,
                Size = DcduStyleManager.IsBoeing ? new Size(108, 24) : new Size(118, 28),
                BackColor = selected
                    ? (DcduStyleManager.IsBoeing ? Color.FromArgb(12, 34, 42) : Color.FromArgb(20, MainAccentColor()))
                    : Color.FromArgb(4, 9, 13),
                ForeColor = selected ? DcduTheme.Amber : MainPrimaryTextColor(),
                Font = DcduStyleManager.IsBoeing
                    ? CreateDpiStablePointFont("Segoe UI Semibold", 8.6f, FontStyle.Regular)
                    : (selected ? textFontBold : textFont),
                Tag = filter,
                Padding = DcduStyleManager.IsBoeing ? new Padding(7, 0, 6, 0) : new Padding(8, 0, 8, 0),
                TextAlign = ContentAlignment.MiddleLeft
            };

            item.Click += FilterMenuItem_Click;
            return item;
        }

        private void FilterMenuItem_Click(object sender, EventArgs e)
        {
            if (sender is ToolStripMenuItem item && item.Tag is string filter)
            {
                activeMessageFilter = filter;
                standardOverviewExtentValid = false;
                ResetHardwareMessageOverviewPage();
                ApplyMessageFilter();
            }
        }

        private void UpdateMessageFilterLabel()
        {
            if (messageFilterLabel == null)
            {
                return;
            }

            messageFilterLabel.Text = activeMessageFilter == "ALL" ? "ALL ▾" : activeMessageFilter + " ▾";
            UpdateSmartStatusLabelColors();
        }

        private int CountVisibleMessagesForFilter(string filter)
        {
            if (outputTable == null || outputTable.IsDisposed)
            {
                return 0;
            }

            int count = 0;

            foreach (Control control in outputTable.Controls)
            {
                if (control is CPDLCMessage message && MessageMatchesFilter(message, filter))
                {
                    count++;
                }
            }

            return count;
        }

        private bool MessageMatchesFilter(CPDLCMessage message, string filter)
        {
            if (message == null)
            {
                return false;
            }

            string normalizedFilter = string.IsNullOrWhiteSpace(filter) ? "ALL" : filter.ToUpperInvariant();
            string type = (message.type ?? string.Empty).ToUpperInvariant();

            bool looksAtis = MessageLooksAtis(message);
            bool looksMetar = MessageLooksMetar(message);

            return normalizedFilter switch
            {
                "ALL" => true,
                "NEW" => unreadMessages.Contains(message),
                "ATIS" => looksAtis,
                "METAR" => looksMetar,
                "CPDLC" => string.Equals(type, "CPDLC", StringComparison.OrdinalIgnoreCase) && !looksAtis && !looksMetar,
                "TELEX" => string.Equals(type, "TELEX", StringComparison.OrdinalIgnoreCase),
                "SYSTEM" => string.Equals(type, "SYSTEM", StringComparison.OrdinalIgnoreCase),
                _ => true
            };
        }

        private bool MessageLooksAtis(CPDLCMessage message)
        {
            if (message == null)
            {
                return false;
            }

            string type = (message.type ?? string.Empty).ToUpperInvariant();
            string recipient = (message.recipient ?? string.Empty).ToUpperInvariant();
            string contents = message.message ?? string.Empty;
            string upperContents = contents.ToUpperInvariant();
            string listText = (message.Text ?? string.Empty).ToUpperInvariant();

            return string.Equals(type, "ATIS", StringComparison.OrdinalIgnoreCase) ||
                   ShouldUseAtisListText(contents, type, recipient) ||
                   listText.StartsWith("ATIS ", StringComparison.Ordinal) ||
                   listText.Contains(" ATIS ") ||
                   listText.Contains("_ATIS") ||
                   listText.Contains("REQUESTING ATIS") ||
                   Regex.IsMatch(listText, @"\b[A-Z0-9]{4}\s+ATIS\b") ||
                   Regex.IsMatch(upperContents, @"\b[A-Z0-9]{4}\s+ATIS\b") ||
                   upperContents.Contains("_ATIS");
        }

        private bool MessageLooksMetar(CPDLCMessage message)
        {
            if (message == null)
            {
                return false;
            }

            string type = (message.type ?? string.Empty).ToUpperInvariant();
            string recipient = (message.recipient ?? string.Empty).ToUpperInvariant();
            string contents = message.message ?? string.Empty;
            string upperContents = contents.ToUpperInvariant();
            string listText = (message.Text ?? string.Empty).ToUpperInvariant();

            return string.Equals(type, "METAR", StringComparison.OrdinalIgnoreCase) ||
                   ShouldUseMetarListText(contents, type, recipient) ||
                   listText.StartsWith("METAR ", StringComparison.Ordinal) ||
                   listText.Contains(" METAR ") ||
                   listText.Contains("REQUESTING METAR") ||
                   Regex.IsMatch(listText, @"\b[A-Z][A-Z0-9]{3}\s+METAR\b") ||
                   Regex.IsMatch(upperContents, @"\b[A-Z][A-Z0-9]{3}\s+\d{6}Z\b");
        }

        private int A220OverviewMessageMaxWidth()
        {
            return StandardOverviewMessageMaxWidth();
        }

        // Percentage columns combined with AutoSize labels can make WinForms
        // enlarge the *whole table's scrollable area* when a long clearance
        // arrives. After a hardware -> standard switch that leaves the time
        // and menu columns off screen, even on A220. Keep all three columns
        // absolute and fit them within the actual outputTable viewport.
        private void FitMessageOverviewColumns(bool hardwareMode)
        {
            if (outputTable == null || outputTable.IsDisposed ||
                outputTable.ColumnStyles.Count < 3)
            {
                return;
            }

            outputTable.AutoSize = false;
            int timeWidth = S(DcduStyleManager.IsBoeing ? 74 : 68);
            int actionWidth = hardwareMode ? 0 : OpenMessageActionsIndicatorWidth();
            // Keep room for the normal-mode vertical scroll bar even when it
            // is not currently visible; toggling it must not change line wrap.
            int scrollbarReserve = hardwareMode ? S(3) :
                SystemInformation.VerticalScrollBarWidth + S(4);
            int available = Math.Max(S(150),
                outputTable.ClientSize.Width - outputTable.Padding.Horizontal -
                scrollbarReserve);
            int messageWidth = Math.Max(S(70),
                available - timeWidth - actionWidth);

            outputTable.ColumnStyles[0].SizeType = SizeType.Absolute;
            outputTable.ColumnStyles[0].Width = timeWidth;
            outputTable.ColumnStyles[1].SizeType = SizeType.Absolute;
            outputTable.ColumnStyles[1].Width = messageWidth;
            outputTable.ColumnStyles[2].SizeType = SizeType.Absolute;
            outputTable.ColumnStyles[2].Width = actionWidth;
        }

        private int StandardOverviewMessageMaxWidth()
        {
            if (outputTable == null || outputTable.IsDisposed ||
                outputTable.ColumnStyles.Count < 3)
            {
                return S(300);
            }

            // The second column's width is fixed by FitMessageOverviewColumns.
            // No AutoSize label may request more than this bounded cell width.
            return Math.Max(S(70),
                (int)Math.Floor(outputTable.ColumnStyles[1].Width) - S(7));
        }

        private int HardwareOverviewRowHeight(int slot)
        {
            if (!DcduStyleManager.IsBoeing)
            {
                return S(42);
            }

            // The physical Boeing LSK3..6 centres are 41/42/41 pixels apart.
            // A uniform 42px pitch makes the last message drift visibly.
            return S(slot == 0 || slot == 2 ? 41 :
                     slot == 1 ? 42 : 44);
        }

        private int HardwareOverviewTextTopInset(
            int slot, int precedingRowHeight, int labelHeight)
        {
            if (screenPanel == null || outputTable == null)
            {
                return S(12);
            }

            Rectangle physicalLsk = MessageOverviewLeftLskBounds(
                MessageOverviewFirstLeftLskIndex() + slot);

            // Position all text in a slot from one physical LSK centre and
            // ONE shared height: measured label.PreferredSize used to differ
            // between status timestamps and normal text, shifting baselines.
            int centreInTable = physicalLsk.Top + physicalLsk.Height / 2 -
                screenPanel.Top - outputTable.Top;
            int desiredTop = centreInTable - precedingRowHeight -
                labelHeight / 2;
            // The Airbus key art is optically centered below the label's
            // geometric center; the visible text was ~7px above the keys.
            // Boeing uses the unadjusted measured key center.
            if (!DcduStyleManager.IsBoeing)
            {
                desiredTop += S(7);
            }
            return Math.Max(0, Math.Min(desiredTop,
                HardwareOverviewRowHeight(slot) - Math.Min(
                    labelHeight, HardwareOverviewRowHeight(slot))));
        }

        private void RestoreOverviewTimeAndActionColumns(int row, bool lskMode)
        {
            if (outputTable.ColumnStyles.Count < 3)
            {
                return;
            }

            int timeWidth = Math.Max(S(48),
                (int)Math.Floor(outputTable.ColumnStyles[0].Width) - S(7));
            Control time = outputTable.GetControlFromPosition(0, row);
            if (time != null)
            {
                time.Dock = DockStyle.None;
                time.Anchor = AnchorStyles.Top | AnchorStyles.Left;
                // A220 standard list keeps its original auto-sized time text.
                // On Airbus/Boeing, status and ordinary timestamps share the
                // same fixed geometry so the reply glyph cannot move a row.
                if (DcduStyleManager.IsA220 && time is AccessibleLabel)
                {
                    time.AutoSize = true;
                    time.MaximumSize = new Size(timeWidth, 0);
                }
                else
                {
                    time.AutoSize = false;
                    time.Width = timeWidth;
                    time.Height = S(18);
                    time.MaximumSize = Size.Empty;
                }
            }

            if (outputTable.GetControlFromPosition(2, row) is TimerLabel action)
            {
                // Indicators were originally created at the OLD style width.
                // An A220 84px button in a Boeing 74px column can force a
                // horizontal scroll and misalign every following message.
                int actionWidth = lskMode ? 0 :
                    (int)Math.Floor(outputTable.ColumnStyles[2].Width);
                action.AutoSize = false;
                action.Dock = DockStyle.None;
                action.Anchor = AnchorStyles.Top | AnchorStyles.Right;
                action.Width = Math.Max(1, actionWidth - S(2));
                action.Height = S(18);
                action.MinimumSize = Size.Empty;
                action.MaximumSize = lskMode
                    ? Size.Empty
                    : new Size(Math.Max(1, actionWidth - S(2)), 0);
                action.Margin = new Padding(0, S(3), S(2), 0);
            }
        }

        private void RestoreStandardOverviewActionIndicators()
        {
            foreach (CPDLCMessage message in overviewMessageOrder)
            {
                if (message == null || message.IsDisposed)
                {
                    continue;
                }
                TimerLabel action = FindMenuLabelForMessage(message);
                if (action == null || action.IsDisposed || !action.Enabled ||
                    autoDeleteRequestTimers.ContainsKey(message))
                {
                    continue;
                }

                // New unread messages keep their envelope; only read messages
                // get the normal open/delete quick actions. Explicitly avoid
                // overwriting transient spinner/status and countdown states.
                if (unreadMessages.Contains(message))
                {
                    action.Tag = null;
                    action.Text = UnreadMessageMarkerText;
                    action.CanFlash = true;
                }
                else if (IsOpenMessageActionsIndicator(action) ||
                         action.Text == UnreadMessageMarkerText)
                {
                    if (ShouldUseDeleteOnlyOverviewAction(message))
                    {
                        ConfigureDeleteOnlyMessageIndicator(action);
                    }
                    else
                    {
                        ConfigureOpenMessageIndicator(action);
                    }
                    action.CanFlash = ShouldFlashForReply(message) ||
                        CanDirectWilcoFromOverview(message) ||
                        CanDirectRogerFromOverview(message);
                }
                action.Invalidate();
            }
        }

        private void ApplyMessageFilter()
        {
            if (outputTable == null || outputTable.IsDisposed ||
                rebuildingOverviewRows)
            {
                return;
            }

            bool hardwareLskOverview =
                ShouldUseMessageOverviewLskMode();

            string overviewStyle = DcduStyleManager.IsA220 ? "A220" :
                (DcduStyleManager.IsBoeing ? "BOEING" : "AIRBUS");
            bool presentationChanged =
                lastOverviewLskMode != hardwareLskOverview ||
                !string.Equals(lastOverviewStyle, overviewStyle, StringComparison.Ordinal);
            if (presentationChanged)
            {
                standardOverviewExtentValid = false;
                // A220 is permanently standard, regardless of the setting
                // stored for the Airbus/Boeing bezel.
                overviewRowsNeedRebuild = true;
                lastOverviewLskMode = hardwareLskOverview;
                lastOverviewStyle = overviewStyle;
            }

            if (overviewRowsNeedRebuild && !hardwareLskOverview)
            {
                standardOverviewExtentValid = false;
            }
            ConfigureMessageOverviewScrollMode();
            if (presentationChanged)
            {
                // A scroll position from a narrower/shorter style would crop
                // the first messages in the newly selected standard list.
                outputTable.AutoScrollPosition = Point.Empty;
                if (!hardwareLskOverview)
                {
                    // Drop the previous style's measured extent once only.
                    // Ordinary redraws must preserve the stabilized extent.
                    outputTable.AutoScrollMinSize = Size.Empty;
                }
            }
            FitMessageOverviewColumns(hardwareLskOverview);
            NormalizeOverviewRowCells();
            if (hardwareLskOverview)
            {
                DetachOverviewActionsForHardwareMode();
            }
            if (presentationChanged && !hardwareLskOverview)
            {
                RestoreStandardOverviewActionIndicators();
            }

            HashSet<CPDLCMessage> hardwarePageMessages =
                hardwareLskOverview
                    ? GetHardwareMessageOverviewPageMessages()
                    : null;

            if (!hardwareLskOverview)
            {
                hardwareMessageOverviewPageIndex = 0;
                hardwareMessageOverviewPageCount = 1;
            }

            outputTable.SuspendLayout();

            try
            {
                int hardwareSlot = 0;
                int priorHardwareRowHeight = 0;
                int standardTextWidth = StandardOverviewMessageMaxWidth();

                for (int row = 0; row < outputTable.RowCount; row++)
                {
                    CPDLCMessage rowMessage = null;

                    for (int col = 0; col < outputTable.ColumnCount; col++)
                    {
                        if (outputTable.GetControlFromPosition(col, row) is CPDLCMessage message)
                        {
                            rowMessage = message;
                            break;
                        }
                    }

                    bool visible;

                    if (rowMessage == null)
                    {
                        // Special non-message rows (for example NEW FP DETECTED)
                        // keep their established behaviour.
                        visible = true;
                    }
                    else if (hardwareLskOverview)
                    {
                        visible =
                            hardwarePageMessages.Contains(
                                rowMessage);
                    }
                    else
                    {
                        visible =
                            MessageMatchesFilter(
                                rowMessage,
                                activeMessageFilter);
                    }

                    for (int col = 0; col < outputTable.ColumnCount; col++)
                    {
                        Control control =
                            outputTable.GetControlFromPosition(
                                col,
                                row);

                        if (control != null)
                        {
                            // Hardware action controls are detached above;
                            // never set their own Visible flag to false. In
                            // standard mode always restore each attached
                            // action's visibility from its message filter.
                            control.Visible = visible &&
                                (col != 2 || control.Enabled);
                        }
                    }

                    // Every row must release the old style's fixed time and
                    // action column sizes, even when that row is filtered out.
                    // Otherwise hidden rows can later expand the scroll width.
                    RestoreOverviewTimeAndActionColumns(row, hardwareLskOverview);

                    if (row < outputTable.RowStyles.Count)
                    {
                        if (!visible)
                        {
                            outputTable.RowStyles[row].SizeType =
                                SizeType.Absolute;
                            outputTable.RowStyles[row].Height = 0F;
                        }
                        else if (hardwareLskOverview &&
                                 rowMessage != null)
                        {
                            // Give every hardware message exactly one physical
                            // LSK slot. Airbus exposes three slots; Boeing exposes
                            // four. One-/two-line source text can therefore never
                            // push another message away from its physical key.
                            outputTable.RowStyles[row].SizeType =
                                SizeType.Absolute;

                            outputTable.RowStyles[row].Height =
                                HardwareOverviewRowHeight(hardwareSlot);

                            rowMessage.Text =
                                HardwareMessageOverviewSingleLineText(
                                    rowMessage);

                            // Every hardware slot is fixed-height and single-line.
                            // A status label's preferred size or message font
                            // must not independently move either baseline.
                            int labelHeight = Math.Min(
                                HardwareOverviewRowHeight(hardwareSlot),
                                Math.Max(S(18), TextRenderer.MeasureText(
                                    "Ag", rowMessage.Font,
                                    Size.Empty,
                                    TextFormatFlags.SingleLine |
                                    TextFormatFlags.NoPadding).Height));

                            rowMessage.MinimumSize = Size.Empty;
                            rowMessage.MaximumSize = new Size(
                                Math.Max(S(70), standardTextWidth), labelHeight);
                            rowMessage.AutoSize = false;
                            rowMessage.Size = new Size(
                                Math.Max(S(70), standardTextWidth), labelHeight);
                            rowMessage.TextAlign = ContentAlignment.MiddleLeft;
                            rowMessage.Dock = DockStyle.None;
                            rowMessage.Anchor = AnchorStyles.Top | AnchorStyles.Left;

                            int sharedInset = HardwareOverviewTextTopInset(
                                hardwareSlot, priorHardwareRowHeight,
                                labelHeight);
                            rowMessage.Margin = new Padding(
                                0, sharedInset, 0, 0);

                            Control timeControl =
                                outputTable.GetControlFromPosition(0, row);

                            if (timeControl != null)
                            {
                                timeControl.AutoSize = false;
                                timeControl.Height = labelHeight;
                                timeControl.Margin = new Padding(
                                    S(5), sharedInset, 0, 0);
                            }

                            priorHardwareRowHeight +=
                                HardwareOverviewRowHeight(hardwareSlot);
                            hardwareSlot++;
                        }
                        else if (hardwareLskOverview)
                        {
                            // Non-message helper/prompt rows have no physical
                            // overview LSK assignment and must not consume one
                            // of the three hardware message slots.
                            outputTable.RowStyles[row].SizeType =
                                SizeType.Absolute;
                            outputTable.RowStyles[row].Height = 0F;

                            for (int col = 0;
                                 col < outputTable.ColumnCount;
                                 col++)
                            {
                                Control helperControl =
                                    outputTable.GetControlFromPosition(
                                        col,
                                        row);

                                if (helperControl != null)
                                {
                                    helperControl.Visible = false;
                                }
                            }
                        }
                        else
                        {
                            // Standard overview (and A220) keeps the original
                            // flexible list with envelope / quick-menu actions.
                            outputTable.RowStyles[row].SizeType =
                                SizeType.AutoSize;
                            outputTable.RowStyles[row].Height = 0F;

                            // Auxiliary prompts share the same bounded message
                            // column and must not force horizontal auto-scroll.
                            if (rowMessage == null &&
                                outputTable.GetControlFromPosition(1, row)
                                    is Panel promptPanel)
                            {
                                promptPanel.Width = standardTextWidth;
                                promptPanel.MaximumSize = new Size(
                                    standardTextWidth, 0);
                            }

                            if (rowMessage != null)
                            {
                                rowMessage.Text = CreateMessageListText(
                                    rowMessage.message,
                                    rowMessage.type,
                                    rowMessage.recipient,
                                    rowMessage.outbound);

                                // Restore *all* geometry after LSK mode, not
                                // just the message text. AutoSize is bounded by
                                // our fixed-width second column, preventing
                                // horizontal scroll and displaced actions.
                                // On the A220 keep the original variable-height
                                // standard message list. Constrain the preferred
                                // width, but let WinForms measure wrapped text.
                                rowMessage.AutoSize = DcduStyleManager.IsA220;
                                rowMessage.Width = standardTextWidth;
                                rowMessage.TextAlign = ContentAlignment.TopLeft;
                                rowMessage.Dock = DockStyle.None;
                                rowMessage.Anchor = AnchorStyles.Top |
                                    AnchorStyles.Left;

                                // No style is allowed an unbounded AutoSize
                                // message in a percent-width table column.
                                // This is the main fix for the scrambled
                                // timestamps / text / action icons in LSK OFF.
                                rowMessage.MinimumSize = Size.Empty;
                                rowMessage.MaximumSize = new Size(
                                    standardTextWidth, 0);
                                // Obtain the wrapped height at the actual
                                // available width, not at the stale LSK width.
                                // AutoSize=false stops a wide single-line
                                // message from expanding the table horizontally.
                                Size wrapped = TextRenderer.MeasureText(
                                    rowMessage.Text ?? string.Empty,
                                    rowMessage.Font,
                                    new Size(Math.Max(1, standardTextWidth), 100000),
                                    TextFormatFlags.WordBreak |
                                    TextFormatFlags.NoPadding |
                                    TextFormatFlags.NoPrefix);
                                if (!DcduStyleManager.IsA220)
                                {
                                    rowMessage.Height = Math.Max(S(19), wrapped.Height + S(3));
                                }
                                rowMessage.Margin = SPad(
                                    new Padding(0, 3, 0, 0));

                                Control timeControl =
                                    outputTable.GetControlFromPosition(0, row);

                                if (timeControl != null)
                                {
                                    timeControl.Dock = DockStyle.None;
                                    timeControl.Anchor = AnchorStyles.Top |
                                        AnchorStyles.Left;
                                    timeControl.Margin = SPad(
                                        new Padding(5, 3, 0, 0));
                                }
                            }
                        }
                    }
                }

                if (hardwareLskOverview)
                {
                    try
                    {
                        outputTable.AutoScrollPosition =
                            Point.Empty;
                    }
                    catch
                    {
                        // Cosmetic only.
                    }
                }
            }
            finally
            {
                outputTable.ResumeLayout(true);
            }

            // An old horizontal AutoScroll origin may survive a style/mode
            // switch or ScrollControlIntoView. Never let it shift the time
            // column, even on a subsequent redraw or content update.
            if (!hardwareLskOverview && outputTable.AutoScroll)
            {
                int currentY = Math.Max(0, -outputTable.AutoScrollPosition.Y);
                outputTable.AutoScrollPosition = new Point(0, currentY);
                // A visible false-to-true change can trigger another layout
                // pass; keep the scrollable width inside the viewport too.
                outputTable.HorizontalScroll.Value = 0;
            }

            UpdateMessageFilterLabel();
            HideNativeOutputScrollbars();
            UpdateHardwareMessageOverviewPageBar();
            UpdateHardwareMessageOverviewBlinkState();
            KeepMessageOverviewHeaderAboveList();
            RefreshOutputScrollSurfaceOnly();
            if (!hardwareLskOverview)
            {
                // Do this after the table is resumed and the standard
                // actions are reattached (also when returning to A220).
                QueueStandardOverviewScrollSynchronization(
                    presentationChanged);
            }
        }

        private void ConfigureAtisAutoRefresh()
        {
            atisAutoRefreshTimer.Interval = 15000;
            atisAutoRefreshTimer.Tick += (_, __) => AtisAutoRefreshTimer_Tick();
            atisAutoRefreshTimer.Start();
        }

        private void AtisAutoRefreshTimer_Tick()
        {
            string target;

            lock (atisAutoRefreshLock)
            {
                if (!atisAutoRefreshEnabled || !Connected || string.IsNullOrWhiteSpace(atisAutoRefreshTarget))
                {
                    return;
                }

                if (DateTime.UtcNow < nextAtisAutoRefreshUtc)
                {
                    return;
                }

                target = atisAutoRefreshTarget;
                nextAtisAutoRefreshUtc = DateTime.UtcNow + atisAutoRefreshInterval;
            }

            RememberAtisRequestTarget(target);
            ArtificialDelay("VATATIS " + target, "INFOREQ", "REQUEST", 2, 8);
        }

        public void SetAtisAutoRefresh(string target, bool enabled)
        {
            string cleanTarget = (target ?? string.Empty).Trim().ToUpperInvariant();

            lock (atisAutoRefreshLock)
            {
                if (!enabled || string.IsNullOrWhiteSpace(cleanTarget))
                {
                    atisAutoRefreshEnabled = false;
                    atisAutoRefreshTarget = string.Empty;
                    atisAutoRefreshDisplayTarget = string.Empty;
                    atisAutoRefreshLastLetter = string.Empty;
                    nextAtisAutoRefreshUtc = DateTime.MinValue;
                }
                else
                {
                    atisAutoRefreshEnabled = true;
                    atisAutoRefreshTarget = cleanTarget;
                    atisAutoRefreshDisplayTarget = FormatAtisTargetForList(cleanTarget);
                    atisAutoRefreshLastLetter = string.Empty;
                    nextAtisAutoRefreshUtc = DateTime.UtcNow + atisAutoRefreshInitialDelay;
                }
            }

            SafeUi(() =>
            {
                UpdateAtisAutoStatusLabel();
                UpdateSmartStatusLabelColors();
            });

            if (enabled && !string.IsNullOrWhiteSpace(cleanTarget))
            {
                WriteMessage("ATIS AUTO REFRESH ON FOR " + FormatAtisTargetForList(cleanTarget), "SYSTEM", "SYSTEM");
            }
        }

        public bool IsAtisAutoRefreshEnabled()
        {
            lock (atisAutoRefreshLock)
            {
                return atisAutoRefreshEnabled;
            }
        }

        private bool IsAutoAtisTarget(string target)
        {
            string formatted = FormatAtisTargetForList(target);

            lock (atisAutoRefreshLock)
            {
                return atisAutoRefreshEnabled &&
                    !string.IsNullOrWhiteSpace(atisAutoRefreshDisplayTarget) &&
                    string.Equals(formatted, atisAutoRefreshDisplayTarget, StringComparison.OrdinalIgnoreCase);
            }
        }

        private string BuildAtisStatusForOverview(string target, string atisLetter)
        {
            string cleanLetter = (atisLetter ?? string.Empty).Trim().ToUpperInvariant();

            if (string.IsNullOrWhiteSpace(cleanLetter))
            {
                return "? RECEIVED";
            }

            lock (atisAutoRefreshLock)
            {
                if (atisAutoRefreshEnabled &&
                    IsAutoAtisTarget(target) &&
                    !string.IsNullOrWhiteSpace(atisAutoRefreshLastLetter) &&
                    !string.Equals(atisAutoRefreshLastLetter, cleanLetter, StringComparison.OrdinalIgnoreCase))
                {
                    return "UPDATED " + atisAutoRefreshLastLetter + "->" + cleanLetter;
                }
            }

            return "INFO " + cleanLetter + " RECEIVED";
        }

        private string GetAtisLetterForAutoRefresh(string target, string contents)
        {
            string letter = GetAtisOverviewLetter(contents, target);

            if (string.IsNullOrWhiteSpace(letter))
            {
                letter = ExtractAtisInformationLetter(contents);
            }

            if (string.IsNullOrWhiteSpace(letter))
            {
                letter = ExtractAtisLetterFromVatsimData(target);
            }

            return (letter ?? string.Empty).Trim().ToUpperInvariant();
        }

        private bool ShouldEmitAutoAtisUpdateFromContents(string target, string contents)
        {
            string formattedTarget = FormatAtisTargetForList(target);
            string letter = GetAtisLetterForAutoRefresh(formattedTarget, contents);

            if (string.IsNullOrWhiteSpace(letter))
            {
                return false;
            }

            lock (atisAutoRefreshLock)
            {
                if (!atisAutoRefreshEnabled || !IsAutoAtisTarget(formattedTarget))
                {
                    return false;
                }

                if (string.IsNullOrWhiteSpace(atisAutoRefreshLastLetter))
                {
                    atisAutoRefreshLastLetter = letter;
                    return false;
                }

                return !string.Equals(atisAutoRefreshLastLetter, letter, StringComparison.OrdinalIgnoreCase);
            }
        }

        private void MaybeEmitAutoAtisUpdateFromHoverCache(string target, string contents)
        {
            string formattedTarget = FormatAtisTargetForList(target);

            bool autoTarget;
            lock (atisAutoRefreshLock)
            {
                autoTarget = atisAutoRefreshEnabled && IsAutoAtisTarget(formattedTarget);
            }

            if (!autoTarget)
            {
                return;
            }

            if (ShouldEmitAutoAtisUpdateFromContents(formattedTarget, contents))
            {
                WriteMessage(formattedTarget + "\n" + NormalizeAtisHoverContent(contents), "ATIS", "VATATIS");
            }

            lock (atisAutoRefreshLock)
            {
                if (atisAutoRefreshEnabled && IsAutoAtisTarget(formattedTarget))
                {
                    nextAtisAutoRefreshUtc = DateTime.UtcNow + atisAutoRefreshInterval;
                }
            }

            SafeUi(() =>
            {
                UpdateAtisAutoStatusLabel();
                UpdateAtisAutoPopupText();
            });
        }

        private void TrackAutoAtisLetterFromMessage(CPDLCMessage message)
        {
            if (message == null || string.IsNullOrWhiteSpace(message.Text))
            {
                return;
            }

            Match match = Regex.Match((message.Text ?? string.Empty).ToUpperInvariant(), @"\b([A-Z0-9]{4})\s+ATIS\s+(?:(?:UPDATED\s+[A-Z?]->)|)([A-Z?])\b");
            if (!match.Success)
            {
                return;
            }

            string target = match.Groups[1].Value;
            string letter = match.Groups[2].Value;

            lock (atisAutoRefreshLock)
            {
                if (atisAutoRefreshEnabled &&
                    string.Equals(target, atisAutoRefreshDisplayTarget, StringComparison.OrdinalIgnoreCase))
                {
                    atisAutoRefreshLastLetter = letter;
                }
            }
        }

        private bool ShouldSuppressUnchangedAutoAtisResponse(string contents, string type, string recipient, bool outbound)
        {
            if (outbound)
            {
                return false;
            }

            string normalizedType = (type ?? string.Empty).Trim().ToUpperInvariant();

            if (!ShouldUseAtisListText(contents, normalizedType, recipient))
            {
                return false;
            }

            string target = GetAtisListTarget(contents, recipient, false);

            if (!IsAutoAtisTarget(target))
            {
                return false;
            }

            string letter = GetAtisOverviewLetter(contents, target);

            if (string.IsNullOrWhiteSpace(letter))
            {
                return false;
            }

            lock (atisAutoRefreshLock)
            {
                if (string.IsNullOrWhiteSpace(atisAutoRefreshLastLetter) ||
                    !string.Equals(atisAutoRefreshLastLetter, letter, StringComparison.OrdinalIgnoreCase))
                {
                    return false;
                }
            }

            RemovePendingAtisRequestTarget(target);
            CacheWeatherMessage("ATIS", target, contents, BuildAtisStatusForOverview(target, letter) + BuildWeatherOverviewSuffix(contents, 44, false, target));
            return true;
        }

        private void MaybeShowPdcAvailabilityHint(string station, bool hasDatalink)
        {
            // Silent state marker only.
            // The old "PDC AVAILABLE FOR XXXX" SYSTEM MESSAGE was noisy during login.
            if (!Connected || !hasDatalink || string.IsNullOrWhiteSpace(station))
            {
                return;
            }

            lastPdcAvailabilityHintStation = station.Trim().ToUpperInvariant();
        }

        private void ConfigureCpdlcHandoverBlinkTimer()
        {
            cpdlcHandoverBlinkTimer.Interval = 450;
            cpdlcHandoverBlinkTimer.Tick += (_, __) =>
            {
                if (!IsCpdlcHandoverFrequencyPending())
                {
                    cpdlcHandoverBlinkTimer.Stop();

                    bool confirmedConnectionActive =
                        cpdlcSessionEstablished &&
                        !string.IsNullOrWhiteSpace(_currentATCUnit) &&
                        string.IsNullOrWhiteSpace(pendingLogon);

                    if (confirmedConnectionActive ||
                        IsCpdlcUnitVerifiedOnActiveFrequency(GetActiveCpdlcVerificationCode()))
                    {
                        cpdlcHandoverTargetCode = string.Empty;
                        cpdlcHandoverStartedUtc = DateTime.MinValue;
                    }
                }

                UpdateCpdlcDiscoveryLabel();
            };
        }

        private void StartCpdlcHandoverFrequencyWatch(string targetCode)
        {
            cpdlcHandoverTargetCode = (targetCode ?? string.Empty).Trim().ToUpperInvariant();
            cpdlcHandoverStartedUtc = DateTime.UtcNow;

            if (!string.IsNullOrWhiteSpace(cpdlcHandoverTargetCode))
            {
                cpdlcHandoverBlinkTimer.Start();
            }

            UpdateCpdlcDiscoveryLabel();
        }

        private void StopCpdlcHandoverFrequencyWatch()
        {
            cpdlcHandoverTargetCode = string.Empty;
            cpdlcHandoverStartedUtc = DateTime.MinValue;
            cpdlcHandoverBlinkTimer.Stop();
            UpdateCpdlcDiscoveryLabel();
        }

        private void CompleteCpdlcHandoverAfterConfirmedConnection(
            string connectedUnit,
            string confirmationSource)
        {
            string confirmedUnit = (connectedUnit ?? string.Empty)
                .Trim()
                .ToUpperInvariant();

            if (string.IsNullOrWhiteSpace(confirmedUnit) ||
                string.IsNullOrWhiteSpace(cpdlcHandoverTargetCode))
            {
                return;
            }

            Logger.Debug(
                "CPDLC handover completed: target=" +
                cpdlcHandoverTargetCode +
                ", connected=" +
                confirmedUnit +
                ", source=" +
                (confirmationSource ?? "unknown") +
                ". Frequency-watch blink stopped after confirmed CPDLC connection.");

            // A positive LOGON/CONNECTED/CURRENT ATS UNIT confirmation is the
            // authoritative end of the CPDLC handover. VATSIM transceiver data can
            // lag behind the actual radio change and must not keep the satellite
            // icon blinking after the datalink session is already established.
            StopCpdlcHandoverFrequencyWatch();
        }

        private static string NormalizeCpdlcCooldownKey(string value)
        {
            string clean = (value ?? string.Empty).Trim().ToUpperInvariant();
            if (string.IsNullOrWhiteSpace(clean))
            {
                return string.Empty;
            }

            clean = Regex.Replace(clean, @"[^A-Z0-9_]", string.Empty);
            return clean;
        }

        private static IEnumerable<string> CpdlcCooldownAliases(string codeOrController)
        {
            string clean = NormalizeCpdlcCooldownKey(codeOrController);
            if (string.IsNullOrWhiteSpace(clean))
            {
                yield break;
            }

            yield return clean;

            string prefix = clean.Split('_').FirstOrDefault() ?? string.Empty;
            prefix = Regex.Replace(prefix, @"[^A-Z0-9]", string.Empty);
            if (!string.IsNullOrWhiteSpace(prefix) && !string.Equals(prefix, clean, StringComparison.OrdinalIgnoreCase))
            {
                yield return prefix;
            }
        }

        private void StartCpdlcVerifiedSuggestionCooldown(string codeOrController, string reason)
        {
            List<string> aliases = CpdlcCooldownAliases(codeOrController)
                .Where(alias => !string.IsNullOrWhiteSpace(alias))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();

            if (aliases.Count == 0)
            {
                return;
            }

            DateTime until = DateTime.UtcNow + cpdlcVerifiedSuggestionCooldown;

            foreach (string alias in aliases)
            {
                cpdlcVerifiedSuggestionCooldownUntilUtc[alias] = until;
            }

            lastCpdlcStationDetectedNotificationKey = string.Empty;
            lastCpdlcStationDetectedNotificationUtc = DateTime.MinValue;

            Logger.Debug("CPDLC verified suggestion cooldown: " + string.Join(",", aliases) + " until " + until.ToString("HH:mm:ss") + "Z" +
                (string.IsNullOrWhiteSpace(reason) ? string.Empty : " (" + reason + ")"));
        }

        private void StartCpdlcVerifiedSuggestionCooldownForCurrentConnection(string reason, string sender = null)
        {
            if (!string.IsNullOrWhiteSpace(_currentATCUnit))
            {
                StartCpdlcVerifiedSuggestionCooldown(_currentATCUnit, reason);
            }

            if (!string.IsNullOrWhiteSpace(sender))
            {
                StartCpdlcVerifiedSuggestionCooldown(sender, reason);
                string senderCode = ExtractCpdlcLogonCode(sender, string.Empty);
                if (!string.IsNullOrWhiteSpace(senderCode))
                {
                    StartCpdlcVerifiedSuggestionCooldown(senderCode, reason);
                }
            }
        }

        private void PruneCpdlcVerifiedSuggestionCooldowns()
        {
            if (cpdlcVerifiedSuggestionCooldownUntilUtc.Count == 0)
            {
                return;
            }

            DateTime now = DateTime.UtcNow;
            foreach (string key in cpdlcVerifiedSuggestionCooldownUntilUtc
                .Where(pair => pair.Value <= now)
                .Select(pair => pair.Key)
                .ToList())
            {
                cpdlcVerifiedSuggestionCooldownUntilUtc.Remove(key);
            }
        }

        private bool IsCpdlcVerifiedSuggestionCooldownActive(string code, string controller, out string remainingText)
        {
            remainingText = string.Empty;
            PruneCpdlcVerifiedSuggestionCooldowns();

            DateTime newestUntil = DateTime.MinValue;

            foreach (string alias in CpdlcCooldownAliases(code).Concat(CpdlcCooldownAliases(controller)).Distinct(StringComparer.OrdinalIgnoreCase))
            {
                if (cpdlcVerifiedSuggestionCooldownUntilUtc.TryGetValue(alias, out DateTime until) && until > DateTime.UtcNow)
                {
                    if (until > newestUntil)
                    {
                        newestUntil = until;
                    }
                }
            }

            if (newestUntil == DateTime.MinValue)
            {
                return false;
            }

            TimeSpan remaining = newestUntil - DateTime.UtcNow;
            remainingText = Math.Max(1, (int)Math.Ceiling(remaining.TotalMinutes)).ToString(System.Globalization.CultureInfo.InvariantCulture) + " min";
            return true;
        }

        private static bool IsCpdlcGoodbyeOrUnicomInstruction(string message)
        {
            string clean = NormalizeCpdlcOverviewText(message);

            if (string.IsNullOrWhiteSpace(clean))
            {
                return false;
            }

            bool goodbye = clean.Contains("GOODBYE") || clean.Contains("GOOD BYE");
            bool advisory = clean.Contains("MONITOR ADVISORY") ||
                            clean.Contains("MONITOR UNICOM") ||
                            clean.Contains("UNICOM") ||
                            clean.Contains("122.8") ||
                            clean.Contains("122800") ||
                            clean.Contains("122 800");

            return goodbye && advisory;
        }

        private string GetActiveCpdlcVerificationCode()
        {
            if (!string.IsNullOrWhiteSpace(cpdlcHandoverTargetCode))
            {
                return cpdlcHandoverTargetCode.Trim().ToUpperInvariant();
            }

            if (!string.IsNullOrWhiteSpace(pendingLogon))
            {
                return pendingLogon.Trim().ToUpperInvariant();
            }

            if (!string.IsNullOrWhiteSpace(_currentATCUnit))
            {
                return _currentATCUnit.Trim().ToUpperInvariant();
            }

            return string.Empty;
        }

        private bool IsCpdlcHandoverFrequencyPending()
        {
            string targetCode = GetActiveCpdlcVerificationCode();

            if (string.IsNullOrWhiteSpace(targetCode))
            {
                return false;
            }

            if (cpdlcHandoverStartedUtc == DateTime.MinValue ||
                DateTime.UtcNow - cpdlcHandoverStartedUtc > cpdlcHandoverFrequencyGrace)
            {
                return false;
            }

            // The radio-frequency watch is only a pre-connection handover aid.
            // Once CPDLC itself confirms a current unit, the satellite indicator
            // must be solid green even if the VATSIM transceiver feed is delayed.
            if (cpdlcSessionEstablished &&
                !string.IsNullOrWhiteSpace(_currentATCUnit) &&
                string.IsNullOrWhiteSpace(pendingLogon))
            {
                return false;
            }

            return !IsCpdlcUnitVerifiedOnActiveFrequency(targetCode);
        }

        private bool IsCpdlcUnitVerifiedOnActiveFrequency(string logonCode)
        {
            string targetCode = (logonCode ?? string.Empty).Trim().ToUpperInvariant();

            if (!Connected ||
                !IsAirborneNowForPhase() ||
                string.IsNullOrWhiteSpace(targetCode) ||
                IsVatsimTransceiverDataStale())
            {
                return false;
            }

            if (IsCpdlcVerifiedSuggestionCooldownActive(targetCode, targetCode, out _))
            {
                return false;
            }

            List<long> currentPilotFreqs = GetPilotTunedFrequencies();
            if (currentPilotFreqs.Count == 0 || vatsimData?.controllers == null)
            {
                return false;
            }

            foreach (CpdlcDiscoveryResult candidate in cpdlcDiscoveryCandidates)
            {
                if (candidate == null ||
                    !candidate.Possible ||
                    !string.Equals((candidate.Code ?? string.Empty).Trim(), targetCode, StringComparison.OrdinalIgnoreCase) ||
                    string.IsNullOrWhiteSpace(candidate.Controller) ||
                    !IsHoppieLogonOnline(candidate.Code))
                {
                    continue;
                }

                string candidateController = candidate.Controller.Trim().ToUpperInvariant();
                Controller controller = vatsimData.controllers.FirstOrDefault(ctrl =>
                    string.Equals((ctrl.callsign ?? string.Empty).Trim().ToUpperInvariant(), candidateController, StringComparison.OrdinalIgnoreCase));

                if (TryGetTunedFrequencyMatch(controller, currentPilotFreqs, out _))
                {
                    return true;
                }
            }

            foreach (Controller controller in vatsimData.controllers.Where(IsCpdlcDiscoveryController))
            {
                string info = GetControllerInfoText(controller);
                string code = ExtractCpdlcLogonCode(info, string.Empty);

                if (!string.Equals(code, targetCode, StringComparison.OrdinalIgnoreCase) ||
                    !IsHoppieLogonOnline(code))
                {
                    continue;
                }

                if (TryGetTunedFrequencyMatch(controller, currentPilotFreqs, out _))
                {
                    return true;
                }
            }

            return false;
        }

        private bool IsVatsimRequestBackoffActive(out TimeSpan remaining)
        {
            remaining = vatsimRequestBackoffUntilUtc - DateTime.UtcNow;
            if (remaining <= TimeSpan.Zero)
            {
                remaining = TimeSpan.Zero;
                return false;
            }

            return true;
        }

        private static bool IsVatsimBackoffWorthyFailure(Exception ex)
        {
            if (ex is TaskCanceledException || ex is TimeoutException)
            {
                return true;
            }

            if (ex is HttpRequestException httpError)
            {
                if (!httpError.StatusCode.HasValue)
                {
                    return true;
                }

                int statusCode = (int)httpError.StatusCode.Value;
                return statusCode == 429 || statusCode >= 500;
            }

            // A malformed or incomplete service response should not be retried in
            // a tight loop either.
            return ex is JsonException || ex is FormatException;
        }

        private void ResetVatsimRequestBackoff()
        {
            consecutiveVatsimRequestFailures = 0;
            vatsimRequestBackoffUntilUtc = DateTime.MinValue;
        }

        private void RegisterVatsimRequestFailure(Exception ex, string operation)
        {
            if (!IsVatsimBackoffWorthyFailure(ex))
            {
                return;
            }

            consecutiveVatsimRequestFailures =
                Math.Min(consecutiveVatsimRequestFailures + 1, 16);

            int exponent = Math.Min(consecutiveVatsimRequestFailures - 1, 5);
            double calculatedSeconds =
                vatsimFailureBackoffBase.TotalSeconds * Math.Pow(2.0, exponent);
            double cappedSeconds = Math.Min(
                calculatedSeconds,
                vatsimFailureBackoffMaximum.TotalSeconds);
            int jitterSeconds = Random.Shared.Next(0, 11);

            DateTime proposedUntilUtc =
                DateTime.UtcNow +
                TimeSpan.FromSeconds(cappedSeconds + jitterSeconds);

            if (proposedUntilUtc > vatsimRequestBackoffUntilUtc)
            {
                vatsimRequestBackoffUntilUtc = proposedUntilUtc;
            }

            Logger.Debug(
                DiagnosticLogMessage(
                    "VATSIM request backoff: operation=" +
                    (operation ?? "unknown") +
                    ", failures=" +
                    consecutiveVatsimRequestFailures.ToString(
                        System.Globalization.CultureInfo.InvariantCulture) +
                    ", retry-in=" +
                    Math.Max(
                        0,
                        (int)Math.Ceiling(
                            (vatsimRequestBackoffUntilUtc - DateTime.UtcNow).TotalSeconds))
                        .ToString(System.Globalization.CultureInfo.InvariantCulture) +
                    "s, error=" +
                    ex.Message));
        }

        private void ConfigureVatsimOnlineRefresh()
        {
            // Dedicated background refresh for CPDLC/PDC/ATIS helper data.
            // The timer ticks often, but RefreshVatsimOnlineStatusAsync(false) throttles
            // actual VATSIM/Hoppie downloads to vatsimOnlineRefreshInterval.
            vatsimOnlineTimer.Interval = 10000;
            vatsimOnlineTimer.Tick += async (_, __) =>
            {
                if (!Connected)
                {
                    return;
                }

                // Frequency changes must not wait for the complete 60-second
                // VATSIM/Hoppie refresh. The transceiver method has its own 20-second
                // throttle and failure backoff, so this remains request-safe.
                await RefreshVatsimTransceiversAsync(false);
                await RefreshVatsimOnlineStatusAsync(false);
            };
            vatsimOnlineTimer.Start();
        }

        private async Task RefreshVatsimAtcOnlineAsync()
        {
            try
            {
                string json = await webclient.GetStringAsync(VatsimAtcOnlineUrl);
                JArray array = JArray.Parse(json ?? "[]");

                HashSet<string> callsigns = new(StringComparer.OrdinalIgnoreCase);
                foreach (JToken item in array)
                {
                    string callsignValue = item?["callsign"]?.ToString()?.Trim().ToUpperInvariant();
                    if (!string.IsNullOrWhiteSpace(callsignValue))
                    {
                        callsigns.Add(callsignValue);
                    }
                }

                vatsimAtcOnlineCallsigns.Clear();
                foreach (string callsignValue in callsigns)
                {
                    vatsimAtcOnlineCallsigns.Add(callsignValue);
                }

                vatsimAtcOnlineLoadedUtc = DateTime.UtcNow;
                lastVatsimAtcOnlineDebugText = "VATSIM ATC online v2: " + vatsimAtcOnlineCallsigns.Count + " stations";
                Logger.Debug(lastVatsimAtcOnlineDebugText);
            }
            catch (Exception ex)
            {
                lastVatsimAtcOnlineDebugText = "VATSIM ATC online v2 failed: " + ex.Message;
                Logger.Debug(lastVatsimAtcOnlineDebugText);
            }
        }

        private async Task PrimeCpdlcDiscoveryAfterConnectionAsync()
        {
            if (!Connected)
            {
                return;
            }

            // vatsim-data.json was already downloaded by the CONN handler. Only
            // load the additional helper sources here; do not download the main
            // VATSIM feed a second time.
            try
            {
                await RefreshHoppieOnlineStationsAsync();
            }
            catch (Exception ex)
            {
                hoppieOnlineStationsLoaded = false;
                Logger.Debug("Initial Hoppie station refresh failed: " + ex.Message);
            }

            await RefreshVatsimAtcOnlineAsync();
            await RefreshVatsimTransceiversAsync(true);

            lastVatsimOnlineRefreshUtc = DateTime.UtcNow;
            SafeUi(UpdateOnlineStatusLabel);
        }

        private async Task RefreshVatsimOnlineStatusAsync(bool force)
        {
            RecordUiDiagnosticActivity(
                force ? "VATSIM status refresh [forced]" : "VATSIM status refresh");

            if (DebugUiPreviewMode)
            {
                // DEBUG UI preview must not periodically rebuild/reset the current Airbus AOC page.
                // Keep the mocked status alive, but leave the currently visible screen untouched.
                _connected = true;
                if (statusValueLabel != null)
                {
                    statusValueLabel.Text = "UI PREVIEW";
                    statusValueLabel.ForeColor = DcduTheme.Green;
                }
                UpdateOnlineStatusLabel();
                return;
            }

            // No helper/status request may run before the VATSIM pilot and flight
            // plan checks have completed and EasyCPDLC is actually connected.
            if (!Connected)
            {
                return;
            }

            if (vatsimOnlineRefreshInProgress)
            {
                UpdateOnlineStatusLabel();
                return;
            }

            if (IsVatsimRequestBackoffActive(out _))
            {
                UpdateOnlineStatusLabel();
                return;
            }

            TimeSpan elapsedSinceRefresh = DateTime.UtcNow - lastVatsimOnlineRefreshUtc;
            TimeSpan minimumInterval = force
                ? vatsimForcedRefreshMinimumInterval
                : vatsimOnlineRefreshInterval;

            if (elapsedSinceRefresh < minimumInterval)
            {
                UpdateOnlineStatusLabel();
                return;
            }

            vatsimOnlineRefreshInProgress = true;

            try
            {
                await RefreshHoppieOnlineStationsAsync();
                await RefreshVatsimAtcOnlineAsync();

                string data = await webclient.GetStringAsync("https://data.vatsim.net/v3/vatsim-data.json");
                VATSIMRootobject refreshed = JsonConvert.DeserializeObject<VATSIMRootobject>(data);

                if (refreshed != null)
                {
                    vatsimData = refreshed;

                    Pilot refreshedPilot = vatsimData.pilots?
                        .FirstOrDefault(pilot => pilot.cid == cid ||
                            (!string.IsNullOrWhiteSpace(callsign) &&
                             string.Equals(pilot.callsign, callsign, StringComparison.OrdinalIgnoreCase)));

                    if (refreshedPilot != null)
                    {
                        ApplyLiveVatsimPilotUpdate(refreshedPilot);
                    }
                }

                await EnsureFirBoundariesLoadedAsync(false);
                await RefreshVatsimTransceiversAsync(false);

                lastVatsimOnlineRefreshUtc = DateTime.UtcNow;
                ResetVatsimRequestBackoff();
                UpdateOnlineStatusLabel();
            }
            catch (Exception ex)
            {
                RegisterVatsimRequestFailure(ex, "online status refresh");
                Logger.Debug("Online status refresh failed: " + ex.Message);
                if (onlineStatusLabel != null)
                {
                    datalinkStatusText = "PDC ?";
                    atisStatusText = "ATIS ?";
                    UpdateClearanceStatusLabel();
                }
            }
            finally
            {
                vatsimOnlineRefreshInProgress = false;
            }
        }

        private async Task RefreshCurrentVatsimPilotDataForPhaseAsync(bool force = false)
        {
            if (!Connected)
            {
                return;
            }

            if (IsVatsimRequestBackoffActive(out _))
            {
                return;
            }

            if (!force && DateTime.UtcNow - lastVatsimPilotPhaseRefreshUtc < vatsimPilotPhaseRefreshInterval)
            {
                return;
            }

            lastVatsimPilotPhaseRefreshUtc = DateTime.UtcNow;

            try
            {
                string data = await webclient.GetStringAsync("https://data.vatsim.net/v3/vatsim-data.json");
                VATSIMRootobject refreshed = JsonConvert.DeserializeObject<VATSIMRootobject>(data);

                if (refreshed == null)
                {
                    return;
                }

                vatsimData = refreshed;

                Pilot refreshedPilot = vatsimData.pilots?
                    .FirstOrDefault(pilot => pilot.cid == cid ||
                        (!string.IsNullOrWhiteSpace(callsign) &&
                         string.Equals(pilot.callsign, callsign, StringComparison.OrdinalIgnoreCase)));

                if (refreshedPilot != null)
                {
                    ApplyLiveVatsimPilotUpdate(refreshedPilot);
                }

                await RefreshVatsimTransceiversAsync(false);

                ResetVatsimRequestBackoff();

                SafeUi(() =>
                {
                    UpdateCallsignDisplay();
                    UpdateOnlineStatusLabel();
                    UpdateFlightPhaseBadge();
                });
            }
            catch (Exception ex)
            {
                RegisterVatsimRequestFailure(ex, "pilot/phase refresh");
                Logger.Debug("VATSIM pilot/phase refresh failed: " + ex.Message);
            }
        }

        private async Task CheckVatsimCallsignMismatchNowAsync()
        {
            if (!Connected || callsignMismatchManualCheckInProgress)
            {
                return;
            }

            callsignMismatchManualCheckInProgress = true;
            SafeUi(UpdateCallsignDisplay);

            try
            {
                await RefreshCurrentVatsimPilotDataForPhaseAsync(true);
            }
            finally
            {
                callsignMismatchManualCheckInProgress = false;
                SafeUi(UpdateCallsignDisplay);
            }
        }

        private async Task RefreshHoppieOnlineStationsAsync()
        {
            var connectionValues = new Dictionary<string, string>
            {
                {"logon", logonCode ?? String.Empty},
                {"from", string.IsNullOrWhiteSpace(callsign) ? "EASYCPDLC" : callsign},
                {"to", "SERVER"},
                {"type", "ping"},
                {"packet", "ALL-CALLSIGNS"}
            };

            var content = new FormUrlEncodedContent(connectionValues);
            var response = await webclient.PostAsync(HoppieConnectUrl, content);
            response.EnsureSuccessStatusCode();
            string responseString = await response.Content.ReadAsStringAsync();

            if (IsHoppieNetworkLoadResponse(responseString))
            {
                HandleHoppieNetworkLoadResponse(responseString);
                return;
            }

            string upperResponse = (responseString ?? string.Empty).Trim().ToUpperInvariant();
            if (string.IsNullOrWhiteSpace(upperResponse) || upperResponse.Contains("ERROR"))
            {
                throw new HttpRequestException(
                    "Hoppie ALL-CALLSIGNS did not return a verifiable station list.");
            }

            HashSet<string> refreshedStations = new(StringComparer.OrdinalIgnoreCase);

            foreach (Match match in Regex.Matches(upperResponse, @"\b[A-Z0-9]{3,10}(?:_[A-Z0-9]{1,10})?\b"))
            {
                string token = match.Value.Trim();

                if (IsUsefulHoppieStationToken(token))
                {
                    refreshedStations.Add(token);
                }
            }

            // An empty/invalid response must never be treated as proof that every
            // station is offline. Keep the previous cache and report UNKNOWN.
            if (refreshedStations.Count == 0)
            {
                throw new FormatException(
                    "Hoppie ALL-CALLSIGNS returned no usable station entries.");
            }

            hoppieOnlineStations.Clear();
            foreach (string station in refreshedStations)
            {
                hoppieOnlineStations.Add(station);
            }

            hoppieOnlineStationsLoaded = true;
            hoppieOnlineStationsLoadedUtc = DateTime.UtcNow;
        }

        private static bool IsUsefulHoppieStationToken(string token)
        {
            if (string.IsNullOrWhiteSpace(token))
            {
                return false;
            }

            string upper = token.Trim().ToUpperInvariant();

            string[] reserved =
            {
                "OK", "ERROR", "SERVER", "SYSTEM", "PING", "POLL",
                "ALL", "CALLSIGNS", "ALL-CALLSIGNS", "ACARS",
                "TYPE", "PACKET", "LOGON", "FROM", "TO"
            };

            return !reserved.Contains(upper);
        }

        private static bool IsUnavailableAtisText(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            string upper = text.ToUpperInvariant();
            return upper.Contains("THIS ATIS IS NOT AVAILABLE") ||
                   upper.Contains("ATIS NOT AVAILABLE") ||
                   upper.Contains("NO ATIS TEXT");
        }

        private static TimeSpan GetAtisHoverCacheRetention(AtisHoverCacheItem item)
        {
            if (item == null)
            {
                return TimeSpan.Zero;
            }

            return IsUnavailableAtisText(item.Content)
                ? atisHoverRequestCooldown
                : atisHoverCacheLifetime;
        }

        private bool HasAtisDataForTarget(string target)
        {
            if (string.IsNullOrWhiteSpace(target))
            {
                return false;
            }

            if (HasVatsimAtisForTarget(target))
            {
                return true;
            }

            AtisHoverCacheItem cached = GetAtisHoverCache(target);
            bool hasCachedAtis = cached != null && !IsUnavailableAtisText(cached.Content);

            return hasCachedAtis;
        }


        private async Task CheckForNextFlightPlanAfterArrivalAsync()
        {
            try
            {
                if (!Connected ||
                    !arrivalReloadReminderShown ||
                    nextFlightPlanDetected ||
                    nextFlightPlanIgnored ||
                    string.IsNullOrWhiteSpace(loadedFlightPlanSignature) ||
                    !IsLandedAfterArrivalPhase())
                {
                    return;
                }

                if (arrivalReloadReminderStartUtc == DateTime.MinValue ||
                    DateTime.UtcNow - arrivalReloadReminderStartUtc < nextFlightPlanDetectionDelay)
                {
                    return;
                }

                if (DateTime.UtcNow - lastNextFlightPlanCheckUtc < nextFlightPlanCheckInterval)
                {
                    return;
                }

                lastNextFlightPlanCheckUtc = DateTime.UtcNow;

                string vatsimJson = await webclient.GetStringAsync("https://data.vatsim.net/v3/vatsim-data.json");
                VATSIMRootobject refreshed = JsonConvert.DeserializeObject<VATSIMRootobject>(vatsimJson);

                if (refreshed == null)
                {
                    return;
                }

                vatsimData = refreshed;

                Pilot detectedPilot = refreshed.pilots?.FirstOrDefault(pilot => pilot.cid == cid);
                Prefile detectedPrefile = refreshed.prefiles?
                    .Where(prefile => prefile.cid == cid && prefile.flight_plan != null)
                    .OrderByDescending(prefile => prefile.last_updated)
                    .FirstOrDefault();

                string detectedSignature = string.Empty;
                string detectedDisplayText = string.Empty;

                if (detectedPilot?.flight_plan != null)
                {
                    string pilotSignature = BuildFlightPlanSignature(detectedPilot);

                    if (!string.IsNullOrWhiteSpace(pilotSignature) &&
                        !string.Equals(pilotSignature, loadedFlightPlanSignature, StringComparison.OrdinalIgnoreCase) &&
                        !string.Equals(pilotSignature, nextFlightPlanSignature, StringComparison.OrdinalIgnoreCase))
                    {
                        detectedSignature = pilotSignature;
                        detectedDisplayText = BuildFlightPlanDisplayText(detectedPilot);
                    }
                }

                if (string.IsNullOrWhiteSpace(detectedSignature) && detectedPrefile?.flight_plan != null)
                {
                    string prefileSignature = BuildFlightPlanSignature(detectedPrefile);

                    if (!string.IsNullOrWhiteSpace(prefileSignature) &&
                        !string.Equals(prefileSignature, loadedFlightPlanSignature, StringComparison.OrdinalIgnoreCase) &&
                        !string.Equals(prefileSignature, nextFlightPlanSignature, StringComparison.OrdinalIgnoreCase))
                    {
                        detectedSignature = prefileSignature;
                        detectedDisplayText = BuildFlightPlanDisplayText(detectedPrefile);
                    }
                }

                if (string.IsNullOrWhiteSpace(detectedSignature))
                {
                    if (nextFlightPlanDetected)
                    {
                        nextFlightPlanDetected = false;
                        nextFlightPlanSignature = string.Empty;
                        nextFlightPlanDisplayText = string.Empty;
                        HideNextFlightPlanPrompt();
                        UpdateFlightPhaseBadge();
                    }

                    return;
                }

                if (IsSameAsCurrentLoadedFlightPlanDisplay(detectedDisplayText))
                {
                    Logger.Debug("Ignored false NEW FP candidate because it matches the active flight plan display: " + detectedDisplayText);
                    loadedFlightPlanSignature = detectedSignature;
                    nextFlightPlanDetected = false;
                    nextFlightPlanSignature = string.Empty;
                    nextFlightPlanDisplayText = string.Empty;
                    HideNextFlightPlanPrompt();
                    UpdateFlightPhaseBadge();
                    return;
                }

                nextFlightPlanDetected = true;
                nextFlightPlanSignature = detectedSignature;
                nextFlightPlanDisplayText = detectedDisplayText;

                WriteNextFlightPlanPrompt(nextFlightPlanDisplayText);
                UpdateFlightPhaseBadge();
            }
            catch (Exception ex)
            {
                Logger.Debug("Next flight plan detection failed: " + ex.Message);
            }
        }

        private System.Windows.Forms.Label CreateNextFlightPromptButton(string text)
        {
            return new DcduBadgeLabel
            {
                AutoSize = false,
                BackColor = Color.Transparent,
                ForeColor = DcduTheme.Amber,
                Font = CreateDpiStablePixelFont(textFontBold.FontFamily, Math.Max(7.0f, textFontBold.Size - 2.4f), FontStyle.Bold),
                Text = text,
                TextAlign = ContentAlignment.MiddleCenter,
                Cursor = Cursors.Hand,
                TabStop = true,
                Width = 58,
                Height = 20,
                Margin = new Padding(0, 0, 4, 0)
            };
        }

        private void WriteNextFlightPlanPrompt(string displayText)
        {
            HideNextFlightPlanPrompt();

            SafeUi(() =>
            {
                if (outputTable == null || outputTable.IsDisposed)
                {
                    return;
                }

                nextFlightPlanPromptPanel = new Panel
                {
                    AutoSize = false,
                    BackColor = Color.Transparent,
                    Height = 45,
                    Width = Math.Max(300, outputTable.Width - 86),
                    Margin = new Padding(0, 3, 0, 2)
                };

                System.Windows.Forms.Label promptText = new System.Windows.Forms.Label
                {
                    AutoSize = false,
                    BackColor = Color.Transparent,
                    ForeColor = DcduTheme.Amber,
                    Font = CreateDpiStablePixelFont(textFontBold.FontFamily, Math.Max(7.0f, textFontBold.Size - 2.4f), FontStyle.Bold),
                    Text = "NEW FP DETECTED " + (displayText ?? string.Empty).Trim().ToUpperInvariant(),
                    TextAlign = ContentAlignment.MiddleLeft,
                    Location = new Point(0, 0),
                    Size = new Size(nextFlightPlanPromptPanel.Width, 18)
                };

                System.Windows.Forms.Label reloadButton = CreateNextFlightPromptButton("RLD FP");
                reloadButton.Location = new Point(0, 22);
                reloadButton.Click += async (_, __) =>
                {
                    nextFlightPlanDetected = false;
                    HideNextFlightPlanPrompt();
                    await ReloadFlightPlanDataAsync(true);
                };

                System.Windows.Forms.Label ignoreButton = CreateNextFlightPromptButton("IGNORE");
                ignoreButton.Location = new Point(66, 22);
                ignoreButton.Click += (_, __) =>
                {
                    nextFlightPlanIgnored = true;
                    nextFlightPlanDetected = false;
                    HideNextFlightPlanPrompt();
                    UpdateFlightPhaseBadge();
                    Logger.Debug("NEW FLIGHT PLAN IGNORED");
                };

                nextFlightPlanPromptPanel.Controls.Add(promptText);
                nextFlightPlanPromptPanel.Controls.Add(reloadButton);
                nextFlightPlanPromptPanel.Controls.Add(ignoreButton);

                // Append first, then normalize the whole table. Inserting at
                // index 0 with TableLayoutHelper moved occupied cells one at
                // a time and could disassociate live messages from their icons.
                int promptAppendRow = outputTable.RowCount;
                outputTable.RowCount = promptAppendRow + 1;
                outputTable.Controls.Add(CreateLabel(DateTime.Now.ToString("HH:mm")), 0, promptAppendRow);
                outputTable.Controls.Add(nextFlightPlanPromptPanel, 1, promptAppendRow);
                outputTable.Controls.Add(CreateTimerLabel(">>", true), 2, promptAppendRow);
                overviewRowsNeedRebuild = true;
                ApplyMessageFilter();
                if (outputTable.AutoScroll)
                {
                    outputTable.AutoScrollPosition = Point.Empty;
                }
                HideNativeOutputScrollbars();
            });

            PlayCallsignMismatchSound();
        }

        private void HideNextFlightPlanPrompt()
        {
            SafeUi(() =>
            {
                if (nextFlightPlanPromptPanel == null)
                {
                    return;
                }

                if (outputTable != null && !outputTable.IsDisposed)
                {
                    try
                    {
                        TableLayoutPanelCellPosition pos = outputTable.GetPositionFromControl(nextFlightPlanPromptPanel);
                        int row = pos.Row;

                        if (row >= 0)
                        {
                            List<Control> rowControls = outputTable.Controls
                                .Cast<Control>()
                                .Where(control => outputTable.GetPositionFromControl(control).Row == row)
                                .ToList();

                            foreach (Control control in rowControls)
                            {
                                outputTable.Controls.Remove(control);
                                control.Dispose();
                            }

                            if (row < outputTable.RowStyles.Count)
                            {
                                outputTable.RowStyles[row].SizeType = SizeType.Absolute;
                                outputTable.RowStyles[row].Height = 0F;
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Logger.Debug("Hide next flight plan prompt row failed: " + ex.Message);
                        nextFlightPlanPromptPanel.Visible = false;
                    }
                }
                else
                {
                    nextFlightPlanPromptPanel.Visible = false;
                }

                nextFlightPlanPromptPanel = null;
                overviewRowsNeedRebuild = true;
                ApplyMessageFilter();
                HideNativeOutputScrollbars();
            });
        }

        private void MaybeShowArrivalReloadReminder()
        {
            try
            {
                if (!Connected || userVATSIMData?.flight_plan == null)
                {
                    arrivalReloadReminderStartUtc = DateTime.MinValue;
                    return;
                }

                string callsignNow = (userVATSIMData.callsign ?? string.Empty).Trim().ToUpperInvariant();
                string departure = userVATSIMData.flight_plan.departure?.Trim().ToUpperInvariant() ?? string.Empty;
                string arrival = userVATSIMData.flight_plan.arrival?.Trim().ToUpperInvariant() ?? string.Empty;
                string signature = callsignNow + "|" + departure + "|" + arrival;

                if (!string.Equals(signature, arrivalReloadReminderSignature, StringComparison.OrdinalIgnoreCase))
                {
                    arrivalReloadReminderSignature = signature;
                    arrivalReloadReminderShown = false;
                    arrivalReloadReminderStartUtc = DateTime.MinValue;
                }

                if (arrivalReloadReminderShown || !preferArrivalStationAfterAirborne || string.IsNullOrWhiteSpace(arrival))
                {
                    return;
                }

                bool appearsLandedAfterArrival = userVATSIMData.groundspeed < 60 && userVATSIMData.altitude < 3000;

                if (!appearsLandedAfterArrival)
                {
                    return;
                }

                arrivalReloadReminderShown = true;
                arrivalReloadReminderStartUtc = DateTime.UtcNow;

                WriteMessage("ARRIVAL DETECTED. NEW FP WATCH ACTIVE.", "SYSTEM", "SYSTEM");
                UpdateFlightPhaseBadge();
            }
            catch (Exception ex)
            {
                Logger.Debug("Arrival reload reminder failed: " + ex.Message);
            }
        }

        private void UpdateOnlineStatusLabel()
        {
            string station = GetSmartAtisStationForHover();

            if (string.IsNullOrWhiteSpace(station))
            {
                datalinkStatusText = "PDC --";
                atisStatusText = BuildDotBadgeText("ATIS");
                atisAvailabilityState = "UNKNOWN";
                UpdateClearanceStatusLabel();
                UpdateFlightPhaseBadge();
                return;
            }

            station = station.ToUpperInvariant();

            PdcDiscoveryResult pdcDiscovery = DiscoverPdcAvailability(station);
            bool atisGeneric = HasAtisDataForTarget(station);
            bool atisArrival = HasAtisDataForTarget(station + "_A");
            bool atisDeparture = HasAtisDataForTarget(station + "_D");
            bool hasAnyAtis = atisGeneric || atisArrival || atisDeparture;

            string datalinkText = hoppieOnlineStationsLoaded
                ? pdcDiscovery.StatusText
                : "?";

            datalinkStatusText = "PDC " + datalinkText;
            pdcDiscoveryHoverText = pdcDiscovery.HoverText;
            pdcDiscoveryLogonCode = pdcDiscovery.LogonCode ?? string.Empty;
            pdcDiscoveryController = pdcDiscovery.Controller ?? string.Empty;
            pdcDiscoverySource = pdcDiscovery.Source ?? string.Empty;
            pdcDiscoveryIsFallbackCandidate = pdcDiscovery.IsFallbackCandidate;
            pdcDiscoveryAllowReqClr = pdcDiscovery.AllowReqClr;
            UpdateCpdlcDiscoveryFromVatsim();
            atisStatusText = BuildDotBadgeText("ATIS");
            atisAvailabilityState = hasAnyAtis
                ? "ONLINE"
                : vatsimData?.atis == null ? "UNKNOWN" : "OFFLINE";

            UpdateClearanceStatusLabel();

            if (atisAvailabilityPopupPanel != null && atisAvailabilityPopupPanel.Visible)
            {
                UpdateAtisAvailabilityPopupText();
            }

            MaybeShowPdcAvailabilityHint(station, pdcDiscovery.IsAvailable);
            MaybeShowArrivalReloadReminder();
            UpdateFlightPhaseBadge();
        }

        private string GetPrimaryOnlineStatusStation()
        {
            if (!string.IsNullOrWhiteSpace(CurrentATCUnit) && CurrentATCUnit.Length >= 4)
            {
                return CurrentATCUnit.Substring(0, 4);
            }

            if (userVATSIMData?.flight_plan != null)
            {
                if (!string.IsNullOrWhiteSpace(userVATSIMData.flight_plan.departure))
                {
                    return userVATSIMData.flight_plan.departure;
                }

                if (!string.IsNullOrWhiteSpace(userVATSIMData.flight_plan.arrival))
                {
                    return userVATSIMData.flight_plan.arrival;
                }
            }

            return string.Empty;
        }

        private bool IsControllerOnlineForStation(string station)
        {
            if (!hoppieOnlineStationsLoaded || string.IsNullOrWhiteSpace(station))
            {
                return false;
            }

            string upper = station.ToUpperInvariant();

            return hoppieOnlineStations.Any(hoppieStation =>
            {
                string candidate = (hoppieStation ?? string.Empty).ToUpperInvariant();
                return candidate == upper ||
                       candidate.StartsWith(upper + "_", StringComparison.Ordinal) ||
                       candidate.StartsWith(upper, StringComparison.Ordinal);
            });
        }
