                {
                    SetCpdlcHelperStandbyText("CPDLC helper disabled\nClick radar icon to enable.");
                }

                UpdateCpdlcDiscoveryLabel();
                ShowCpdlcLogonPopup();
            };

            cpdlcLogonPopupPanel.Controls.Add(toggleLabel);
        }

        private void ShowCpdlcLogonPopup()
        {
            if (cpdlcLogonPopupPanel == null)
            {
                ConfigureCpdlcLogonPopup();
            }

            if (cpdlcLogonPopupPanel == null)
            {
                return;
            }

            cpdlcLogonPopupPanel.SuspendLayout();
            cpdlcLogonPopupPanel.Controls.Clear();

            int popupWidth = S(326);
            int y = 6;
            Font headerFont = PopupHeaderFont();
            Font rowFont = PopupRowFont();

            AddCpdlcPopupLabel("CPDLC LOGON HELPER", 8, y, 142, 18, PopupHeaderTextColor(MainAccentColor()), headerFont);
            AddCpdlcHelperHeaderToggle(popupWidth);
            AddCpdlcPopupCloseAction(popupWidth);
            y += 26;

            if (CpdlcHelperPopupDebugPreview)
            {
                AddCpdlcPopupLabel("DEBUG PREVIEW", 8, y, popupWidth - 16, 16, PopupContentTextColor(DcduTheme.Amber), rowFont);
                y += 26;
                AddCpdlcPopupLabel("CONNECTED TO LOVV", 8, y, popupWidth - 16, 16, MainPrimaryTextColor(), rowFont);
                y += 21;

                LayoutCpdlcLogonPopup(popupWidth, Math.Max(64, y + 5));
                cpdlcLogonPopupPanel.ResumeLayout();
                cpdlcLogonPopupPanel.Visible = true;
                cpdlcLogonPopupPanel.BringToFront();
                cpdlcLogonPopupPanel.Focus();
                cpdlcLogonPopupPanel.Invalidate();
                return;
            }

            if (!string.IsNullOrWhiteSpace(_currentATCUnit))
            {
                string state = "CONNECTED TO " + _currentATCUnit.Trim().ToUpperInvariant();
                AddCpdlcPopupLabel(state, 8, y, popupWidth - 16, 16, MainPrimaryTextColor(), rowFont);
                y += 26;
                AddCpdlcPopupLogoffAction(_currentATCUnit, y);
                y += 26;

                LayoutCpdlcLogonPopup(popupWidth, Math.Max(82, y + 5));
                cpdlcLogonPopupPanel.ResumeLayout();
                cpdlcLogonPopupPanel.Visible = true;
                cpdlcLogonPopupPanel.BringToFront();
                cpdlcLogonPopupPanel.Focus();
                cpdlcLogonPopupPanel.Invalidate();
                return;
            }

            if (!cpdlcHelperEnabled)
            {
                AddCpdlcPopupLabel("HELPER DISABLED", 8, y, popupWidth - 16, 16, NeutralStatusBadgeColor(), rowFont);
                y += 26;
                AddCpdlcPopupLabel("NO STATION SUGGESTIONS WILL BE SHOWN", 8, y, popupWidth - 16, 16, MainPrimaryTextColor(), rowFont);
                y += 26;
                LayoutCpdlcLogonPopup(popupWidth, Math.Max(72, y + 5));
                cpdlcLogonPopupPanel.ResumeLayout();
                cpdlcLogonPopupPanel.Visible = true;
                cpdlcLogonPopupPanel.BringToFront();
                cpdlcLogonPopupPanel.Focus();
                cpdlcLogonPopupPanel.Invalidate();
                return;
            }

            if (IsCpdlcHelperSuppressedByConnection())
            {
                string state = "HANDOVER / LOGON PENDING";

                AddCpdlcPopupLabel(state, 8, y, popupWidth - 16, 16, MainPrimaryTextColor(), rowFont);
                y += 26;
                LayoutCpdlcLogonPopup(popupWidth, Math.Max(58, y + 5));
                cpdlcLogonPopupPanel.ResumeLayout();
                cpdlcLogonPopupPanel.Visible = true;
                cpdlcLogonPopupPanel.BringToFront();
                cpdlcLogonPopupPanel.Focus();
                cpdlcLogonPopupPanel.Invalidate();
                return;
            }

            List<long> currentPilotFreqs = IsVatsimTransceiverDataStale()
                ? new List<long>()
                : GetPilotTunedFrequencies();

            List<CpdlcDiscoveryResult> candidates = cpdlcDiscoveryCandidates
                .Where(candidate => candidate != null &&
                                    candidate.Possible &&
                                    !string.IsNullOrWhiteSpace(candidate.Code) &&
                                    IsHoppieLogonOnline(candidate.Code) &&
                                    !IsCpdlcVerifiedSuggestionCooldownActive(candidate.Code, candidate.Controller, out _))
                .Select(candidate => VerifyCandidateAgainstActiveFrequency(candidate, currentPilotFreqs))
                .Where(candidate => !IsCpdlcHelperIgnoredControllerCallsign(candidate.Controller))
                .GroupBy(candidate => candidate.Code.Trim().ToUpperInvariant() + "|" + (candidate.Controller ?? string.Empty).Trim().ToUpperInvariant())
                .Select(group => OrderCpdlcCandidates(group).First())
                .OrderBy(candidate => candidate.IsTunedFrequencyMatch ? 0 : 1)
                .ThenBy(GetCpdlcCandidateDistanceSortValue)
                .ThenBy(GetCpdlcCandidateSortScore)
                .ThenBy(candidate => candidate.Controller ?? string.Empty)
                .ToList();

            if (candidates.Count == 0 && CanQuickCpdlcLogon())
            {
                candidates.Add(new CpdlcDiscoveryResult
                {
                    Possible = true,
                    Code = cpdlcDiscoveryLogonCode,
                    Controller = cpdlcDiscoveryController,
                    MatchReason = "current candidate"
                });
            }

            if (candidates.Count == 0)
            {
                AddCpdlcPopupLabel("NO CPDLC CANDIDATE", 8, y, popupWidth - 16, 16, NeutralStatusBadgeColor(), rowFont);
                y += 26;
                AddCpdlcPopupLabel("HELPER ACTIVE / STANDBY", 8, y, popupWidth - 16, 16, MainPrimaryTextColor(), rowFont);
                y += 26;
                LayoutCpdlcLogonPopup(popupWidth, Math.Max(72, y + 5));
                cpdlcLogonPopupPanel.ResumeLayout();
                cpdlcLogonPopupPanel.Visible = true;
                cpdlcLogonPopupPanel.BringToFront();
                cpdlcLogonPopupPanel.Focus();
                cpdlcLogonPopupPanel.Invalidate();
                return;
            }

            CpdlcDiscoveryResult tuned = candidates.FirstOrDefault(candidate => candidate.IsTunedFrequencyMatch);
            List<CpdlcDiscoveryResult> others = candidates
                .Where(candidate => tuned == null ||
                                    !string.Equals(candidate.Code, tuned.Code, StringComparison.OrdinalIgnoreCase) ||
                                    !string.Equals(candidate.Controller, tuned.Controller, StringComparison.OrdinalIgnoreCase))
                .ToList();

            if (tuned != null)
            {
                string code = tuned.Code.Trim().ToUpperInvariant();
                string controller = (tuned.Controller ?? string.Empty).Trim().ToUpperInvariant();
                string frequency = string.IsNullOrWhiteSpace(tuned.FrequencyText) ? "ACTIVE FREQ" : tuned.FrequencyText;

                AddCpdlcPopupLabel("VERIFIED ACTIVE FREQ CPDLC", 8, y, popupWidth - 16, 16, PopupHeaderTextColor(MainAccentColor()), rowFont);
                y += 21;
                AddCpdlcPopupLabel((string.IsNullOrWhiteSpace(controller) ? "UNKNOWN" : controller) + "   " + frequency, 8, y, popupWidth - 16, 16, MainPrimaryTextColor(), rowFont);
                y += 21;
                AddCpdlcPopupLabel("LOGON: " + code, 8, y, popupWidth - 16, 16, MainPrimaryTextColor(), rowFont);
                y += 21;
                AddCpdlcPopupAction("> LOGON TO " + code, code, controller, "Verified on your active VATSIM frequency\nController: " + controller + "\nLogon: " + code, y);
                y += 23;
            }

            if (others.Count > 0)
            {
                if (tuned != null)
                {
                    AddCpdlcPopupLabel("──────────────────────────────", 8, y, popupWidth - 16, 16, Color.FromArgb(150, MainPrimaryTextColor()), rowFont);
                    y += 21;
                }

                bool hasRouteCandidate = others.Any(candidate =>
                    (candidate.MatchReason ?? string.Empty)
                        .ToUpperInvariant()
                        .Contains("FLIGHT PLAN ROUTE FIR"));

                string candidatesTitle = tuned == null
                    ? (hasRouteCandidate
                        ? "POSSIBLE CPDLC ATC / ROUTE"
                        : "POSSIBLE CPDLC ATC NEARBY")
                    : "OTHER CPDLC CANDIDATES";

                const int candidateTitleHeight = 26;
                const int candidateRowHeight = 26;
                const int candidateListMaxHeight = 128;

                int candidateContentHeight =
                    candidateTitleHeight +
                    (others.Count * candidateRowHeight) +
                    2;

                int candidateViewportHeight = Math.Min(
                    candidateListMaxHeight,
                    Math.Max(52, candidateContentHeight));

                Panel candidateListPanel =
                    CreateCpdlcCandidateScrollPanel(
                        popupWidth,
                        y,
                        candidateViewportHeight);

                if (candidateListPanel != null)
                {
                    int candidateY = 0;

                    AddCpdlcCandidateListLabel(
                        candidateListPanel,
                        candidatesTitle,
                        candidateY,
                        PopupHeaderTextColor(MainAccentColor()),
                        rowFont);

                    candidateY += candidateTitleHeight;

                    foreach (CpdlcDiscoveryResult candidate in others)
                    {
                        string code = candidate.Code.Trim().ToUpperInvariant();
                        string controller = (candidate.Controller ?? string.Empty)
                            .Trim()
                            .ToUpperInvariant();
                        string caption = "> LOGON TO " + code;

                        string frequency = string.IsNullOrWhiteSpace(candidate.FrequencyText)
                            ? string.Empty
                            : "\nFrequency: " + candidate.FrequencyText.Trim();

                        AddCpdlcCandidateListAction(
                            candidateListPanel,
                            caption,
                            code,
                            controller,
                            "Controller: " + controller +
                            frequency +
                            "\nLogon: " + code +
                            "\n" + (candidate.MatchReason ?? string.Empty),
                            candidateY);

                        candidateY += candidateRowHeight;
                    }

                    ConfigureCpdlcCandidateScrollContent(
                        candidateListPanel,
                        Math.Max(
                            candidateY,
                            candidateContentHeight));
                }

                y += candidateViewportHeight;
            }
            else if (tuned != null)
            {
                AddCpdlcPopupLabel("──────────────────────────────", 8, y, popupWidth - 16, 16, Color.FromArgb(120, MainPrimaryTextColor()), rowFont);
                y += 26;
                AddCpdlcPopupLabel("NO OTHER CPDLC ATC ONLINE", 8, y, popupWidth - 16, 16, Color.FromArgb(170, MainPrimaryTextColor()), rowFont);
                y += 21;
            }

            LayoutCpdlcLogonPopup(popupWidth, Math.Max(58, y + 5));

            cpdlcLogonPopupPanel.ResumeLayout();
            cpdlcLogonPopupPanel.Visible = true;
            cpdlcLogonPopupPanel.BringToFront();
            cpdlcLogonPopupPanel.Focus();
            cpdlcLogonPopupPanel.Invalidate();
        }

        private bool CanQuickCpdlcLogon()
        {
            if (DebugUiPreviewMode)
            {
                return !string.IsNullOrWhiteSpace(cpdlcDiscoveryLogonCode);
            }

            return Connected &&
                   IsHoppieCallsignReadyForInteractiveMenus() &&
                   cpdlcHelperEnabled &&
                   !IsCpdlcHelperSuppressedByConnection() &&
                   string.Equals(cpdlcDiscoveryText, "possible", StringComparison.OrdinalIgnoreCase) &&
                   !string.IsNullOrWhiteSpace(cpdlcDiscoveryLogonCode) &&
                   IsHoppieLogonOnline(cpdlcDiscoveryLogonCode);
        }

        private bool CanQuickRequestClearance()
        {
            if (DebugUiPreviewMode)
            {
                return !string.IsNullOrWhiteSpace(pdcDiscoveryLogonCode);
            }

            if (!Connected ||
                !IsHoppieCallsignReadyForInteractiveMenus() ||
                string.IsNullOrWhiteSpace(pdcDiscoveryLogonCode) ||
                !pdcDiscoveryAllowReqClr ||
                !IsHoppieLogonOnline(pdcDiscoveryLogonCode))
            {
                return false;
            }

            // REQ CLR is a ground/departure PDC/DCL action. Do not offer it once airborne.
            if (IsAirborneForStatusBadges())
            {
                return false;
            }

            string status = (datalinkStatusText ?? string.Empty).ToUpperInvariant();
            return status.Contains("AVAIL") || status.Contains("MAYBE");
        }

        private bool HasPdcPopupCandidate()
        {
            if (DebugUiPreviewMode)
            {
                return !string.IsNullOrWhiteSpace(pdcDiscoveryLogonCode);
            }

            if (!Connected ||
                !IsHoppieCallsignReadyForInteractiveMenus() ||
                string.IsNullOrWhiteSpace(pdcDiscoveryLogonCode) ||
                !IsHoppieLogonOnline(pdcDiscoveryLogonCode) ||
                IsAirborneForStatusBadges())
            {
                return false;
            }

            string status = (datalinkStatusText ?? string.Empty).ToUpperInvariant();
            return status.Contains("AVAIL") || status.Contains("MAYBE");
        }

        private void TogglePdcQuickActionButton()
        {
            if (pdcActionPopupPanel != null && pdcActionPopupPanel.Visible && pdcQuickActionPinned)
            {
                HidePdcQuickActionButton();
                return;
            }

            if (!HasPdcPopupCandidate())
            {
                Logger.Debug("PDC popup click ignored: no green/amber PDC-DCL candidate.");
                HidePdcQuickActionButton();
                return;
            }

            pdcQuickActionPinned = true;
            ShowPdcQuickActionButton();
        }

        private void ConfigurePdcActionPopup()
        {
            if (screenPanel == null || pdcActionPopupPanel != null)
            {
                return;
            }

            pdcActionPopupPanel = new Panel
            {
                BackColor = Color.Transparent,
                Visible = false,
                Size = SS(new Size(260, 105))
            };

            pdcActionPopupPanel.Paint += (_, e) =>
            {
                Color accent = pdcDiscoveryIsFallbackCandidate ? DcduTheme.Amber : DcduTheme.Green;
                PaintStyleAwarePopupPanel(pdcActionPopupPanel, e, accent, pdcQuickActionPinned);
            };

            pdcActionPopupPanel.MouseLeave += (_, __) => { };
            screenPanel.Controls.Add(pdcActionPopupPanel);
            pdcActionPopupPanel.BringToFront();
        }

        private void AddPdcPopupLabel(string text, int x, int y, int width, int height, Color color, Font font)
        {
            if (pdcActionPopupPanel == null)
            {
                return;
            }

            pdcActionPopupPanel.Controls.Add(new System.Windows.Forms.Label
            {
                AutoSize = false,
                BackColor = Color.Transparent,
                ForeColor = color,
                Font = font,
                Text = text,
                TextAlign = ContentAlignment.MiddleLeft,
                Location = new Point(ScaleChildX(pdcActionPopupPanel, x, width), ScaleChildY(pdcActionPopupPanel, y, height)),
                Size = new Size(ScaleChildWidth(pdcActionPopupPanel, x, width), ScaleChildHeight(pdcActionPopupPanel, y, height)),
                Margin = SPad(new Padding(0)),
                Padding = SPad(new Padding(0))
            });
        }

        private void AddPdcPopupAction(string code, int y)
        {
            if (pdcActionPopupPanel == null)
            {
                return;
            }

            string caption = "> REQ CLR TO " + code;
            System.Windows.Forms.Label label = new System.Windows.Forms.Label
            {
                AutoSize = false,
                BackColor = Color.Transparent,
                ForeColor = MainPrimaryTextColor(),
                Font = PopupRowFont(),
                Text = caption,
                TextAlign = ContentAlignment.MiddleLeft,
                Location = new Point(ScaleChildX(pdcActionPopupPanel, 8, pdcActionPopupPanel.Width - S(16)), ScaleChildY(pdcActionPopupPanel, y, 18)),
                Size = new Size(Math.Max(1, pdcActionPopupPanel.Width - S(16)), ScaleChildHeight(pdcActionPopupPanel, y, 18)),
                Cursor = Cursors.Hand
            };

            smartStatusToolTip.SetToolTip(label, "Send pre-departure clearance request to " + code);
            label.MouseEnter += (_, __) => label.ForeColor = DcduTheme.Amber;
            label.MouseLeave += (_, __) => label.ForeColor = MainPrimaryTextColor();
            label.Click += async (_, __) => await QuickRequestPredepClearanceAsync();

            pdcActionPopupPanel.Controls.Add(label);
        }

        private void ShowPdcQuickActionButton()
        {
            if (!HasPdcPopupCandidate())
            {
                HidePdcQuickActionButton();
                return;
            }

            if (pdcActionPopupPanel == null)
            {
                ConfigurePdcActionPopup();
            }

            if (pdcActionPopupPanel == null)
            {
                return;
            }

            pdcActionPopupPanel.SuspendLayout();
            pdcActionPopupPanel.Controls.Clear();

            string code = pdcDiscoveryLogonCode.Trim().ToUpperInvariant();
            string controller = (pdcDiscoveryController ?? string.Empty).Trim().ToUpperInvariant();
            string source = string.IsNullOrWhiteSpace(pdcDiscoverySource)
                ? (pdcDiscoveryIsFallbackCandidate ? "CTR/FSS DEP FIR MATCH" : "LOCAL MATCH")
                : pdcDiscoverySource.Trim().ToUpperInvariant();

            bool amberCandidate = pdcDiscoveryIsFallbackCandidate || (datalinkStatusText ?? string.Empty).ToUpperInvariant().Contains("MAYBE");

            int popupWidth = S(306);
            int y = 6;
            Font headerFont = PopupHeaderFont();
            Font rowFont = PopupRowFont();

            AddPdcPopupLabel(amberCandidate ? "PDC / DCL CANDIDATE" : "PDC / DCL AVAILABLE", 8, y, popupWidth - 16, 18, PopupHeaderTextColor(MainAccentColor()), headerFont);
            y += 26;

            AddPdcPopupLabel(source, 8, y, popupWidth - 16, 16, MainPrimaryTextColor(), rowFont);
            y += 26;

            if (!string.IsNullOrWhiteSpace(controller))
            {
                AddPdcPopupLabel(controller, 8, y, popupWidth - 16, 16, MainPrimaryTextColor(), rowFont);
                y += 26;
            }

            AddPdcPopupLabel("LOGON: " + code, 8, y, popupWidth - 16, 16, MainPrimaryTextColor(), rowFont);
            y += 26;

            if (amberCandidate)
            {
                AddPdcPopupLabel("DOUBLE CHECK ON VATSIM RADAR", 8, y, popupWidth - 16, 16, PopupContentTextColor(DcduTheme.Amber), rowFont);
                y += 26;
            }

            AddPdcPopupAction(code, y);
            y += 26;

            pdcActionPopupPanel.Size = new Size(popupWidth, S(Math.Max(92, y + 5)));
            pdcActionPopupPanel.Location = new Point(
                Math.Max(S(4), Math.Min(datalinkStatusLabel.Left - S(64), screenPanel.Width - pdcActionPopupPanel.Width - S(4))),
                Math.Max(S(4), Math.Min(datalinkStatusLabel.Bottom + S(2), screenPanel.Height - pdcActionPopupPanel.Height - S(4))));

            pdcActionPopupPanel.ResumeLayout();
            pdcActionPopupPanel.Visible = true;
            pdcActionPopupPanel.BringToFront();
            pdcActionPopupPanel.Invalidate();
        }

        private void HidePdcQuickActionButton()
        {
            pdcQuickActionPinned = false;

            if (pdcActionDebugLabel != null)
            {
                pdcActionDebugLabel.Visible = false;
            }

            if (pdcActionPopupPanel != null)
            {
                pdcActionPopupPanel.Visible = false;
            }
        }

        private void ShowCpdlcQuickActionButton()
        {
            // Kept for compatibility with older layout code.
            // CPDLC LOGON is intentionally click-only now; hover must not open the popup.
            if (!CanQuickCpdlcLogon())
            {
                HideCpdlcLogonPopup();
            }
        }

        private void HideQuickActionButtons()
        {
            HidePdcQuickActionButton();

            if (CpdlcHelperPopupDebugPreview && cpdlcLogonPopupPinned)
            {
                return;
            }

            if (cpdlcActionDebugLabel != null)
            {
                cpdlcActionDebugLabel.Visible = false;
            }

            HideCpdlcLogonPopup();
        }

        private void HideMainScreenQuickActionButtonsAfterReturn()
        {
            pdcQuickActionPinned = false;
            cpdlcLogonPopupPinned = false;
            HideQuickActionButtons();

            if (pdcActionDebugLabel != null)
            {
                pdcActionDebugLabel.Visible = false;
                pdcActionDebugLabel.Enabled = false;
            }

            if (cpdlcActionDebugLabel != null)
            {
                cpdlcActionDebugLabel.Visible = false;
                cpdlcActionDebugLabel.Enabled = false;
            }

            if (pdcActionPopupPanel != null)
            {
                pdcActionPopupPanel.Visible = false;
            }

            if (cpdlcLogonPopupPanel != null)
            {
                cpdlcLogonPopupPanel.Visible = false;
            }
        }

        private void HideCpdlcLogonPopup()
        {
            cpdlcLogonPopupPinned = false;

            if (cpdlcLogonPopupPanel != null)
            {
                cpdlcLogonPopupPanel.Visible = false;
            }
        }

        private void ScheduleHideQuickActionButtons()
        {
            if (pdcQuickActionPinned || cpdlcLogonPopupPinned)
            {
                return;
            }

            try
            {
                BeginInvoke(new Action(() =>
                {
                    if (pdcQuickActionPinned || cpdlcLogonPopupPinned)
                    {
                        return;
                    }

                    if (IsCursorOver(datalinkStatusLabel) ||
                        IsCursorOver(cpdlcDiscoveryLabel) ||
                        IsCursorOver(pdcActionDebugLabel) ||
                        IsCursorOver(cpdlcActionDebugLabel) ||
                        IsCursorOver(cpdlcLogonPopupPanel))
                    {
                        return;
                    }

                    HideQuickActionButtons();
                }));
            }
            catch
            {
                HideQuickActionButtons();
            }
        }

        private static bool IsCursorOver(Control control)
        {
            return control != null &&
                   control.Visible &&
                   control.ClientRectangle.Contains(control.PointToClient(Cursor.Position));
        }

        private async Task QuickRequestPredepClearanceAsync()
        {
            if (!CanQuickRequestClearance())
            {
                WriteMessage("QUICK PDC NOT AVAILABLE", "SYSTEM", "SYSTEM");
                HideQuickActionButtons();
                return;
            }

            string recipient = pdcDiscoveryLogonCode.Trim().ToUpperInvariant();
            string clearanceCallsign = GetConnectedPilotCallsign();
            string departure = userVATSIMData?.flight_plan?.departure?.Trim().ToUpperInvariant() ?? string.Empty;
            string arrival = userVATSIMData?.flight_plan?.arrival?.Trim().ToUpperInvariant() ?? string.Empty;
            string aircraft = userVATSIMData?.flight_plan?.aircraft_short?.Trim().ToUpperInvariant() ?? string.Empty;
            string atisLetter = GetBestDepartureAtisLetter(departure);

            if (string.IsNullOrWhiteSpace(clearanceCallsign) ||
                string.IsNullOrWhiteSpace(departure) ||
                string.IsNullOrWhiteSpace(arrival) ||
                string.IsNullOrWhiteSpace(aircraft))
            {
                WriteMessage("QUICK PDC FAILED: MISSING FLIGHTPLAN DATA", "SYSTEM", "SYSTEM");
                HideQuickActionButtons();
                return;
            }

            string message = string.Format(
                "REQUEST PREDEP CLEARANCE {0} {1} TO {2} AT {3} STAND {4} ATIS {5}",
                clearanceCallsign,
                aircraft,
                arrival,
                departure,
                "----",
                string.IsNullOrWhiteSpace(atisLetter) ? "A" : atisLetter);

            HideQuickActionButtons();

            CpdlcLogonStationAvailability quickPdcAvailability =
                await VerifyPdcStationAvailabilityBeforeSendAsync(recipient);

            if (quickPdcAvailability != CpdlcLogonStationAvailability.Online)
            {
                return;
            }

            await SendCPDLCMessage(recipient, "TELEX", message.Trim());
            StartPdcStationOfflineWatch(recipient);
        }

        private async Task QuickCpdlcLogoffAsync()
        {
            string target = (CurrentATCUnit ?? pendingLogon ?? cpdlcHandoverTargetCode ?? string.Empty).Trim().ToUpperInvariant();

            if (string.IsNullOrWhiteSpace(target))
            {
                WriteMessage("CPDLC LOGOFF NOT AVAILABLE", "SYSTEM", "SYSTEM");
                HideQuickActionButtons();
                return;
            }

            HideCpdlcLogonPopup();
            HideQuickActionButtons();

            string packet = string.Format("/data2/{0}//N/LOGOFF", messageOutCounter);
            messageOutCounter += 1;

            await SendCPDLCMessage(target, "CPDLC", packet.Trim());

            cpdlcSessionEstablished = false;
            CurrentATCUnit = null;
            pendingLogon = null;
            ClearNextAtcUnitDisplay();
            StopCpdlcHandoverFrequencyWatch();
            UpdateCpdlcDiscoveryLabel();
            UpdateOnlineStatusLabel();
            UpdateCurrentAtcUnitDisplay();
        }

        private Task ExecuteCpdlcLogonFromEmbeddedMenuAsync()
        {
