                return;
            }

            quickWxPopupPinned = true;
            ShowQuickWxPopup(true);
        }


        private void ResetHardwareMessageOverviewPage()
        {
            hardwareMessageOverviewPageIndex = 0;
        }

        private List<CPDLCMessage> GetFilteredOverviewMessagesInRowOrder()
        {
            List<(int Row, CPDLCMessage Message)> ordered = new();

            if (outputTable == null || outputTable.IsDisposed)
            {
                return new List<CPDLCMessage>();
            }

            for (int row = 0; row < outputTable.RowCount; row++)
            {
                CPDLCMessage rowMessage = null;

                for (int col = 0; col < outputTable.ColumnCount; col++)
                {
                    if (outputTable.GetControlFromPosition(col, row) is CPDLCMessage message)
                    {
                        rowMessage = message;
                        break;
                    }
                }

                if (rowMessage != null &&
                    MessageMatchesFilter(rowMessage, activeMessageFilter))
                {
                    ordered.Add((row, rowMessage));
                }
            }

            return ordered
                .OrderBy(item => item.Row)
                .Select(item => item.Message)
                .ToList();
        }

        private List<CPDLCMessage> GetHardwareMessageOverviewPageList()
        {
            List<CPDLCMessage> filtered =
                GetFilteredOverviewMessagesInRowOrder();

            int pageCapacity =
                HardwareMessageOverviewPageCapacity();

            hardwareMessageOverviewPageCount =
                Math.Max(
                    1,
                    (filtered.Count + pageCapacity - 1) /
                    pageCapacity);

            hardwareMessageOverviewPageIndex =
                Math.Max(
                    0,
                    Math.Min(
                        hardwareMessageOverviewPageIndex,
                        hardwareMessageOverviewPageCount - 1));

            return filtered
                .Skip(
                    hardwareMessageOverviewPageIndex *
                    pageCapacity)
                .Take(pageCapacity)
                .ToList();
        }

        private string HardwareMessageOverviewSingleLineText(
            CPDLCMessage message)
        {
            if (message == null)
            {
                return string.Empty;
            }

            string text = CreateMessageListText(
                message.message,
                message.type,
                message.recipient,
                message.outbound);

            text = Regex.Replace(
                    (text ?? string.Empty)
                        .Replace("\r", " ")
                        .Replace("\n", " "),
                    @"\s+",
                    " ")
                .Trim();

            if (string.IsNullOrWhiteSpace(text) ||
                outputTable == null ||
                outputTable.IsDisposed)
            {
                return text;
            }

            // Use the SAME available width as the actual message column.
            // A separately estimated width could let the last characters
            // wrap below an LSK row even after text truncation.
            int maxWidth = Math.Max(
                S(80), StandardOverviewMessageMaxWidth() - S(6));

            Font font = message.Font ?? GetMessageTextFont(false);
            TextFormatFlags flags =
                TextFormatFlags.SingleLine |
                TextFormatFlags.NoPadding |
                TextFormatFlags.NoPrefix;

            if (TextRenderer.MeasureText(text, font, Size.Empty, flags).Width <= maxWidth)
            {
                return text;
            }

            const string suffix = "...";
            int low = 0;
            int high = text.Length;
            int best = 0;

            while (low <= high)
            {
                int middle = low + ((high - low) / 2);
                string candidate =
                    text.Substring(0, middle).TrimEnd() + suffix;

                int width =
                    TextRenderer.MeasureText(
                        candidate,
                        font,
                        Size.Empty,
                        flags).Width;

                if (width <= maxWidth)
                {
                    best = middle;
                    low = middle + 1;
                }
                else
                {
                    high = middle - 1;
                }
            }

            return text.Substring(0, best).TrimEnd() + suffix;
        }

        private void RestoreHardwareOverviewUnreadColors()
        {
            foreach (CPDLCMessage message in unreadMessages.ToList())
            {
                if (message == null || message.IsDisposed)
                {
                    continue;
                }

                if (IsCallsignMismatchAlarmText(message.message))
                {
                    message.ForeColor = CallsignMismatchAlarmColor();
                }
                else if (MessageNeedsOverviewReplyIndicator(
                             message.type,
                             message.outbound,
                             message.header))
                {
                    message.ForeColor = MainPrimaryTextColor();
                }
                else
                {
                    message.ForeColor = DcduTheme.Amber;
                }

                message.Invalidate();
            }
        }

        private void UpdateHardwareMessageOverviewBlinkState()
        {
            bool shouldBlink =
                ShouldUseMessageOverviewLskMode() &&
                unreadMessages.Any(message =>
                    message != null &&
                    !message.IsDisposed &&
                    !message.outbound);

            if (shouldBlink)
            {
                if (!hardwareMessageOverviewBlinkTimer.Enabled)
                {
                    hardwareMessageOverviewBlinkOn = true;
                    hardwareMessageOverviewBlinkTimer.Start();
                }
            }
            else
            {
                hardwareMessageOverviewBlinkTimer.Stop();
                hardwareMessageOverviewBlinkOn = false;
                RestoreHardwareOverviewUnreadColors();
            }
        }

        private void HardwareMessageOverviewBlinkTimer_Tick(
            object sender,
            EventArgs e)
        {
            if (!ShouldUseMessageOverviewLskMode())
            {
                UpdateHardwareMessageOverviewBlinkState();
                return;
            }

            hardwareMessageOverviewBlinkOn =
                !hardwareMessageOverviewBlinkOn;

            HashSet<CPDLCMessage> visiblePage =
                GetHardwareMessageOverviewPageList().ToHashSet();

            foreach (CPDLCMessage message in unreadMessages.ToList())
            {
                if (message == null ||
                    message.IsDisposed ||
                    !visiblePage.Contains(message) ||
                    IsCallsignMismatchAlarmText(message.message))
                {
                    continue;
                }

                message.ForeColor = hardwareMessageOverviewBlinkOn
                    ? DcduTheme.Amber
                    : MainPrimaryTextColor();

                message.Invalidate();
            }
        }

        private HashSet<CPDLCMessage> GetHardwareMessageOverviewPageMessages()
        {
            return GetHardwareMessageOverviewPageList()
                .ToHashSet();
        }

        // Unlike the Airbus/Boeing LSK pages, A220 scrolls through its normal
        // variable-height messages. This indicator reflects the REAL vertical
        // scroll range, rather than imposing hardware LSK slots on A220.
        private void CalculateA220OverviewPages()
        {
            a220OverviewPageIndex = 0;
            a220OverviewPageCount = 1;
            a220OverviewMaxScroll = 0;
            if (!DcduStyleManager.IsA220 || outputTable == null ||
                outputTable.IsDisposed || outputTable.ClientSize.Height <= 0 ||
                !standardOverviewExtentValid)
            {
                return;
            }

            // A220 uses standard scrolling, never physical LSK pages. Both
            // its indicator and the actual scrollbar share the same measured
            // content extent, not the self-inflating DisplayRectangle.
            a220OverviewMaxScroll = standardOverviewMaximumOffset;
            if (a220OverviewMaxScroll <= 0)
            {
                return;
            }

            int viewport = Math.Max(1, outputTable.ClientSize.Height);
            a220OverviewPageCount = Math.Max(2,
                (standardOverviewContentBottom + viewport - 1) / viewport);
            int scrollY = Math.Max(0, Math.Min(a220OverviewMaxScroll,
                -outputTable.AutoScrollPosition.Y));
            a220OverviewPageIndex = Math.Min(a220OverviewPageCount - 1,
                (int)Math.Round((double)scrollY *
                    (a220OverviewPageCount - 1) / a220OverviewMaxScroll));
        }

        private void ChangeA220OverviewPage(int delta)
        {
            if (!DcduStyleManager.IsA220 || delta == 0 ||
                outputTable == null || outputTable.IsDisposed ||
                !outputTable.Visible || !outputTable.AutoScroll)
            {
                return;
            }

            CalculateA220OverviewPages();
            if (a220OverviewPageCount <= 1)
            {
                return;
            }
            int targetPage = Math.Max(0, Math.Min(
                a220OverviewPageCount - 1, a220OverviewPageIndex + delta));
            int desiredOffset = (int)Math.Round(
                (double)targetPage * a220OverviewMaxScroll /
                (a220OverviewPageCount - 1));
            outputTable.AutoScrollPosition = new Point(0, desiredOffset);
            HideNativeOutputScrollbars();
            UpdateHardwareMessageOverviewPageBar();
            RefreshOutputScrollSurfaceOnly();
        }

        private void EnsureHardwareMessageOverviewPageBar()
        {
            if (hardwareMessageOverviewPageBar != null &&
                !hardwareMessageOverviewPageBar.IsDisposed)
            {
                return;
            }

            // The hardware overview scrolls through logical LSK pages, never
            // through a scrollable message list. Use a small page counter in
            // the header instead of a misleading vertical scroll bar.
            hardwareMessageOverviewPageBar = new Panel
            {
                BackColor = Color.Transparent,
                BorderStyle = BorderStyle.None,
                Visible = false,
                Cursor = Cursors.Hand,
                TabStop = false
            };

            hardwareMessageOverviewPageBar.Paint += (_, e) =>
            {
                bool a220 = DcduStyleManager.IsA220;
                int pageCount = a220 ? a220OverviewPageCount :
                    hardwareMessageOverviewPageCount;
                int pageIndex = a220 ? a220OverviewPageIndex :
                    hardwareMessageOverviewPageIndex;
                if (pageCount <= 1)
                {
                    return;
                }

                string pageText = "< " +
                    (pageIndex + 1).ToString(
                        System.Globalization.CultureInfo.InvariantCulture) +
                    "/" +
                    pageCount.ToString(
                        System.Globalization.CultureInfo.InvariantCulture) +
                    " >";

                // The counter must stay compact independently of the
                // user-selectable message font size (including EXTRA LARGE).
                using Font counterFont = CreateDpiStablePointFont(
                    "Consolas", 9.5f, FontStyle.Bold);
                TextRenderer.DrawText(
                    e.Graphics,
                    pageText,
                    counterFont,
                    hardwareMessageOverviewPageBar.ClientRectangle,
                    a220 ? DcduTheme.Cyan : DcduTheme.Amber,
                    TextFormatFlags.HorizontalCenter |
                    TextFormatFlags.VerticalCenter |
                    TextFormatFlags.SingleLine |
                    TextFormatFlags.NoPrefix |
                    TextFormatFlags.EndEllipsis |
                    TextFormatFlags.NoPadding);
            };

            hardwareMessageOverviewPageBar.MouseDown += (_, e) =>
            {
                if (e.Button != MouseButtons.Left)
                {
                    return;
                }

                int half = hardwareMessageOverviewPageBar.ClientSize.Width / 2;
                if (DcduStyleManager.IsA220)
                    ChangeA220OverviewPage(e.X < half ? -1 : 1);
                else
                    ChangeHardwareMessageOverviewPage(e.X < half ? -1 : 1);
            };

            hardwareMessageOverviewPageBar.MouseWheel += (_, e) =>
            {
                if (DcduStyleManager.IsA220)
                    ChangeA220OverviewPage(e.Delta > 0 ? -1 : 1);
                else if (hardwareMessageOverviewPageCount > 1)
                    ChangeHardwareMessageOverviewPage(e.Delta > 0 ? -1 : 1);
            };

            screenPanel?.Controls.Add(hardwareMessageOverviewPageBar);
        }

        private void UpdateHardwareMessageOverviewPageBar()
        {
            EnsureHardwareMessageOverviewPageBar();

            if (hardwareMessageOverviewPageBar == null ||
                hardwareMessageOverviewPageBar.IsDisposed)
            {
                return;
            }

            CalculateA220OverviewPages();
            bool show =
                (DcduStyleManager.IsA220
                    ? a220OverviewPageCount > 1 &&
                      embeddedSetupPage == EmbeddedSetupPage.None &&
                      airbusAocPage == AirbusAocPage.None &&
                      boeingTelexPage == BoeingTelexPage.None
                    : ShouldUseMessageOverviewLskMode() &&
                      IsHardwareLskMessageOverviewActive() &&
                      hardwareMessageOverviewPageCount > 1) &&
                outputTable.Visible &&
                outputTable.Enabled &&
                (messageFormatPanel == null ||
                 messageFormatPanel.IsDisposed ||
                 !messageFormatPanel.Visible);

            if (!show)
            {
                hardwareMessageOverviewPageBar.Visible = false;
                return;
            }

            if (!ReferenceEquals(
                    hardwareMessageOverviewPageBar.Parent,
                    screenPanel))
            {
                hardwareMessageOverviewPageBar.Parent?.Controls.Remove(
                    hardwareMessageOverviewPageBar);

                screenPanel.Controls.Add(
                    hardwareMessageOverviewPageBar);
            }

            // Keep the counter on the MESSAGES / DATA header, well away from
            // the fixed-position LSK rows (both Boeing and Airbus).
            int indicatorWidth = Math.Min(S(88),
                Math.Max(S(44), screenPanel.ClientSize.Width - S(240)));
            int indicatorX = Math.Max(
                (messageFilterLabel?.Right ?? messageHeaderLabel.Right) + S(8),
                screenPanel.ClientSize.Width - indicatorWidth - S(8));
            indicatorX = Math.Max(0, Math.Min(
                indicatorX,
                screenPanel.ClientSize.Width - indicatorWidth - S(2)));

            hardwareMessageOverviewPageBar.Bounds = new Rectangle(
                indicatorX,
                messageHeaderLabel.Top + S(1),
                indicatorWidth,
                Math.Max(S(20), messageHeaderLabel.Height));

            hardwareMessageOverviewPageBar.Visible = true;
            hardwareMessageOverviewPageBar.BringToFront();

            smartStatusToolTip.SetToolTip(
                hardwareMessageOverviewPageBar,
                "MESSAGES PAGE " +
                (DcduStyleManager.IsA220 ? a220OverviewPageIndex + 1 :
                    hardwareMessageOverviewPageIndex + 1)
                    .ToString(
                        System.Globalization.CultureInfo.InvariantCulture) +
                "/" +
                (DcduStyleManager.IsA220 ? a220OverviewPageCount :
                    hardwareMessageOverviewPageCount)
                    .ToString(
                        System.Globalization.CultureInfo.InvariantCulture) +
                (DcduStyleManager.IsA220 ? " - CLICK TO SCROLL" :
                    " - CLICK TO CHANGE PAGE"));

            hardwareMessageOverviewPageBar.Invalidate();
        }

        private void ChangeHardwareMessageOverviewPage(int delta)
        {
            if (!ShouldUseMessageOverviewLskMode() ||
                delta == 0 ||
                hardwareMessageOverviewPageCount <= 1)
            {
                return;
            }

            int next =
                Math.Max(
                    0,
                    Math.Min(
                        hardwareMessageOverviewPageCount - 1,
                        hardwareMessageOverviewPageIndex + delta));

            if (next == hardwareMessageOverviewPageIndex)
            {
                return;
            }

            hardwareMessageOverviewPageIndex = next;
            ApplyMessageFilter();
        }

        private bool ShouldUseMessageOverviewLskMode()
        {
            return !DcduStyleManager.IsA220 &&
                   MessageOverviewLskModeEnabled;
        }

        private void HideMessageOverviewNavigationChrome()
        {
            if (outputScrollBar != null && !outputScrollBar.IsDisposed)
            {
                outputScrollBar.Visible = false;
                outputScrollBar.SendToBack();
            }

            if (hardwareMessageOverviewPageBar != null &&
                !hardwareMessageOverviewPageBar.IsDisposed)
            {
                hardwareMessageOverviewPageBar.Visible = false;
                hardwareMessageOverviewPageBar.SendToBack();
            }
        }

        private bool IsHardwareLskMessageOverviewActive()
        {
            if (!ShouldUseMessageOverviewLskMode() ||
                dcduFrame == null ||
                dcduFrame.IsDisposed ||
                outputTable == null ||
                outputTable.IsDisposed ||
                !outputTable.Visible ||
                !outputTable.Enabled)
            {
                return false;
            }

            if (messageFormatPanel != null &&
                !messageFormatPanel.IsDisposed &&
                messageFormatPanel.Visible)
            {
                return false;
            }

            return airbusAocPage == AirbusAocPage.None &&
                   boeingTelexPage == BoeingTelexPage.None &&
                   embeddedSetupPage == EmbeddedSetupPage.None;
        }

        private int MessageOverviewFirstRightLskIndex()
        {
            return 3;
        }

        private int MessageOverviewLastRightLskIndex()
        {
            return DcduStyleManager.IsBoeing ? 6 : 5;
        }

        private int MessageOverviewFirstLeftLskIndex()
        {
            return 3;
        }

        private int MessageOverviewLastLeftLskIndex()
        {
            return DcduStyleManager.IsBoeing ? 6 : 5;
        }

        private Rectangle MessageOverviewLeftLskBounds(int index)
        {
            return DcduStyleManager.IsBoeing
                ? BoeingTelexLeftLskBounds(index)
                : AirbusAocLeftLskBounds(index);
        }

        private Rectangle MessageOverviewRightLskBounds(int index)
        {
            return DcduStyleManager.IsBoeing
                ? BoeingTelexRightLskBounds(index)
                : AirbusAocRightLskBounds(index);
        }

        private List<CPDLCMessage> GetVisibleHardwareOverviewMessages()
        {
            if (!IsHardwareLskMessageOverviewActive())
            {
                return new List<CPDLCMessage>();
            }

            // Hardware LSK mapping is logical, not visual: L3/R3 is slot 1,
            // L4/R4 slot 2, L5/R5 slot 3 and Boeing L6/R6 slot 4.
            return GetHardwareMessageOverviewPageList();
        }

        private CPDLCMessage GetHardwareOverviewMessageForRightLsk(
            int index)
        {
            int first = MessageOverviewFirstRightLskIndex();
            int last = MessageOverviewLastRightLskIndex();

            if (index < first || index > last)
            {
                return null;
            }

            List<CPDLCMessage> messages =
                GetVisibleHardwareOverviewMessages();

            int slot = index - first;

            return slot >= 0 && slot < messages.Count
                ? messages[slot]
                : null;
        }

        private CPDLCMessage GetHardwareOverviewMessageForLeftLsk(
            int index)
        {
            int first = MessageOverviewFirstLeftLskIndex();
            int last = MessageOverviewLastLeftLskIndex();

            if (index < first || index > last)
            {
                return null;
            }

            List<CPDLCMessage> messages =
                GetVisibleHardwareOverviewMessages();

            int slot = index - first;

            return slot >= 0 && slot < messages.Count
                ? messages[slot]
                : null;
        }

        private bool TryGetMessageOverviewLineSelect(
            Point location,
            out CPDLCMessage message)
        {
            message = null;

            if (!IsHardwareLskMessageOverviewActive())
            {
                return false;
            }

            for (int index = MessageOverviewFirstLeftLskIndex();
                 index <= MessageOverviewLastLeftLskIndex();
                 index++)
            {
                if (MessageOverviewLeftLskBounds(index)
                        .Contains(location))
                {
                    message =
                        GetHardwareOverviewMessageForLeftLsk(index);

                    return message != null;
                }
            }

            for (int index = MessageOverviewFirstRightLskIndex();
                 index <= MessageOverviewLastRightLskIndex();
                 index++)
            {
                if (MessageOverviewRightLskBounds(index)
                        .Contains(location))
                {
                    message =
                        GetHardwareOverviewMessageForRightLsk(index);

                    return message != null;
                }
            }

            return false;
        }

        private bool IsMessageOverviewLineSelectHit(Point location)
        {
            return TryGetMessageOverviewLineSelect(
                location,
                out _);
        }

        private bool HandleMessageOverviewLineSelectClick(Point location)
        {
            if (!TryGetMessageOverviewLineSelect(
                    location,
                    out CPDLCMessage message))
            {
                return false;
            }

            HideAutoDeleteActionPopup();
            HideManualDeleteConfirmPopup();

            MessageClicked(
                message,
                new KeyEventArgs(Keys.Enter));

            return true;
        }

        private bool IsAirbusAocActive()
        {
            return !DcduStyleManager.IsBoeing && airbusAocPage != AirbusAocPage.None;
        }

        // The left Airbus LSK bank in the current bezel artwork was moved down.
        // Only the physical click targets need the +18 logical px correction.
        // Visible left/right captions share the same row coordinates so paired
        // labels and values remain perfectly level on every Airbus page.
        private const int AirbusLeftLskHitboxVerticalOffset = 18;
        private const int AirbusLeftLskTextVerticalOffset = 0;

        private Rectangle AirbusAocLeftLskBounds(int index)
        {
            // Physical Airbus side-key hitboxes, tuned to the lowered left LSK
            // bank in the current DCDU bezel artwork.
            int[] y = { 46, 88, 130, 172, 214 };
            int i = Math.Max(0, Math.Min(index - 1, y.Length - 1));
            return SR(new Rectangle(
                8,
                y[i] + AirbusLeftLskHitboxVerticalOffset,
                64,
                36));
        }

        private Rectangle AirbusAocRightLskBounds(int index)
        {
            int[] y = { 64, 106, 148, 190, 232 };
            int i = Math.Max(0, Math.Min(index - 1, y.Length - 1));
            return SR(new Rectangle(610, y[i], 66, 36));
        }

        private bool TryGetAirbusAocLineSelect(Point location, out bool rightSide, out int index)
        {
            rightSide = false;
            index = 0;

            if (!IsAirbusAocActive())
            {
                return false;
            }

            for (int i = 1; i <= 5; i++)
            {
                if (AirbusAocLeftLskBounds(i).Contains(location) && IsAirbusAocLineSelectActionAvailable(false, i))
                {
                    index = i;
                    return true;
                }

                if (AirbusAocRightLskBounds(i).Contains(location) && IsAirbusAocLineSelectActionAvailable(true, i))
                {
                    rightSide = true;
                    index = i;
                    return true;
                }
            }

            return false;
        }

        private bool IsAirbusAocLineSelectActionAvailable(bool rightSide, int index)
        {
            switch (airbusAocPage)
            {
                case AirbusAocPage.MainMenu:
                    return (!rightSide && (index == 1 || index == 2 || index == 5)) ||
                           (rightSide && (index == 1 || index == 2));

                case AirbusAocPage.AtcRequestMenu:
                    return !rightSide && (index == 1 || index == 2 || index == 5);

                case AirbusAocPage.AtcMainMenu:
                    return (!rightSide && (index == 1 || index == 2 || index == 3 || index == 5)) ||
                           (rightSide && (index == 1 || index == 2));

                case AirbusAocPage.AtcDirectRequest:
                case AirbusAocPage.AtcLevelRequest:
                case AirbusAocPage.AtcSpeedRequest:
                case AirbusAocPage.AtcWhenCanWeRequest:
                case AirbusAocPage.AtcTextRequest:
                case AirbusAocPage.AtcLogonRequest:
                    return (!rightSide && index == 5) ||
                           (rightSide && index == 5 && airbusAocSendReady);

                case AirbusAocPage.AtcLatRequestMenu:
                case AirbusAocPage.AtcVertRequestMenu:
                case AirbusAocPage.AtcWhenCanWeMenu:
                case AirbusAocPage.AtcOtherRequestMenu:
                case AirbusAocPage.AtcReportsMenu:
                    return (!rightSide && (index == 1 || index == 2 || index == 3 || index == 5)) ||
                           (rightSide && (index == 1 || index == 2));

                case AirbusAocPage.AtcConnectionMenu:
                    return !rightSide && (index == 1 || index == 5);

                case AirbusAocPage.AtcEmergencyMenu:
                    return (!rightSide && (index == 1 || index == 2 || index == 3 || index == 5)) ||
                           (rightSide && index == 1);

                case AirbusAocPage.PreDepClearance:
                case AirbusAocPage.OceanicClearance:
                case AirbusAocPage.WxRequest:
                case AirbusAocPage.AtisRequest:
                case AirbusAocPage.FreeTextRequest:
                    return (!rightSide && index == 5) ||
                           (rightSide && index == 5 && airbusAocSendReady);

                case AirbusAocPage.SendConfirm:
                    return (!rightSide && index == 5) ||
                           (rightSide && index == 5 && airbusAocPendingSendKind != AirbusAocPendingSendKind.None);

                default:
                    return false;
            }
        }

        private bool IsAirbusAocLineSelectHit(Point location)
        {
            return TryGetAirbusAocLineSelect(location, out _, out _);
        }

        private bool HandleAirbusAocLineSelectClick(Point location)
        {
            if (!TryGetAirbusAocLineSelect(location, out bool rightSide, out int index))
            {
                return false;
            }

            HandleAirbusAocLineSelect(rightSide, index);
            return true;
        }

        private void HandleAirbusAocLineSelect(bool rightSide, int index)
        {
            switch (airbusAocPage)
            {
                case AirbusAocPage.MainMenu:
                    if (!rightSide && index == 1)
                    {
                        ShowAirbusAocAtcRequestMenu();
                    }
                    else if (rightSide && index == 1)
                    {
                        ShowAirbusAocWeatherRequest(false);
                    }
                    else if (!rightSide && index == 2)
                    {
                        ShowAirbusAocWeatherRequest(true);
                    }
                    else if (rightSide && index == 2)
                    {
                        ShowAirbusAocFreeTextRequest();
                    }
                    else if (!rightSide && index == 5)
                    {
                        CloseAirbusAocPages();
                    }
                    break;

                case AirbusAocPage.AtcRequestMenu:
                    if (!rightSide && index == 1)
                    {
                        ShowAirbusAocPreDepClearance();
                    }
                    else if (!rightSide && index == 2)
                    {
                        ShowAirbusAocOceanicClearance();
                    }
                    else if (!rightSide && index == 5)
                    {
                        ShowAirbusAocMainMenu();
                    }
                    break;

                case AirbusAocPage.AtcMainMenu:
                    HandleAirbusAtcMainMenuLineSelect(rightSide, index);
                    break;

                case AirbusAocPage.AtcLatRequestMenu:
                    HandleAirbusAtcLatMenuLineSelect(rightSide, index);
                    break;

                case AirbusAocPage.AtcVertRequestMenu:
                    HandleAirbusAtcVertMenuLineSelect(rightSide, index);
                    break;

                case AirbusAocPage.AtcWhenCanWeMenu:
                    HandleAirbusAtcWhenCanWeMenuLineSelect(rightSide, index);
                    break;

                case AirbusAocPage.AtcOtherRequestMenu:
                    HandleAirbusAtcOtherMenuLineSelect(rightSide, index);
                    break;

                case AirbusAocPage.AtcReportsMenu:
                    HandleAirbusAtcReportsMenuLineSelect(rightSide, index);
                    break;

                case AirbusAocPage.AtcConnectionMenu:
                    HandleAirbusAtcConnectionMenuLineSelect(rightSide, index);
                    break;

                case AirbusAocPage.AtcEmergencyMenu:
                    HandleAirbusAtcEmergencyMenuLineSelect(rightSide, index);
                    break;

                case AirbusAocPage.AtcTextRequest:
                    if (!rightSide && index == 5)
                    {
                        ShowAirbusAtcMainMenu();
                    }
                    else if (rightSide && index == 5)
                    {
                        ShowAirbusAtcTextConfirm();
                    }
                    break;

                case AirbusAocPage.AtcLogonRequest:
                    if (!rightSide && index == 5)
                    {
                        ShowAirbusAtcConnectionMenu();
                    }
                    else if (rightSide && index == 5)
                    {
                        _ = SendAirbusAtcLogonRequestAsync();
                    }
                    break;

                case AirbusAocPage.AtcDirectRequest:
                case AirbusAocPage.AtcLevelRequest:
                case AirbusAocPage.AtcSpeedRequest:
                case AirbusAocPage.AtcWhenCanWeRequest:
                    if (!rightSide && index == 5)
                    {
                        ShowAirbusAtcMainMenu();
                    }
                    else if (rightSide && index == 5)
                    {
                        ShowAirbusAtcRequestConfirm();
                    }
                    break;

                case AirbusAocPage.PreDepClearance:
                    if (!rightSide && index == 5)
                    {
                        ShowAirbusAocAtcRequestMenu();
                    }
                    else if (rightSide && index == 5)
                    {
                        ShowAirbusAocPreDepClearanceConfirm();
                    }
                    break;

                case AirbusAocPage.OceanicClearance:
                    if (!rightSide && index == 5)
                    {
                        ShowAirbusAocAtcRequestMenu();
                    }
                    else if (rightSide && index == 5)
                    {
                        ShowAirbusAocOceanicClearanceConfirm();
                    }
                    break;

                case AirbusAocPage.WxRequest:
                    if (!rightSide && index == 5)
                    {
                        ShowAirbusAocMainMenu();
                    }
                    else if (rightSide && index == 5)
                    {
                        ShowAirbusAocWeatherConfirm(false);
                    }
                    break;

                case AirbusAocPage.AtisRequest:
                    if (!rightSide && index == 5)
                    {
                        ShowAirbusAocMainMenu();
                    }
                    else if (rightSide && index == 5)
                    {
                        ShowAirbusAocWeatherConfirm(true);
                    }
                    break;

                case AirbusAocPage.FreeTextRequest:
                    if (!rightSide && index == 5)
                    {
                        ShowAirbusAocMainMenu();
                    }
                    else if (rightSide && index == 5)
                    {
                        ShowAirbusAocFreeTextConfirm();
                    }
                    break;

                case AirbusAocPage.SendConfirm:
                    if (!rightSide && index == 5)
                    {
                        ReturnFromAirbusAocConfirm();
                    }
                    else if (rightSide && index == 5)
                    {
                        _ = SendAirbusAocPendingRequestAsync();
                    }
                    break;
            }
        }


        private bool IsBoeingTelexActive()
        {
            return DcduStyleManager.IsBoeing && boeingTelexPage != BoeingTelexPage.None;
        }

        private Rectangle BoeingTelexLeftLskBounds(int index)
        {
            // Physical Boeing DCDU side-key hitboxes, tuned for DCDU_Main_V15 Boeing asset.
            int[] y = { 66, 107, 149, 190, 232, 273 };
            int i = Math.Max(0, Math.Min(index - 1, y.Length - 1));
            return SR(new Rectangle(4, y[i], 70, 35));
        }

        private Rectangle BoeingTelexRightLskBounds(int index)
        {
            int[] y = { 66, 107, 149, 190, 232, 273 };
            int i = Math.Max(0, Math.Min(index - 1, y.Length - 1));
            return SR(new Rectangle(584, y[i], 70, 35));
        }

        private bool TryGetBoeingTelexLineSelect(Point location, out bool rightSide, out int index)
        {
            rightSide = false;
            index = 0;

            if (!IsBoeingTelexActive())
            {
                return false;
            }

            for (int i = 1; i <= 6; i++)
            {
                if (BoeingTelexLeftLskBounds(i).Contains(location) && IsBoeingTelexLineSelectActionAvailable(false, i))
                {
                    index = i;
                    return true;
                }

                if (BoeingTelexRightLskBounds(i).Contains(location) && IsBoeingTelexLineSelectActionAvailable(true, i))
                {
                    rightSide = true;
                    index = i;
                    return true;
                }
            }

            return false;
        }

        private bool IsBoeingTelexLineSelectHit(Point location)
        {
            return TryGetBoeingTelexLineSelect(location, out _, out _);
        }

        private bool HandleBoeingTelexLineSelectClick(Point location)
        {
            if (!TryGetBoeingTelexLineSelect(location, out bool rightSide, out int index))
            {
                return false;
            }

            HandleBoeingTelexLineSelect(rightSide, index);
            return true;
        }

        private bool IsBoeingTelexLineSelectActionAvailable(bool rightSide, int index)
        {
            switch (boeingTelexPage)
            {
                case BoeingTelexPage.Menu:
                    return !rightSide && (index == 1 || index == 2 || index == 3 || index == 6);

                case BoeingTelexPage.AtcMainMenu:
                    return (!rightSide && (index == 1 || index == 2 || index == 3 || index == 4 || index == 6)) ||
                           (rightSide && (index == 1 || index == 2 || index == 3));

                case BoeingTelexPage.AtcConnectionMenu:
                    return !rightSide && (index == 1 || index == 6);

                case BoeingTelexPage.FreeText:
                case BoeingTelexPage.Metar:
                case BoeingTelexPage.Atis:
                case BoeingTelexPage.AtcPreDepClearance:
                case BoeingTelexPage.AtcOceanicClearance:
                case BoeingTelexPage.AtcDirectRequest:
                case BoeingTelexPage.AtcLevelRequest:
                case BoeingTelexPage.AtcSpeedRequest:
                case BoeingTelexPage.AtcWhenCanWeRequest:
                case BoeingTelexPage.AtcLogonRequest:
                    return (!rightSide && index == 6) ||
                           (rightSide && index == 6 && boeingTelexSendReady);

                case BoeingTelexPage.SendConfirm:
                    return (!rightSide && index == 6) ||
                           (rightSide && index == 6 && boeingTelexPendingSendKind != BoeingTelexPendingSendKind.None);

                default:
                    return false;
            }
        }

        private void HandleBoeingTelexLineSelect(bool rightSide, int index)
        {
            switch (boeingTelexPage)
            {
                case BoeingTelexPage.Menu:
                    if (!rightSide && index == 1)
                    {
                        ShowBoeingTelexFreeText();
                    }
                    else if (!rightSide && index == 2)
                    {
                        ShowBoeingTelexMetarRequest();
                    }
                    else if (!rightSide && index == 3)
                    {
                        ShowBoeingTelexAtisRequest();
                    }
                    else if (!rightSide && index == 6)
                    {
                        CloseBoeingTelexPages();
                    }
                    break;

                case BoeingTelexPage.FreeText:
                    if (!rightSide && index == 6)
                    {
                        ShowBoeingTelexMenu();
                    }
                    else if (rightSide && index == 6)
                    {
                        ShowBoeingTelexFreeTextConfirm();
                    }
                    break;

                case BoeingTelexPage.Metar:
                    if (!rightSide && index == 6)
                    {
                        ShowBoeingTelexMenu();
                    }
                    else if (rightSide && index == 6)
                    {
                        ShowBoeingTelexInfoConfirm(false);
                    }
                    break;

                case BoeingTelexPage.Atis:
                    if (!rightSide && index == 6)
                    {
                        ShowBoeingTelexMenu();
                    }
                    else if (rightSide && index == 6)
                    {
                        ShowBoeingTelexInfoConfirm(true);
                    }
                    break;

                case BoeingTelexPage.AtcMainMenu:
                    if (!rightSide && index == 1)
                    {
                        ShowBoeingAtcDirectRequest();
                    }
                    else if (!rightSide && index == 2)
                    {
                        ShowBoeingAtcLevelRequest();
                    }
                    else if (!rightSide && index == 3)
                    {
                        ShowBoeingAtcPreDepClearance();
                    }
                    else if (rightSide && index == 1)
                    {
                        ShowBoeingAtcWhenCanWeRequest();
                    }
                    else if (rightSide && index == 2)
                    {
                        ShowBoeingAtcSpeedRequest();
                    }
                    else if (rightSide && index == 3)
                    {
                        ShowBoeingAtcOceanicClearance();
                    }
                    else if (!rightSide && index == 4)
                    {
                        ShowBoeingAtcConnectionMenu();
                    }
                    else if (!rightSide && index == 6)
                    {
                        CloseBoeingTelexPages();
                    }
                    break;

                case BoeingTelexPage.AtcConnectionMenu:
                    if (!rightSide && index == 1)
                    {
                        if (!string.IsNullOrWhiteSpace(CurrentATCUnit))
                        {
                            _ = ExecuteCpdlcLogoffFromEmbeddedMenuAsync();
                        }
                        else
                        {
                            ShowBoeingAtcLogonRequest();
                        }
                    }
                    else if (!rightSide && index == 6)
                    {
                        ShowBoeingAtcMainMenu();
                    }
                    break;

                case BoeingTelexPage.AtcLogonRequest:
                    if (!rightSide && index == 6)
                    {
                        ShowBoeingAtcConnectionMenu();
                    }
                    else if (rightSide && index == 6)
                    {
                        _ = SendBoeingAtcLogonRequestAsync();
                    }
                    break;

                case BoeingTelexPage.AtcPreDepClearance:
                    if (!rightSide && index == 6)
                    {
                        ShowBoeingAtcMainMenu();
                    }
                    else if (rightSide && index == 6)
                    {
                        ShowBoeingAtcPreDepClearanceSend();
                    }
                    break;

                case BoeingTelexPage.AtcOceanicClearance:
                    if (!rightSide && index == 6)
                    {
                        ShowBoeingAtcMainMenu();
                    }
                    else if (rightSide && index == 6)
                    {
                        ShowBoeingAtcOceanicClearanceSend();
                    }
                    break;

                case BoeingTelexPage.AtcDirectRequest:
                case BoeingTelexPage.AtcLevelRequest:
                case BoeingTelexPage.AtcSpeedRequest:
                case BoeingTelexPage.AtcWhenCanWeRequest:
                    if (!rightSide && index == 6)
                    {
                        ShowBoeingAtcMainMenu();
                    }
                    else if (rightSide && index == 6)
                    {
                        ShowBoeingAtcRequestSend();
                    }
                    break;

                case BoeingTelexPage.SendConfirm:
                    if (!rightSide && index == 6)
                    {
                        ReturnFromBoeingTelexConfirm();
                    }
                    else if (rightSide && index == 6)
                    {
                        _ = SendBoeingTelexPendingRequestAsync();
                    }
                    break;
            }
        }

        private void PrepareBoeingTelexPage(BoeingTelexPage page)
        {
            if (!DcduStyleManager.IsBoeing)
            {
                return;
            }

            embeddedSetupPage = EmbeddedSetupPage.None;
            boeingTelexPage = page;
            boeingTelexInputs.Clear();
            boeingTelexSendLabel = null;
            boeingTelexSendReady = false;

            HideQuickWxPopup();
            HideClearanceTimelinePopup();
            HideAtisAvailabilityPopup();
            HideAtisAutoPopup();
            HideQuickActionButtons();
            HideCpdlcLogonPopup();
            HidePdcQuickActionButton();
            HideMessageOverviewNavigationChrome();

            SetAirbusAocChromeVisible(false);
            if (DcduStyleManager.IsA220)
            {
                SetA220MainGuideLinesVisible(false);
            }

            messageFormatPanel.SuspendLayout();
            messageFormatPanel.Controls.Clear();
            messageFormatPanel.Visible = true;
            messageFormatPanel.Enabled = true;
            messageFormatPanel.BringToFront();

            if (DcduStyleManager.IsA220)
            {
                messageFormatPanel.Location = Point.Empty;
                messageFormatPanel.Size = screenPanel.ClientSize;
                messageFormatPanel.BackColor = Color.Black;
                ApplyA220BlackGradient(messageFormatPanel);
            }
            else
            {
                messageFormatPanel.Location = SP(new Point(12, 10));
                messageFormatPanel.Size = new Size(
                    Math.Max(1, screenPanel.Width - S(24)),
                    Math.Max(1, screenPanel.Height - S(20)));
                messageFormatPanel.BackColor = Color.Transparent;
            }

            messageFormatPanel.Padding = SPad(new Padding(0));
            messageFormatPanel.Margin = SPad(new Padding(0));
            messageFormatPanel.AutoScroll = false;
            messageFormatPanel.FlowDirection = FlowDirection.LeftToRight;
            messageFormatPanel.WrapContents = false;
            messageFormatPanel.ResumeLayout(false);
        }

        private Panel CreateBoeingTelexCanvas()
        {
            Panel canvas = new()
            {
                BackColor = DcduStyleManager.IsA220
                    ? Color.Black
                    : Color.Transparent,
                Margin = new Padding(0),
                Padding = new Padding(0),
                Size = messageFormatPanel.ClientSize,
                Tag = DcduStyleManager.IsA220 ? A220PhysicalLayoutTag : null
            };
            messageFormatPanel.Controls.Add(canvas);
            canvas.BringToFront();
            return canvas;
        }

