        }

        private static bool TryGetProtocolCommand(out string command)
        {
            command = string.Empty;

            try
            {
                string[] args = Environment.GetCommandLineArgs();

                foreach (string arg in args)
                {
                    if (string.IsNullOrWhiteSpace(arg))
                    {
                        continue;
                    }

                    string trimmed = arg.Trim().Trim('"');

                    if (!trimmed.StartsWith(EasyCpdlcUriScheme + "://", StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    command = trimmed.Contains("toggle", StringComparison.OrdinalIgnoreCase)
                        ? "TOGGLE"
                        : "SHOW";
                    return true;
                }
            }
            catch
            {
                // If args cannot be parsed, just continue normal startup.
            }

            return false;
        }

        private static bool TryForwardProtocolLaunchToExistingInstance()
        {
            if (!TryGetProtocolCommand(out string command))
            {
                return false;
            }

            try
            {
                using System.IO.Pipes.NamedPipeClientStream client = new(".", EasyCpdlcProtocolPipeName, System.IO.Pipes.PipeDirection.Out);
                client.Connect(850);

                using StreamWriter writer = new(client)
                {
                    AutoFlush = true
                };

                writer.WriteLine(command);
                return true;
            }
            catch
            {
                // No running EasyCPDLC instance is listening yet.
                // In that case this protocol launch becomes the normal app launch.
                return false;
            }
        }

        private void RegisterEasyCpdlcUriProtocol()
        {
            try
            {
                string exePath = System.Windows.Forms.Application.ExecutablePath;
                string command = "\"" + exePath + "\" \"%1\"";

                using Microsoft.Win32.RegistryKey schemeKey = Microsoft.Win32.Registry.CurrentUser.CreateSubKey(@"Software\Classes\" + EasyCpdlcUriScheme);
                schemeKey.SetValue(string.Empty, "URL:EasyCPDLC");
                schemeKey.SetValue("URL Protocol", string.Empty);

                using Microsoft.Win32.RegistryKey iconKey = schemeKey.CreateSubKey("DefaultIcon");
                iconKey.SetValue(string.Empty, "\"" + exePath + "\",0");

                using Microsoft.Win32.RegistryKey commandKey = schemeKey.CreateSubKey(@"shell\open\command");
                commandKey.SetValue(string.Empty, command);

                Logger.Info("Registered EasyCPDLC URI protocol: " + EasyCpdlcUriScheme + "://show");
            }
            catch (Exception ex)
            {
                Logger.Warn(ex, "Could not register EasyCPDLC URI protocol");
            }
        }

        private void StartProtocolCommandListener()
        {
            try
            {
                protocolPipeCancellationTokenSource?.Cancel();
                protocolPipeCancellationTokenSource = new CancellationTokenSource();
                CancellationToken token = protocolPipeCancellationTokenSource.Token;

                _ = Task.Run(async () =>
                {
                    while (!token.IsCancellationRequested)
                    {
                        try
                        {
                            using System.IO.Pipes.NamedPipeServerStream server = new(
                                EasyCpdlcProtocolPipeName,
                                System.IO.Pipes.PipeDirection.In,
                                1,
                                System.IO.Pipes.PipeTransmissionMode.Message,
                                System.IO.Pipes.PipeOptions.Asynchronous);

                            await server.WaitForConnectionAsync(token).ConfigureAwait(false);

                            using StreamReader reader = new(server);
                            string command = (await reader.ReadLineAsync().ConfigureAwait(false) ?? "SHOW").Trim();
                            if (command.Length > 16)
                            {
                                command = string.Empty;
                            }

                            SafeUi(() => HandleProtocolCommand(command));
                        }
                        catch (OperationCanceledException)
                        {
                            break;
                        }
                        catch (Exception ex)
                        {
                            Logger.Warn(ex, "EasyCPDLC protocol listener error");
                            await Task.Delay(500, token).ConfigureAwait(false);
                        }
                    }
                }, token);
            }
            catch (Exception ex)
            {
                Logger.Warn(ex, "Could not start EasyCPDLC protocol listener");
            }
        }

        private void HandleProtocolCommand(string command)
        {
            string normalizedCommand = (command ?? string.Empty).Trim().ToUpperInvariant();
            if (normalizedCommand != "SHOW" && normalizedCommand != "TOGGLE")
            {
                Logger.Debug("Ignored invalid EasyCPDLC protocol command.");
                return;
            }

            DateTime nowUtc = DateTime.UtcNow;
            if ((nowUtc - lastProtocolCommandUtc) < TimeSpan.FromMilliseconds(300))
            {
                return;
            }

            lastProtocolCommandUtc = nowUtc;

            if (string.Equals(normalizedCommand, "TOGGLE", StringComparison.OrdinalIgnoreCase))
            {
                if (Visible && WindowState != FormWindowState.Minimized && ContainsFocus)
                {
                    Hide();
                    return;
                }
            }

            BringEasyCpdlcWindowToFront();
        }

        public void BringEasyCpdlcWindowToFront()
        {
            try
            {
                if (IsDisposed || Disposing)
                {
                    return;
                }

                if (InvokeRequired)
                {
                    BeginInvoke(new Action(BringEasyCpdlcWindowToFront));
                    return;
                }

                if (!Visible)
                {
                    Show();
                }

                if (WindowState == FormWindowState.Minimized || IsIconic(Handle))
                {
                    ShowWindow(Handle, SW_RESTORE);
                    WindowState = FormWindowState.Normal;
                }

                bool targetTopMost = true;
                TopMost = true;
                BringToFront();

                // Intentionally do not call Activate() or SetForegroundWindow() here.
                // In MSFS fullscreen those calls can make Windows show the taskbar.
                // WS_EX_NOACTIVATE keeps EasyCPDLC clickable without stealing focus from MSFS.

                System.Windows.Forms.Timer restoreTimer = new()
                {
                    Interval = 700
                };

                restoreTimer.Tick += (_, __) =>
                {
                    restoreTimer.Stop();
                    restoreTimer.Dispose();
                    TopMost = targetTopMost;
                };

                restoreTimer.Start();
            }
            catch (Exception ex)
            {
                Logger.Warn(ex, "Could not bring EasyCPDLC window to front");
            }
        }

        private void MainForm_Load(object sender, EventArgs e)
        {
            outputTable.BorderStyle = BorderStyle.None;
            outputTable.BackColor = Color.Transparent;
            messageFormatPanel.BackColor = Color.Transparent;
            outputTable.HorizontalScroll.Maximum = 0;
            outputTable.AutoScroll = false;
            outputTable.VerticalScroll.Visible = false;
            outputTable.AutoScroll = true;
            ConfigureTransparentScrollDoubleBuffer();
            outputTable.Scroll += (scrollSender, scrollArgs) =>
            {
                // WinForms' built-in scroll range may still include unused
                // TableLayoutPanel row space. Restrict actual user scrolling
                // to the last visible message, but NEVER intervene during
                // startup or the deferred layout/scroll measurement.
                if (standardOverviewExtentValid &&
                    !stabilizingStandardOverviewScroll &&
                    !ShouldUseMessageOverviewLskMode() &&
                    scrollArgs.ScrollOrientation ==
                        ScrollOrientation.VerticalScroll)
                {
                    scrollArgs.NewValue = Math.Max(0, Math.Min(
                        scrollArgs.NewValue, standardOverviewMaximumOffset));
                }
                HideNativeOutputScrollbars();
                RefreshOutputScrollSurfaceOnly();
            };
            outputTable.ControlAdded += (controlSender, controlArgs) =>
            {
                if (rebuildingOverviewRows) return;
                if (controlArgs.Control != null)
                {
                    controlArgs.Control.MouseWheel -= HardwareMessageOverview_MouseWheel;
                    controlArgs.Control.MouseWheel += HardwareMessageOverview_MouseWheel;
                }
                HideNativeOutputScrollbars();
                RefreshOutputScrollSurfaceOnly();
            };
            foreach (Control control in outputTable.Controls)
            {
                control.MouseWheel -= HardwareMessageOverview_MouseWheel;
                control.MouseWheel += HardwareMessageOverview_MouseWheel;
            }
            outputTable.ControlRemoved += (controlSender, controlArgs) => { if (!rebuildingOverviewRows) { HideNativeOutputScrollbars(); RefreshOutputScrollSurfaceOnly(); } };
            outputTable.SizeChanged += (sizeSender, sizeArgs) => { HideNativeOutputScrollbars(); RefreshOutputScrollSurfaceOnly(); };
            outputTable.Layout += (layoutSender, layoutArgs) => { if (!rebuildingOverviewRows) { HideNativeOutputScrollbars(); RefreshOutputScrollSurfaceOnly(); } };
            outputTable.MouseWheel += HardwareMessageOverview_MouseWheel;

            hardwareMessageOverviewBlinkTimer.Interval = 480;
            hardwareMessageOverviewBlinkTimer.Tick +=
                HardwareMessageOverviewBlinkTimer_Tick;

            HideNativeOutputScrollbars();

            CheckNewVersion();
            //CheckAdministrator();
            InitialisePopupMenu();
            ShowSetupForm();
            Setup();

            RegisterEasyCpdlcUriProtocol();
            StartProtocolCommandListener();
            EnsureTrayIconVisible();

            if (Properties.Settings.Default.MainWindowLocation != new Point(0, 0))
            {
                Location = Properties.Settings.Default.MainWindowLocation;
            }

            ApplyMainWindowBounds(DcduStyleManager.IsBoeing);
            ApplyMainScreenLayout(DcduStyleManager.IsBoeing);
            ApplyMainButtonLayout(DcduStyleManager.IsBoeing);
            ConfigureSmartWidgets();
            ApplyMessageFilter();
            ApplyAutoDeleteToExistingEligibleMessages();

            UpdateOnlineStatusLabel();
            _ = EnsureFirBoundariesLoadedAsync(false);
            EnsureTrayIconVisible();
            BeginInvoke(new Action(BringEasyCpdlcWindowToFront));

            Logger.Info("Setup completed successfully");
        }


        private void RefreshMainDisplaySurface()
        {
            try
            {
                dcduFrame?.Invalidate();
                screenPanel?.Invalidate();
                outputTable?.Invalidate();
                messageFormatPanel?.Invalidate();
            }
            catch
            {
                // Cosmetic repaint only.
            }
        }

        private void RefreshOutputScrollSurfaceOnly()
        {
            try
            {
                // Do not invalidate the whole DCDU frame/screen while scrolling.
                // With transparent WinForms controls over MSFS/fullscreen this can reveal
                // the window behind for a frame. Only repaint the moving message layer.
                outputTable?.Invalidate();
                outputScrollBar?.Invalidate();
            }
            catch
            {
                // Cosmetic repaint only.
            }
        }

        private void ConfigureTransparentScrollDoubleBuffer()
        {
            try
            {
                outputTable?.GetType()
                    .GetProperty("DoubleBuffered", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?.SetValue(outputTable, true, null);

                messageFormatPanel?.GetType()
                    .GetProperty("DoubleBuffered", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?.SetValue(messageFormatPanel, true, null);

                screenPanel?.GetType()
                    .GetProperty("DoubleBuffered", BindingFlags.Instance | BindingFlags.NonPublic)
                    ?.SetValue(screenPanel, true, null);
            }
            catch
            {
                // Cosmetic only.
            }
        }

        private void HideNativeOutputScrollbars()
        {
            if (outputTable == null || outputTable.IsDisposed ||
                updatingOutputScrollbarVisibility || rebuildingOverviewRows ||
                stabilizingStandardOverviewScroll)
            {
                return;
            }

            updatingOutputScrollbarVisibility = true;
            try
            {
                HideNativeOutputScrollbarsCore();
            }
            finally
            {
                updatingOutputScrollbarVisibility = false;
            }
        }

        private void HideNativeOutputScrollbarsCore()
        {
            try
            {
                if (outputTable.IsHandleCreated)
                {
                    ShowScrollBar(outputTable.Handle, ScrollBarBoth, false);
                }
            }
            catch
            {
                // Cosmetic only: keep message handling safe if Win32 rejects the call.
            }

            if (outputScrollBar != null && !outputScrollBar.IsDisposed)
            {
                if (ShouldUseMessageOverviewLskMode() ||
                    embeddedSetupPage != EmbeddedSetupPage.None ||
                    airbusAocPage != AirbusAocPage.None ||
                    boeingTelexPage != BoeingTelexPage.None ||
                    (messageFormatPanel != null && messageFormatPanel.Visible))
                {
                    // Only the main standard overview may have the scrollbar.
                    // Airbus/Boeing LSK overview mode uses logical 3-message
                    // pages instead of a continuously scrolling list.
                    outputScrollBar.Visible = false;
                    UpdateHardwareMessageOverviewPageBar();
                }
                else
                {
                    bool mainOverviewVisible =
                        embeddedSetupPage == EmbeddedSetupPage.None &&
                        airbusAocPage == AirbusAocPage.None &&
                        boeingTelexPage == BoeingTelexPage.None &&
                        outputTable.Visible &&
                        outputTable.Enabled &&
                        (messageFormatPanel == null ||
                         messageFormatPanel.IsDisposed ||
                         !messageFormatPanel.Visible);

                    // A cached WinForms DisplayRectangle can exceed the
                    // visible messages by a whole blank page. The scrollbar
                    // is driven by the measured last visible message only.
                    bool hasScrollableContent = mainOverviewVisible &&
                        standardOverviewExtentValid &&
                        standardOverviewMaximumOffset > 0;

                    if (DcduStyleManager.IsA220)
                    {
                        CalculateA220OverviewPages();
                    }
                    outputScrollBar.Visible = hasScrollableContent;

                    // The A220 uses standard scrolling and gets a page
                    // indicator as well, without introducing any LSK mode.
                    UpdateHardwareMessageOverviewPageBar();

                    if (hasScrollableContent)
                    {
                        outputScrollBar.BringToFront();
                        outputScrollBar.Invalidate();
                    }
                }
            }
        }


private const string UpdateGithubOwner = "fresH229a";
private const string UpdateGithubRepo = "EasyCPDLC-Modernized";
private const string UpdateGithubApiAccept = "application/vnd.github+json";
private const string UpdateGithubApiVersion = "2022-11-28";
private const string IntegratedUpdaterFileName = "EasyCPDLC.Updater.exe";
private const string UpdateTemporaryDirectoryPrefix = "EasyCPDLC_Update_";
private static readonly Version MinimumSupportedRollbackVersion = new Version(1, 0, 0, 12);

private static void ClearPendingLogonUpdateState()
{
    pendingLogonUpdateRelease = null;
    pendingLogonUpdateAsset = null;
    pendingLogonUpdateTag = string.Empty;
    logonUpdateAvailable = false;
    logonUpdateBlinkVisible = true;
}

private static void SetPendingLogonUpdateState(Release latest, ReleaseAsset asset)
{
    pendingLogonUpdateRelease = latest;
    pendingLogonUpdateAsset = asset;
    pendingLogonUpdateTag = latest?.TagName ?? string.Empty;
    logonUpdateAvailable = latest != null;
    logonUpdateBlinkVisible = true;
}

private static async void CheckNewVersion()
{
    try
    {
        var client = new GitHubClient(new ProductHeaderValue("EasyCPDLC"));
        var releases = await client.Repository.Release.GetAll(UpdateGithubOwner, UpdateGithubRepo);

        var latest = releases
            .Where(release => !release.Prerelease && !release.Draft)
            .OrderByDescending(release => release.PublishedAt ?? release.CreatedAt)
            .FirstOrDefault();

        if (latest == null)
        {
            ClearPendingLogonUpdateState();
            return;
        }

        Version latestVersion = ParseReleaseVersion(latest.TagName);
        Version currentVersion = ParseReleaseVersion(System.Windows.Forms.Application.ProductVersion);

        if (latestVersion == null || currentVersion == null || latestVersion <= currentVersion)
        {
            ClearPendingLogonUpdateState();
            return;
        }

        ReleaseAsset zipAsset = FindUpdateZipAsset(latest);
        SetPendingLogonUpdateState(latest, zipAsset);
        Logger.Info("Update available: " + latest.TagName);
    }
    catch (Exception ex)
    {
        Logger.Debug("Update check failed: " + ex.Message);
    }
}

private async Task HandlePendingLogonUpdateClickAsync()
{
    try
    {
        if (!logonUpdateAvailable || pendingLogonUpdateRelease == null)
        {
            return;
        }

        Release latest = pendingLogonUpdateRelease;
        ReleaseAsset zipAsset = pendingLogonUpdateAsset;

        if (!ShowGithubReleaseChangelogDialog(latest, zipAsset != null))
        {
            return;
        }

        if (zipAsset == null)
        {
            System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(latest.HtmlUrl) { UseShellExecute = true });
            return;
        }

        await DownloadAndInstallUpdateAsync(latest, zipAsset);
    }
    catch (Exception ex)
    {
        Logger.Debug("Update click handling failed: " + ex.Message);
    }
}


