        public CPDLCMessage WriteMessage(string _response, string _type, string _recipient, bool _outbound = false, CPDLCResponse _header = null)
        {
            RecordUiDiagnosticActivity(
                "Write message [" +
                ((_type ?? "UNKNOWN").Trim().ToUpperInvariant()) +
                "]");

            if (_outbound && string.Equals(_type, "ATIS", StringComparison.OrdinalIgnoreCase))
            {
                RememberAtisRequestTarget(_recipient);
            }

            if (_outbound && string.Equals(_type, "METAR", StringComparison.OrdinalIgnoreCase))
            {
                RememberMetarRequestTarget(_recipient);
            }

            if (TryCaptureSilentAtisHoverResponse(_response, _type, _recipient, _outbound))
            {
                return null;
            }

            if (ShouldSuppressUnchangedAutoAtisResponse(_response, _type, _recipient, _outbound))
            {
                return null;
            }

            TrackClearanceStatus(_response, _type, _outbound);

            CPDLCMessage message;
            if (_outbound)
            {
                message = CreateCPDLCMessage(_response, _type, _recipient, _outbound, _header);
            }
            else
            {
                message = CreateCPDLCMessage(_response, _type, _recipient, _outbound, _header);
                if (PlaySound && ShouldPlayInboundMessageSound(_type, _recipient))
                {
                    PlayInboundMessageSound();
                }
            }

            TrackAutoAtisLetterFromMessage(message);

            if (_outbound &&
                string.Equals(_type, "CPDLC", StringComparison.OrdinalIgnoreCase))
            {
                if (IsCpdlcSentReplyOverviewText(message.message))
                {
                    message.ForeColor = DcduTheme.Green;
                }
                else if (IsCpdlcSendingReplyOverviewText(message.message))
                {
                    message.ForeColor = DcduTheme.Amber;
                }
                else if (IsCpdlcFailedReplyOverviewText(message.message))
                {
                    message.ForeColor = CallsignMismatchAlarmColor();
                }
            }

            Logger.Debug("Writing message: " + _response);

            TimerLabel menuLabel = CreateTimerLabel(">>", true);
            if (ShouldUseDeleteOnlyOverviewAction(message))
            {
                ConfigureDeleteOnlyMessageIndicator(menuLabel);
                menuLabel.CanFlash = false;
            }
            else if (ShouldShowOverviewActionPopup(message))
            {
                menuLabel.CanFlash = CanDirectWilcoFromOverview(message) || CanDirectRogerFromOverview(message);
            }

            if (IsCpdlcStationDetectedText(_response))
            {
                menuLabel.Tag = null;
                menuLabel.Text = UnreadMessageMarkerText;
                menuLabel.CanFlash = true;
                menuLabel.ForeColor = DcduTheme.Amber;
            }
            else if (IsCallsignMismatchAlarmText(_response))
            {
                menuLabel.Tag = null;
                menuLabel.Text = UnreadMessageMarkerText;
                menuLabel.CanFlash = true;
                menuLabel.ForeColor = CallsignMismatchAlarmColor();
            }
            else if (ShouldFlashForReply(message))
            {
                menuLabel.CanFlash = true;
            }
            menuLabel.MouseClick += (sender, e) =>
            {
                if (sender is not TimerLabel clickedMenuLabel)
                {
                    return;
                }

                if (IsVatsimRetryCooldownMessageText(message.message))
                {
                    return;
                }

                bool cancelledAutoDelete =
                    StopAutoDeleteRequestMessage(message, true);

                if (cancelledAutoDelete)
                {
                    ShowAutoDeleteActionPopup(message, clickedMenuLabel);
                    return;
                }

                if (IsOpenMessageDeleteActionHit(clickedMenuLabel, e.Location))
                {
                    ShowManualDeleteConfirmPopup(message, clickedMenuLabel);
                    return;
                }

                if (ShouldUseDeleteOnlyOverviewAction(message))
                {
                    return;
                }

                if (ShouldShowOverviewActionPopup(message))
                {
                    ShowAutoDeleteActionPopup(message, clickedMenuLabel);
                    return;
                }

                HideManualDeleteConfirmPopup();
                MessageClicked(sender, e);
            };
            message.KeyDown += MessageClicked;
            message.MouseClick += (_, e) =>
            {
                if (e.Button != MouseButtons.Left)
                {
                    return;
                }

                if (!DcduStyleManager.IsA220 &&
                    ShouldUseMessageOverviewLskMode())
                {
                    return;
                }

                HideAutoDeleteActionPopup();
                HideManualDeleteConfirmPopup();

                MessageClicked(
                    message,
                    new KeyEventArgs(Keys.Enter));
            };

            SafeUi(() =>
            {
                if (outputTable == null || outputTable.IsDisposed)
                {
                    return;
                }

                // Rebuild the complete three-cell row as a unit instead of
                // inserting cells into an occupied TableLayoutPanel row.
                Control timestamp = CreateOverviewTimeLabel(
                    DateTime.Now.ToString("HH:mm"), message);
                overviewMessageOrder.Remove(message);
                overviewMessageOrder.Insert(0, message);
                overviewMessageRowParts[message] = (timestamp, menuLabel);
                // Attach the new triple in an unused row before normalization.
                // Parent == outputTable is also required by the existing reply
                // and delete handlers while a new message is being inserted.
                int appendRow = outputTable.RowCount;
                outputTable.RowCount = appendRow + 1;
                outputTable.Controls.Add(timestamp, 0, appendRow);
                outputTable.Controls.Add(message, 1, appendRow);
                outputTable.Controls.Add(menuLabel, 2, appendRow);
                overviewRowsNeedRebuild = true;
                MarkMessageUnread(message, menuLabel);
                StartAutoDeleteRequestMessageIfNeeded(message, menuLabel);
                ResetHardwareMessageOverviewPage();
                ApplyMessageFilter();
                if (message.Visible && !ShouldUseMessageOverviewLskMode() &&
                    outputTable.AutoScroll)
                {
                    // New messages are at row zero. ScrollControlIntoView
                    // additionally scrolls HORIZONTALLY to a long label and
                    // breaks the alignment of time and action columns.
                    outputTable.AutoScrollPosition = Point.Empty;
                }
                HideNativeOutputScrollbars();
            });

            return message;
        }

        public async void ArtificialDelay(string _message, string _type, string _sender, int _minDelay = 5, int _maxDelay = 15)
        {
            await Task.Delay(random.Next(_minDelay, _maxDelay) * 1000);
            await SendCPDLCMessage(_sender, _type, _message, false);
            return;
        }

        private bool ConfirmMainClose()
        {
            DialogResult result = MessageBox.Show(
                this,
                "ARE YOU SURE YOU WANT TO CLOSE EASYCPDLC?",
                "ARE YOU SURE?",
                MessageBoxButtons.YesNo,
                MessageBoxIcon.Warning,
                MessageBoxDefaultButton.Button2);

            return result == DialogResult.Yes;
        }

        private void ExitButton_Click(object sender, EventArgs e)
        {
            if (!ConfirmMainClose())
            {
                return;
            }

            try
            {
                unreadReminderTimer?.Stop();
                hardwareMessageOverviewBlinkTimer?.Stop();
                vatsimOnlineTimer?.Stop();
                uiThreadWatchdogTimer?.Stop();
                uiThreadBackgroundWatchdogTimer?.Dispose();
                uiThreadBackgroundWatchdogTimer = null;
                StopAllAutoDeleteRequestTimers();
                StopAllVatsimRetryHourglassAnimations();
                CancelPdcStationOfflineWatch();
                requestCancellationTokenSource?.Cancel();
            }
            catch (NullReferenceException) { }
            this.Close();

            LogManager.Shutdown();
            FSUIPCData.CloseConnection();
            System.Windows.Forms.Application.Exit();
        }
