        private async void RetrieveButton_Click(object sender, EventArgs e)
        {
            RecordUiDiagnosticActivity(
                Connected ? "Disconnect requested" : "Connect requested");

            string response = "";

            if (DebugUiPreviewMode)
            {
                InitialiseDebugUiPreviewMode();
                WriteMessage("UI PREVIEW: CONNECT/DISCONNECT IS DISABLED. BUTTONS STAY UNLOCKED AND NO NETWORK LOGON IS SENT.", "SYSTEM", "SYSTEM");
                return;
            }

            if (connectionAttemptInProgress)
            {
                return;
            }

            if (!Connected && DateTime.UtcNow < nextConnectionAttemptUtc)
            {
                WriteMessage(
                    "VATSIM: RETRY PAUSED. WAIT " +
                    RemainingConnectionRetrySeconds().ToString(
                        System.Globalization.CultureInfo.InvariantCulture) +
                    " SECONDS.",
                    "SYSTEM",
                    "SYSTEM");
                return;
            }

            if (!Connected && IsVatsimRequestBackoffActive(out TimeSpan vatsimBackoffRemaining))
            {
                int waitSeconds = Math.Max(
                    1,
                    (int)Math.Ceiling(vatsimBackoffRemaining.TotalSeconds));
                WriteMessage(
                    "VATSIM: SERVICE RETRY PAUSED. WAIT " +
                    waitSeconds.ToString(System.Globalization.CultureInfo.InvariantCulture) +
                    " SECONDS.",
                    "SYSTEM",
                    "SYSTEM");
                return;
            }

            connectionAttemptInProgress = true;
            UpdateConnectionGatedControls();

            try
            {
                if (!Connected)
                {

                    try
                {
                    using (HttpClient wc = CreateShortTimeoutHttpClient())
                    {
                        RecordUiDiagnosticActivity("Initial VATSIM pilot lookup");
                        Stopwatch initialVatsimStopwatch = Stopwatch.StartNew();

                        string vatsimJson = await wc.GetStringAsync(
                            "https://data.vatsim.net/v3/vatsim-data.json");

                        LogAsyncOperationDuration(
                            "Initial VATSIM pilot lookup",
                            initialVatsimStopwatch);
                        vatsimData = JsonConvert.DeserializeObject<VATSIMRootobject>(vatsimJson);

                        if (vatsimData == null)
                        {
                            throw new JsonException("VATSIM returned an empty data document.");
                        }

                        ResetVatsimRequestBackoff();
                        Logger.Debug("VATSIM Data Retrieved and Parsed");
                    }

                    userVATSIMData = vatsimData.pilots?.FirstOrDefault(i => i.cid == cid);
                    if (userVATSIMData is null)
                    {
                        response += "VATSIM: PILOT NOT FOUND. WAIT 30 SECONDS AND RETRY.\n";
                        atcButton.Enabled = false;
                        telexButton.Enabled = false;
                        Connected = false;
                        StartConnectionRetryCooldown("pilot not found");
                        CPDLCMessage pilotRetryMessage =
                            WriteMessage(response, "SYSTEM", "SYSTEM");
                        StartVatsimRetryHourglassAnimation(
                            pilotRetryMessage,
                            response);
                        return;
                    }

                    callsign = userVATSIMData.callsign;
                    EnsureFlightPhaseSignature(userVATSIMData);
                    UpdateCallsignDisplay();
                    if (userVATSIMData.flight_plan is null)
                    {
                        response += "VATSIM: NO FLIGHT PLAN FILED. FILE A FLIGHT PLAN AND RETRY.\n";
                        atcButton.Enabled = false;
                        telexButton.Enabled = false;
                        Connected = false;
                        StartConnectionRetryCooldown("no flight plan filed");
                        WriteMessage(response, "SYSTEM", "SYSTEM");
                        return;
                    }

                    Connected = true;
                    loadedFlightPlanSignature = BuildFlightPlanSignature(userVATSIMData);
                    nextFlightPlanDetected = false;
                    nextFlightPlanIgnored = false;
                    nextFlightPlanSignature = string.Empty;
                    nextFlightPlanDisplayText = string.Empty;
                    lastNextFlightPlanCheckUtc = DateTime.MinValue;
                    lastVatsimPilotPhaseRefreshUtc = DateTime.MinValue;
                    activeVatsimCallsign = userVATSIMData?.callsign?.Trim().ToUpperInvariant() ?? string.Empty;
                    pendingHoppieCallsign = string.Empty;
                    preserveLoadedFlightPlanOnLiveUpdate = false;
                    vatsimCallsignMismatchWarningActive = false;
                    lastVatsimCallsignMismatchWarningUtc = DateTime.MinValue;
                    HideNextFlightPlanPrompt();
                    UpdateFlightPhaseBadge();

                    ClearConnectionRetryCooldown();

                    requestCancellationTokenSource = new CancellationTokenSource();
                    requestCancellationToken = requestCancellationTokenSource.Token;
                    _ = PeriodicCheckMessage(updateTimer, requestCancellationToken);

                    // Initialise Hoppie, ATC-online and VHF1 data immediately after
                    // the connection succeeds. This reuses the vatsim-data.json
                    // document already downloaded above and therefore adds no
                    // duplicate main-feed request.
                    await PrimeCpdlcDiscoveryAfterConnectionAsync();

                }
                catch (Exception ex)
                {
                    RegisterVatsimRequestFailure(ex, "initial connection check");
                    response += "VATSIM: ERROR. WAIT 30 SECONDS AND RETRY.\n";
                    atcButton.Enabled = false;
                    telexButton.Enabled = false;
                    Connected = false;
                    StartConnectionRetryCooldown("connection check failed");
                    Logger.Debug("VATSIM initial connection check failed: " + ex.Message);
                    CPDLCMessage connectionRetryMessage =
                        WriteMessage(response, "SYSTEM", "SYSTEM");
                    StartVatsimRetryHourglassAnimation(
                        connectionRetryMessage,
                        response);
                    return;
                }

                response += "LOGON SUCCESSFUL.";

                if (string.IsNullOrWhiteSpace(SimbriefID))
                {
                    response += " SIMBRIEF SKIPPED: NO PILOT ID,";
                }
                else
                {
                    try
                    {
                        Navlog latestSimbriefNavlog =
                            await DownloadLatestSimbriefNavlogAsync(
                                SimbriefID,
                                "initial connection");

                        ApplySimbriefNavlog(
                            latestSimbriefNavlog);

                        Logger.Debug(
                            "SimBrief data retrieved and parsed using JSON v2.");

                        response += " SIMBRIEF OK,";
                    }
                    catch (Exception ex)
                    {
                        Logger.Warn(
                            ex,
                            "Initial SimBrief download failed");

                        response +=
                            " SIMBRIEF ERROR: " +
                            FormatSimbriefUserFacingError(ex) +
                            ",";
                    }
                }

                if (UseFSUIPC)
                {
                    try
                    {
                        // FSUIPCClient's OpenConnection is synchronous and may
                        // wait on the simulator/IPC layer. Run it on a worker
                        // thread so a slow simulator cannot freeze the UI.
                        fsConnectionOpen =
                            await OpenFsuipcConnectionWithDiagnosticsAsync(
                                "initial connection");

                        if (fsConnectionOpen)
                        {
                            await RefreshFsuipcDataWithDiagnosticsAsync(
                                "initial connection");
                            response += "SIMULATOR OK.";
                        }
                        else
                        {
                            string fsuipcError = string.IsNullOrWhiteSpace(FSUIPCData.LastError) ? "CONNECTION FAILED" : FSUIPCData.LastError;
                            response += "SIMULATOR ERROR: " + fsuipcError;
                        }
                    }
                    catch (Exception ex)
                    {
                        string fsuipcError = !string.IsNullOrWhiteSpace(FSUIPCData.LastError) ? FSUIPCData.LastError : ex.Message;
                        response += "SIMULATOR ERROR: " + fsuipcError;
                    }
                }
                WriteMessage(response, "SYSTEM", "SYSTEM");
                BringEasyCpdlcWindowToFront();

            }
            else
            {
                if (CurrentATCUnit is not null)
                {
                    await SendCPDLCMessage(CurrentATCUnit, "CPDLC", String.Format("/data2/{0}//N/LOGOFF", messageOutCounter), false);
                }
                foreach (Contract _contract in contracts)
                {
                    await SendCPDLCMessage(_contract.sender, "ADS-C", "REJECT " + _contract.contractLength, false);
                }
                requestCancellationTokenSource?.Cancel();
                routeBlinkTimer.Stop();
                routeBlinkTicksRemaining = 0;
                routeBlinkAmber = false;
                callsignMismatchManualCheckInProgress = false;
                callsign = "";
                activeVatsimCallsign = string.Empty;
                pendingHoppieCallsign = string.Empty;
                preserveLoadedFlightPlanOnLiveUpdate = false;
                vatsimCallsignMismatchWarningActive = false;
                lastVatsimCallsignMismatchWarningUtc = DateTime.MinValue;
                pendingLogon = null;
                cpdlcSessionEstablished = false;
                CurrentATCUnit = null;
                ClearNextAtcUnitDisplay();
                loadedFlightPlanSignature = string.Empty;
                nextFlightPlanDetected = false;
                nextFlightPlanIgnored = false;
                nextFlightPlanSignature = string.Empty;
                nextFlightPlanDisplayText = string.Empty;
                lastNextFlightPlanCheckUtc = DateTime.MinValue;
                HideNextFlightPlanPrompt();
                UpdateCallsignDisplay();
                UpdateFlightPhaseBadge();
                SetAtisAutoRefresh(string.Empty, false);
                lock (atisHoverLock)
                {
                    pendingSilentAtisHoverTarget = string.Empty;
                    atisHoverCache.Clear();
                }
                lastPdcAvailabilityHintStation = string.Empty;
                preferArrivalStationAfterAirborne = false;
                lastWeatherFlightPlanSignature = string.Empty;
                flightPhaseEnrouteSeen = false;
                flightPhaseArrivalSeen = false;
                flightPhaseDepartureSeen = false;
                lastFlightPhaseSignature = string.Empty;
                ResetFlightPhaseTrendTracking();
                arrivalReloadReminderShown = false;
                arrivalReloadReminderStartUtc = DateTime.MinValue;
                arrivalReloadReminderSignature = string.Empty;
                nextFlightPlanDetected = false;
                nextFlightPlanIgnored = false;
                nextFlightPlanSignature = string.Empty;
                nextFlightPlanDisplayText = string.Empty;
                lastNextFlightPlanCheckUtc = DateTime.MinValue;
                datalinkStatusText = "PDC --";
                atisStatusText = BuildDotBadgeText("ATIS");
                atisAvailabilityState = "UNKNOWN";
                lastClearanceHoverText = string.Empty;
                SetClearanceStatus("CLR --");
                response = "DISCONNECTED CLIENT";
                vatsimData = new VATSIMRootobject();
                hoppieOnlineStations.Clear();
                hoppieOnlineStationsLoaded = false;
                userVATSIMData = new Pilot();
                simbriefData = new Navlog();
                fsConnectionOpen = FSUIPCData.CloseConnection();

                atcButton.Enabled = false;
                telexButton.Enabled = false;
                Connected = false;

                WriteMessage(response, "SYSTEM", "SYSTEM");

                }
            }
            finally
            {
                connectionAttemptInProgress = false;
                UpdateConnectionGatedControls();
            }
        }
