        private async Task StartEmbeddedSetupRollbackAsync()
        {
            Release release = embeddedSetupSelectedRollbackRelease;
            if (release == null)
            {
                ShowEmbeddedSetupUpdateRollbackPage(false);
                return;
            }

            try
            {
                Version selectedVersion = ParseReleaseVersion(release.TagName);
                if (selectedVersion == null || selectedVersion < MinimumSupportedRollbackVersion)
                {
                    MessageBox.Show(
                        "Rollback is only supported down to version 1.0.0.12.",
                        "EasyCPDLC Rollback",
                        MessageBoxButtons.OK,
                        MessageBoxIcon.Warning);
                    ShowEmbeddedSetupUpdateRollbackPage(true);
                    return;
                }

                ReleaseAsset asset = FindUpdateZipAsset(release);
                if (asset == null)
                {
                    MessageBox.Show(
                        "Selected release does not contain a trusted ZIP asset.",
                        "EasyCPDLC Rollback",
                        MessageBoxButtons.OK,
                        MessageBoxIcon.Warning);
                    ShowEmbeddedSetupUpdateRollbackPage(true);
                    return;
                }

                await DownloadAndInstallUpdateAsync(release, asset);
            }
            catch (Exception ex)
            {
                Logger.Debug("Rollback install failed: " + ex.Message);
                MessageBox.Show(
                    "Rollback failed:" + Environment.NewLine + ex.Message,
                    "EasyCPDLC Rollback",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Warning);
                ShowEmbeddedSetupUpdateRollbackPage(true);
            }
        }

        private async Task RunEmbeddedSetupUpdateCheckAsync()
        {
            try
            {
                embeddedSetupRollbackStatus = "CHECKING FOR UPDATE...";
                if (embeddedSetupPage == EmbeddedSetupPage.UpdateRollback)
                {
                    ShowEmbeddedSetupUpdateRollbackPage(false);
                }

                var client = new GitHubClient(new ProductHeaderValue("EasyCPDLC"));
                IReadOnlyList<Release> releases = await client.Repository.Release.GetAll(UpdateGithubOwner, UpdateGithubRepo);

                Release latest = releases
                    .Where(release => release != null && !release.Prerelease && !release.Draft)
                    .OrderByDescending(release => ParseReleaseVersion(release.TagName))
                    .FirstOrDefault();

                Version latestVersion = ParseReleaseVersion(latest?.TagName);
                Version currentVersion = ParseReleaseVersion(System.Windows.Forms.Application.ProductVersion);

                if (latest == null || latestVersion == null || currentVersion == null || latestVersion <= currentVersion)
                {
                    embeddedSetupRollbackStatus = "NO UPDATE AVAILABLE";
                }
                else
                {
                    ReleaseAsset asset = FindUpdateZipAsset(latest);
                    if (asset == null)
                    {
                        embeddedSetupRollbackStatus = "UPDATE HAS NO ZIP ASSET";
                    }
                    else
                    {
                        embeddedSetupSelectedRollbackRelease = latest;
                        await DownloadAndInstallUpdateAsync(latest, asset);
                        return;
                    }
                }
            }
            catch (Exception ex)
            {
                embeddedSetupRollbackStatus = "UPDATE CHECK FAILED";
                Logger.Debug("Embedded update check failed: " + ex.Message);
            }

            if (embeddedSetupPage == EmbeddedSetupPage.UpdateRollback)
            {
                ShowEmbeddedSetupUpdateRollbackPage(false);
            }
        }

        private void ShowEmbeddedSetupStylePage()
        {
            PrepareEmbeddedSetupPage(EmbeddedSetupPage.Style);
            if (DcduStyleManager.IsA220)
            {
                Panel a220Page = CreateEmbeddedSetupCanvas();
                RenderA220SetupStylePage(a220Page);
                return;
            }
            Panel page = CreateEmbeddedSetupCanvas();
            Font titleFont = EmbeddedSetupTitleFont();
            Font menuFont = EmbeddedSetupMenuFont();
            Font captionFont = EmbeddedSetupCaptionFont();
            Color color = MainPrimaryTextColor();

            AddEmbeddedSetupLabel(page, "DCDU STYLE", 0, 2, page.Width, 24, ContentAlignment.MiddleCenter, color, titleFont);
            AddEmbeddedSetupLabel(page, "<AIRBUS", 4, EmbeddedSetupLskTextY(page, 1), 220, 30, ContentAlignment.MiddleLeft, color, menuFont);
            AddEmbeddedSetupLabel(page, string.Equals(DcduStyleManager.CurrentStyle, DcduStyleManager.Airbus, StringComparison.OrdinalIgnoreCase) ? "ACTIVE" : string.Empty,
                page.Width - 160, EmbeddedSetupRightLskTextY(page, 1), 156, 30, ContentAlignment.MiddleRight, DcduTheme.Amber, menuFont);

            AddEmbeddedSetupLabel(page, "<BOEING", 4, EmbeddedSetupLskTextY(page, 2), 220, 30, ContentAlignment.MiddleLeft, color, menuFont);
            AddEmbeddedSetupLabel(page, string.Equals(DcduStyleManager.CurrentStyle, DcduStyleManager.Boeing, StringComparison.OrdinalIgnoreCase) ? "ACTIVE" : string.Empty,
                page.Width - 160, EmbeddedSetupRightLskTextY(page, 2), 156, 30, ContentAlignment.MiddleRight, DcduTheme.Amber, menuFont);

            AddEmbeddedSetupLabel(page, "<A220", 4, EmbeddedSetupLskTextY(page, 3), 220, 30, ContentAlignment.MiddleLeft, color, menuFont);
            AddEmbeddedSetupLabel(page, string.Equals(DcduStyleManager.CurrentStyle, DcduStyleManager.A220, StringComparison.OrdinalIgnoreCase) ? "ACTIVE" : string.Empty,
                page.Width - 160, EmbeddedSetupRightLskTextY(page, 3), 156, 30, ContentAlignment.MiddleRight, DcduTheme.Amber, menuFont);

            AddEmbeddedSetupLabel(page, "WINDOW SCALE", 4, EmbeddedSetupLskTextY(page, 4), 220, 30, ContentAlignment.MiddleLeft, color, menuFont);
            AddEmbeddedSetupLabel(page, WindowScalePercent.ToString(System.Globalization.CultureInfo.InvariantCulture) + "%>", page.Width - 160, EmbeddedSetupRightLskTextY(page, 4), 156, 30, ContentAlignment.MiddleRight, DcduTheme.Amber, menuFont);

            int styleHintY = Math.Min(
                EmbeddedSetupLskTextY(page, 4) + 30,
                EmbeddedSetupLskTextY(page, EmbeddedSetupBottomIndex()) - 22);
            AddEmbeddedSetupLabel(page, "STYLE/SCALE APPLIES IMMEDIATELY", 4, styleHintY, page.Width - 8, 20, ContentAlignment.MiddleLeft, DcduTheme.Amber, captionFont);
            AddEmbeddedSetupLabel(page, "<SETUP MENU", 4, EmbeddedSetupLskTextY(page, EmbeddedSetupBottomIndex()), 230, 30, ContentAlignment.MiddleLeft, color, menuFont);
        }

        private void CycleEmbeddedSetupWindowScale()
        {
            int[] values = { 100, 110, 120 };
            int current = WindowScalePercent;
            int next = values.FirstOrDefault(value => value > current);

            if (next <= 0)
            {
                next = values[0];
            }

            SetEmbeddedSetupWindowScale(next);
        }

        private void SetEmbeddedSetupWindowScale(int percent)
        {
            _ = SetEmbeddedSetupWindowScaleAsync(percent);
        }

        private async Task SetEmbeddedSetupWindowScaleAsync(int percent)
        {
            int normalizedPercent =
                NormalizeWindowScalePercent(
                    percent.ToString(
                        System.Globalization.CultureInfo.InvariantCulture));

            if (normalizedPercent == WindowScalePercent)
            {
                ShowEmbeddedSetupStylePage();
                return;
            }

            Size targetWindowSize =
                GetDcduTransitionTargetWindowSize(
                    DcduStyleManager.CurrentStyle,
                    normalizedPercent);

            await RunUiTransitionAsync(
                "APPLYING DISPLAY SCALE...",
                normalizedPercent.ToString(
                    System.Globalization.CultureInfo.InvariantCulture) + "%",
                () =>
                {
                    WindowScalePercent = normalizedPercent;
                    Properties.Settings.Default.Save();
                    RefreshWindowScaleUi();
                },
                targetWindowSize);
        }

        private void ResetScaleSensitivePopups()
        {
            void RemovePopupPanel(ref Panel panel)
            {
                if (panel == null)
                {
                    return;
                }

                try
                {
                    if (screenPanel != null && !screenPanel.IsDisposed && screenPanel.Controls.Contains(panel))
                    {
                        screenPanel.Controls.Remove(panel);
                    }

                    panel.Dispose();
                }
                catch (Exception ex)
                {
                    Logger.Debug("Popup reset failed: " + ex.Message);
                }
                finally
                {
                    panel = null;
                }
            }

            HideClearanceTimelinePopup();
            HideAtisAvailabilityPopup();
            HideAtisAutoPopup();
            HideQuickWxPopup();
            HidePdcQuickActionButton();
            HideCpdlcLogonPopup();
            HideAutoDeleteActionPopup();
            HideManualDeleteConfirmPopup();

            RemovePopupPanel(ref clearanceTimelinePopupPanel);
            clearanceTimelinePopupLabel = null;

            RemovePopupPanel(ref atisAvailabilityPopupPanel);
            atisAvailabilityPopupLabel = null;

            RemovePopupPanel(ref atisAutoPopupPanel);
            atisAutoPopupLabel = null;

            RemovePopupPanel(ref quickWxPopupPanel);

            RemovePopupPanel(ref pdcActionPopupPanel);
            RemovePopupPanel(ref cpdlcLogonPopupPanel);
            RemovePopupPanel(ref autoDeleteActionPopupPanel);
            RemovePopupPanel(ref manualDeleteConfirmPopupPanel);

            autoDeleteActionPopupMessage = null;
            autoDeleteActionPopupMenuLabel = null;
            manualDeleteConfirmPopupMessage = null;
        }

        private void RefreshWindowScaleUi()
        {
            int diagnosticToken =
                BeginUiDiagnosticOperation("Window scale/layout rebuild");

            try
            {
                // Keep the automatic base tied to monitor pixel resolution. This
                // call does not recursively refresh because refreshUi is false.
                UpdateAutomaticResolutionScaleFactor(false);

                float currentScaleFactor = WindowScaleFactor();

                // AutoScaleMode.None is intentional, so WinForms will not resize
                // fonts for us. Rescale every persistent explicit Font before the
                // style-specific layout is rebuilt.
                RescaleExistingControlFonts(
                    appliedWindowScaleFactor,
                    currentScaleFactor);

                textFont = CreateDpiStablePointFont("Consolas", 10.5f, FontStyle.Regular);
                textFontBold = CreateDpiStablePointFont("Consolas", 11.5f, FontStyle.Bold);
                RefreshMessageTextFonts();
                controlFont = CreateDpiStablePointFont("Segoe UI", 10.0f, FontStyle.Regular);
                controlFontBold = CreateDpiStablePointFont("Segoe UI", 10.0f, FontStyle.Bold);
                dataEntryFont = CreateDpiStablePointFont("Consolas", 13.0f, FontStyle.Bold);
                Font = controlFont;

                ResetScaleSensitivePopups();

                ApplyDisplayStyle();
                ApplyMessageFilter();
                RefreshVisibleMessageColors();
                ApplyMessageTextSizeSetting();
                RefreshMainDisplaySurface();

                // Setup, AOC/ATC, TELEX and message-preview pages are generated
                // controls in every DCDU style. ApplyDisplayStyle resets the shared
                // messageFormatPanel to its normal message-list bounds, so the
                // active page must always be recreated after a monitor/scale change.
                RebuildActiveGeneratedSurfaceAfterScale();

                appliedWindowScaleFactor = currentScaleFactor;

                PerformLayout();
                Invalidate(true);
                screenPanel?.PerformLayout();
                screenPanel?.Invalidate(true);
                outputTable?.PerformLayout();
                outputTable?.Invalidate(true);
            }
            catch (Exception ex)
            {
                Logger.Debug("Window scale refresh failed: " + ex.Message);
            }
            finally
            {
                EndUiDiagnosticOperation(diagnosticToken);
            }
        }

        private void RebuildActiveGeneratedSurfaceAfterScale()
        {
            // ApplyDisplayStyle deliberately restores the normal main-screen
            // layout first. Recreate whichever generated overlay was active so it
            // receives the new monitor factor, full screenPanel bounds and fresh
            // fonts instead of remaining trapped in the message-list rectangle.
            switch (embeddedSetupPage)
            {
                case EmbeddedSetupPage.MainMenu:
                    ShowEmbeddedSetupMainMenu();
                    return;
                case EmbeddedSetupPage.Account:
                    ShowEmbeddedSetupAccountPage();
                    return;
                case EmbeddedSetupPage.Options:
                    ShowEmbeddedSetupOptionsPage();
                    return;
                case EmbeddedSetupPage.AutoDeleteTimer:
                    ShowEmbeddedSetupAutoDeleteTimerPage();
                    return;
                case EmbeddedSetupPage.UpdateRollback:
                    ShowEmbeddedSetupUpdateRollbackPage(false);
                    return;
                case EmbeddedSetupPage.RollbackConfirm:
                    if (embeddedSetupSelectedRollbackRelease != null)
                    {
                        ShowEmbeddedSetupRollbackConfirmPage(embeddedSetupSelectedRollbackRelease);
                        return;
                    }
                    break;
                case EmbeddedSetupPage.Style:
                    ShowEmbeddedSetupStylePage();
                    return;
            }

            switch (airbusAocPage)
            {
                case AirbusAocPage.MainMenu: ShowAirbusAocMainMenu(); return;
                case AirbusAocPage.AtcRequestMenu: ShowAirbusAocAtcRequestMenu(); return;
                case AirbusAocPage.PreDepClearance: ShowAirbusAocPreDepClearance(); return;
                case AirbusAocPage.OceanicClearance: ShowAirbusAocOceanicClearance(); return;
                case AirbusAocPage.WxRequest: ShowAirbusAocWeatherRequest(false); return;
                case AirbusAocPage.AtisRequest: ShowAirbusAocWeatherRequest(true); return;
                case AirbusAocPage.FreeTextRequest: ShowAirbusAocFreeTextRequest(); return;
                case AirbusAocPage.AtcMainMenu: ShowAirbusAtcMainMenu(); return;
                case AirbusAocPage.AtcConnectionMenu: ShowAirbusAtcConnectionMenu(); return;
                case AirbusAocPage.AtcLogonRequest: ShowAirbusAtcLogonRequest(); return;
                case AirbusAocPage.AtcDirectRequest: ShowAirbusAtcDirectRequest(); return;
                case AirbusAocPage.AtcLevelRequest: ShowAirbusAtcLevelRequest(); return;
                case AirbusAocPage.AtcSpeedRequest: ShowAirbusAtcSpeedRequest(); return;
                case AirbusAocPage.AtcWhenCanWeRequest: ShowAirbusAtcWhenCanWeRequest(); return;
                case AirbusAocPage.AtcTextRequest:
                    ShowAirbusAtcTextRequest(
                        "ATC REQUEST",
                        GetStoredAirbusAocInput(
                            AirbusAocPage.AtcTextRequest,
                            AirbusAocInputFreeText,
                            string.Empty));
                    return;
                case AirbusAocPage.SendConfirm:
                    ShowAirbusAocSendConfirmPage();
                    return;
            }

            switch (boeingTelexPage)
            {
                case BoeingTelexPage.Menu: ShowBoeingTelexMenu(); return;
                case BoeingTelexPage.FreeText: ShowBoeingTelexFreeText(); return;
                case BoeingTelexPage.Metar: ShowBoeingTelexMetarRequest(); return;
                case BoeingTelexPage.Atis: ShowBoeingTelexAtisRequest(); return;
                case BoeingTelexPage.AtcMainMenu: ShowBoeingAtcMainMenu(); return;
                case BoeingTelexPage.AtcPreDepClearance: ShowBoeingAtcPreDepClearance(); return;
                case BoeingTelexPage.AtcOceanicClearance: ShowBoeingAtcOceanicClearance(); return;
                case BoeingTelexPage.AtcDirectRequest: ShowBoeingAtcDirectRequest(); return;
                case BoeingTelexPage.AtcLevelRequest: ShowBoeingAtcLevelRequest(); return;
                case BoeingTelexPage.AtcSpeedRequest: ShowBoeingAtcSpeedRequest(); return;
                case BoeingTelexPage.AtcWhenCanWeRequest: ShowBoeingAtcWhenCanWeRequest(); return;
                case BoeingTelexPage.AtcConnectionMenu: ShowBoeingAtcConnectionMenu(); return;
                case BoeingTelexPage.AtcLogonRequest: ShowBoeingAtcLogonRequest(); return;
                case BoeingTelexPage.SendConfirm: ShowBoeingTelexSendConfirmPage(); return;
            }

            if (previewMessage != null && !previewMessage.IsDisposed)
            {
                ShowStyledMessagePreview(
                    previewMessage,
                    new List<System.Windows.Forms.Label>());
                return;
            }

            if (DcduStyleManager.IsA220)
            {
                ApplyA220MainScreenLayout();
            }
        }

        private void SetEmbeddedSetupDisplayStyle(string style)
        {
            _ = SetEmbeddedSetupDisplayStyleAsync(style);
